function normalizeIp(rawIp) {
  const s = String(rawIp || '').trim();
  if (!s) return 'unknown';
  return s.replace(/^::ffff:/i, '');
}

function getRealIP(req) {
  if (!req) return 'unknown';
  if (process.env.TRUST_CLOUDFLARE === 'true' && req.headers && req.headers['cf-connecting-ip']) {
    return normalizeIp(String(req.headers['cf-connecting-ip']).split(',')[0]);
  }
  if (typeof req.ip === 'string' && req.ip) {
    return normalizeIp(req.ip);
  }
  const xff = req.headers && req.headers['x-forwarded-for'];
  if (typeof xff === 'string' && xff.trim()) {
    const hops = xff.split(',').map(s => s.trim()).filter(Boolean);
    if (hops.length > 0) return normalizeIp(hops[hops.length - 1]);
  }
  return normalizeIp((req.socket && req.socket.remoteAddress) || 'unknown');
}

function escapeRegex(str) {
  return String(str || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function escapeHtmlAttr(str) {
  return String(str == null ? '' : str).replace(/[&<>"'`]/g, c => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;', '`': '&#96;'
  }[c]));
}

function safeHttpsUrl(url) {
  const s = String(url || '').trim();
  if (!s) return '';
  try {
    const u = new URL(s);
    if (u.protocol !== 'https:') return '';
    return u.toString();
  } catch (_) {
    return '';
  }
}

function safeJsonForScript(obj) {
  return JSON.stringify(obj)
    .replace(/</g, '\\u003c')
    .replace(/>/g, '\\u003e')
    .replace(/\//g, '\\/')
    .replace(/\u2028/g, '\\u2028')
    .replace(/\u2029/g, '\\u2029');
}

function timingSafeCompare(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  const bufA = Buffer.from(a);
  const bufB = Buffer.from(b);
  if (bufA.length !== bufB.length) return false;
  return crypto.timingSafeEqual(bufA, bufB);
}

// ============================================================================
// MULTI-TIER DDOS PROTECTION & MEMORY-BOUNDED RATE LIMITING ENGINE
// ============================================================================
const MAX_RATE_ENTRIES = 20000;
const ddosTempBans = new Map(); // ip -> { until, violations, windowStart }
const allRateLimitStores = [];
const blacklistedIpCache = { set: new Set(), lastRefresh: 0 };
const blacklistedUsernameCache = { set: new Set(), lastRefresh: 0 };
const BLACKLIST_LANDING_NOTICE_MSG = 'You Are Permananetly Blacklisted Please Remove Yourself From the Website Its Currently Useless For you.';

function pruneBoundedMap(map, isExpiredFn) {
  if (map.size < MAX_RATE_ENTRIES) return;
  const now = Date.now();
  for (const [k, v] of map) {
    if (isExpiredFn(v, now)) map.delete(k);
    if (map.size < MAX_RATE_ENTRIES * 0.8) return;
  }
  const dropCount = Math.max(1, Math.floor(map.size * 0.25));
  let dropped = 0;
  for (const k of map.keys()) {
    map.delete(k);
    if (++dropped >= dropCount) break;
  }
}

function recordDdosViolation(ip, req) {
  if (!ip || ip === 'unknown') return;
  const now = Date.now();
  pruneBoundedMap(ddosTempBans, (v, t) => (!v.until || t > v.until) && (t - (v.windowStart || 0) > 120000));
  let entry = ddosTempBans.get(ip);
  if (!entry || (now - entry.windowStart > 60000 && now > (entry.until || 0))) {
    entry = { violations: 1, windowStart: now, until: 0 };
  } else {
    entry.violations = (entry.violations || 0) + 1;
  }
  let banStarted = false;
  if (entry.violations >= 6 && now > (entry.until || 0)) {
    entry.until = now + 10 * 60 * 1000; // 10-minute automatic traffic block
    entry.violations = 0;
    banStarted = true;
  }
  ddosTempBans.set(ip, entry);
  // Log and notify once when the block begins, not for every request refused by it.
  if (banStarted && req && typeof recordCanaryEvent === 'function') {
    recordCanaryEvent(req, 'ddos_temp_ban_started', { durationSec: 600 }).catch(() => {});
  }
}

// Routes used by the Roblox/game loader are explicitly trusted by the generic
// website/canary traffic guards. Their own key, session, HWID, and payload checks
// still run inside the route handlers below.
function isGameLoaderRequest(req) {
  if (!req) return false;
  const method = String(req.method || 'GET').toUpperCase();
  const routePath = String(req.path || '/').toLowerCase().split('?')[0];
  if (method === 'GET' && (
    routePath === '/loader.lua' ||
    routePath === '/loader' ||
    routePath === '/settings.lua' ||
    routePath === '/cloudconfig' ||
    routePath === '/api/get-active-config' ||
    routePath === '/api/get-configs-list' ||
    /^\/api\/get-config\/[^/]+$/.test(routePath)
  )) return true;
  if (method === 'POST' && (
    routePath === '/api/vm-key' ||
    routePath === '/api/validate' ||
    routePath === '/api/get-script' ||
    routePath === '/api/heartbeat' ||
    routePath === '/api/set-active-config' ||
    routePath === '/cloudconfig/save'
  )) return true;
  return false;
}

function createRateLimiter(windowMsOrOpts = 60000, maxRequestsArg = 60) {
  const opts = (typeof windowMsOrOpts === 'object' && windowMsOrOpts !== null)
    ? windowMsOrOpts
    : { windowMs: windowMsOrOpts, max: maxRequestsArg };
  const windowMs = Math.max(1000, Number(opts.windowMs) || 60000);
  const max = Math.max(1, Number(opts.max) || 60);
  const message = opts.message || 'Too many requests, please slow down.';
  const countAsDdosViolation = opts.countAsDdosViolation !== false;
  const keyFn = typeof opts.keyFn === 'function' ? opts.keyFn : (req) => getRealIP(req);
  const skipFn = typeof opts.skip === 'function' ? opts.skip : null;
  const store = new Map();
  allRateLimitStores.push({ store, windowMs });

  return (req, res, next) => {
    if (skipFn && skipFn(req)) return next();
    const key = String(keyFn(req) || 'unknown');
    const now = Date.now();
    pruneBoundedMap(store, (rec, t) => (t - rec.startTime) > windowMs);
    let record = store.get(key);
    if (!record || (now - record.startTime) >= windowMs) {
      record = { startTime: now, count: 1 };
      store.set(key, record);
      res.setHeader('X-RateLimit-Limit', String(max));
      res.setHeader('X-RateLimit-Remaining', String(Math.max(0, max - 1)));
      res.setHeader('X-RateLimit-Reset', String(Math.ceil((now + windowMs) / 1000)));
      return next();
    }
    record.count++;
    const remaining = Math.max(0, max - record.count);
    const resetMs = Math.max(1000, (record.startTime + windowMs) - now);
    res.setHeader('X-RateLimit-Limit', String(max));
    res.setHeader('X-RateLimit-Remaining', String(remaining));
    res.setHeader('X-RateLimit-Reset', String(Math.ceil((record.startTime + windowMs) / 1000)));
    if (record.count > max) {
      res.setHeader('Retry-After', String(Math.ceil(resetMs / 1000)));
      if (typeof recordCanaryEvent === 'function' && !record.canaryAlerted) {
        record.canaryAlerted = true;
        recordCanaryEvent(req, 'rate_limit_exceeded', { limit: max, windowMs, count: record.count }).catch(() => {});
      }
      if (countAsDdosViolation) recordDdosViolation(getRealIP(req), req);
      if (req.path && req.path.startsWith('/api/')) {
        return res.status(429).json({ error: message, retryAfterSec: Math.ceil(resetMs / 1000) });
      }
      return res.status(429).send('Too many requests. Please slow down and try again shortly.');
    }
    next();
  };
}

setInterval(() => {
  const now = Date.now();
  for (const { store, windowMs } of allRateLimitStores) {
    for (const [k, rec] of store) {
      if ((now - rec.startTime) >= windowMs) store.delete(k);
    }
  }
  for (const [ip, rec] of ddosTempBans) {
    if ((!rec.until || now > rec.until) && (now - (rec.windowStart || 0) > 120000)) {
      ddosTempBans.delete(ip);
    }
  }
}, 5 * 60 * 1000);

