const onlineUsers = new Map();
const activeSessions = new Map();
const accountVaults = new Map(); // vaultId -> [{ username, role, avatar, sessionToken, updatedAt }]
const onlineWebUsers = new Map();
const hiddenOnlineUsers = new Set();
const csrfTokens = new Map();
const pendingDiscordLogins = new Map();
const pendingDiscordOAuthStates = new Map();

function signCsrfTokenValue(nonce) {
  const sig = crypto.createHmac('sha256', LOCKOUT_SECRET).update('csrf:' + String(nonce)).digest('base64url').slice(0, 24);
  return `${nonce}.${sig}`;
}

function isValidCsrfTokenValue(token) {
  if (!token || typeof token !== 'string') return false;
  if (csrfTokens.has(token)) return true;
  const dotIdx = token.indexOf('.');
  if (dotIdx <= 0) return false;
  const nonce = token.slice(0, dotIdx);
  const sig = token.slice(dotIdx + 1);
  if (!nonce || !sig) return false;
  const expected = crypto.createHmac('sha256', LOCKOUT_SECRET).update('csrf:' + nonce).digest('base64url').slice(0, 24);
  return timingSafeCompare(sig, expected);
}

function generateCsrfToken(req, res) {
  let csrf = req.cookies?.csrf_token;
  if (!isValidCsrfTokenValue(csrf)) {
    csrf = signCsrfTokenValue(crypto.randomBytes(24).toString('hex'));
    csrfTokens.set(csrf, Date.now());
    res.cookie('csrf_token', csrf, {
      httpOnly: false,
      secure: isSecureCookieEnv(),
      sameSite: 'Lax',
      path: '/'
    });
  } else if (!csrfTokens.has(csrf)) {
    csrfTokens.set(csrf, Date.now());
  }
  return csrf;
}

function verifyCsrfToken(req, res, next) {
  const isMiddleware = typeof next === 'function';
  const pass = () => (isMiddleware ? next() : true);
  const fail = () => {
    if (isMiddleware) {
      return res.status(403).json({ error: 'Invalid or missing CSRF token' });
    }
    return false;
  };

  if (req.method === 'GET' || req.method === 'HEAD' || req.method === 'OPTIONS') {
    return pass();
  }

  // Exempt non-browser / token-authenticated script & bot endpoints
  const p = req.path || '';
  if (
    p === '/api/login' ||
    p === '/api/register' ||
    p === '/api/logout' ||
    p === '/api/validate' ||
    p === '/api/vm-key' ||
    p === '/api/get-script' ||
    p === '/api/heartbeat' ||
    p === '/api/set-active-config' ||
    p === '/cloudconfig/save' ||
    p.startsWith('/api/bot/') ||
    p.startsWith('/api/admin-portal/') ||
    req.headers['x-api-key'] ||
    req.headers['x-auth-token']
  ) {
    return pass();
  }

  const tokenFromHeader = req.headers['x-csrf-token'];
  const tokenFromCookie = req.cookies?.csrf_token;
  if (tokenFromHeader && typeof tokenFromHeader === 'string' && isValidCsrfTokenValue(tokenFromHeader)) {
    if (!tokenFromCookie || timingSafeCompare(tokenFromHeader, tokenFromCookie)) {
      return pass();
    }
  }

  // Strict same-origin Referer/Origin fallback for authenticated session requests
  const origin = req.headers['origin'] || req.headers['referer'] || '';
  const host = req.get('host') || '';
  const authToken = req.cookies?.clover_session || req.cookies?.prey_session || req.cookies?.token;
  if (authToken && host && origin) {
    let originHost = '';
    try { originHost = new URL(origin).host.toLowerCase(); } catch (_) {}
    if (originHost && originHost === String(host).toLowerCase()) {
      return pass();
    }
  }

  return fail();
}


setInterval(() => {
  const now = Date.now();
  for (const [token, time] of csrfTokens) {
    if (now - time > 24 * 60 * 60 * 1000) csrfTokens.delete(token);
  }
  for (const [token, sess] of activeSessions) {
    if (sess && sess.expiresAt && now > sess.expiresAt) {
      activeSessions.delete(token);
    }
  }
}, 60 * 60 * 1000);

function sanitizePlainValue(val, depth = 0) {
  if (depth > 12 || val === null || val === undefined) return val;
  if (Array.isArray(val)) {
    for (let i = 0; i < val.length; i++) {
      val[i] = sanitizePlainValue(val[i], depth + 1);
    }
    return val;
  }
  if (typeof val === 'object') {
    for (const k of Object.keys(val)) {
      if (k.startsWith('$') || k.includes('\0') || k === '__proto__' || k === 'constructor' || k === 'prototype') {
        delete val[k];
      } else {
        val[k] = sanitizePlainValue(val[k], depth + 1);
      }
    }
    return val;
  }
  return val;
}

function sanitizeNoSqlPayload(req, res, next) {
  if (req.body && typeof req.body === 'object') sanitizePlainValue(req.body);
  if (req.query && typeof req.query === 'object') sanitizePlainValue(req.query);
  if (req.params && typeof req.params === 'object') sanitizePlainValue(req.params);
  next();
}

// Passive canary telemetry. A non-browser User-Agent by itself is not an attack.
// Only higher-confidence probes are sent to the alert feed; routine checks stay quiet.
const canaryUnknownApiHits = new Map();

function isRepeatedUnknownApiProbe(ip, routePath) {
  const now = Date.now();
  const key = `${String(ip || 'unknown')}:${String(routePath || '/')}`;
  pruneBoundedMap(canaryUnknownApiHits, (entry, time) => (time - entry.windowStart) > 60000);
  let entry = canaryUnknownApiHits.get(key);
  if (!entry || (now - entry.windowStart) > 60000) {
    entry = { windowStart: now, count: 1, alerted: false };
  } else {
    entry.count++;
  }
  if (entry.count >= 5 && !entry.alerted) {
    entry.alerted = true;
    canaryUnknownApiHits.set(key, entry);
    return true;
  }
  canaryUnknownApiHits.set(key, entry);
  return false;
}

const rapidLoginAttempts = new Map();
function recordRapidLoginAttempt(ip) {
  const cleanIp = String(ip || 'unknown');
  const now = Date.now();
  pruneBoundedMap(rapidLoginAttempts, (v, t) => (t - v.windowStart) > 20000);
  let rec = rapidLoginAttempts.get(cleanIp);
  if (!rec || (now - rec.windowStart) > 20000) {
    rec = { windowStart: now, count: 1, alerted: false };
  } else {
    rec.count += 1;
  }
  const triggered = rec.count >= 4 && !rec.alerted;
  if (triggered) rec.alerted = true;
  rapidLoginAttempts.set(cleanIp, rec);
  return { triggered, count: rec.count, windowSec: 20 };
}

app.use((req, res, next) => {
  const routePath = String(req.path || '/').toLowerCase();
  const ua = String(req.headers && req.headers['user-agent'] || '').slice(0, 240);
  const method = String(req.method || 'GET').toUpperCase();
  const signals = [];
  const trustedGameLoaderRequest = isGameLoaderRequest(req);
  const isBotRoute = routePath.startsWith('/api/bot/');
  const isKnownDecoyRoute = /^\/(admin-panel|admin-login|administrator|wp-admin|wp-login\.php|cpanel|staff-panel|internal\/admin|console\/admin|panel\/admin|canary-admin)(?:\/|$)/i.test(routePath);
  const adminPath = routePath.includes('/admin') || routePath.includes('/administrator');
  const canaryApiPath = routePath.startsWith('/api/admin-portal/');
  const commandLineClient = /\b(curl|wget|httpie|python-requests|python-urllib|go-http-client|libwww-perl|powershell|invoke-webrequest)\b/i.test(ua);

  if (/\b(sqlmap|nikto|nmap|masscan|zgrab|nuclei|dirbuster|gobuster|ffuf|wpscan|burp|hydra|acunetix|feroxbuster)\b/i.test(ua)) {
    signals.push('scanner_or_recon_user_agent');
  }
  if (/\.(env|git|svn|hg)(?:\/|$)|\/(?:wp-admin|wp-login\.php|phpmyadmin|pma|actuator|server-status|\.well-known\/security|vendor\/phpunit|cgi-bin|backup|backups|config\.php)(?:\/|$)/i.test(routePath)) {
    signals.push('sensitive_path_probe');
  }

  const supportedMethods = ['GET', 'HEAD', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'];
  if (!supportedMethods.includes(method) && (routePath.startsWith('/api/') || adminPath)) {
    signals.push('unusual_http_method');
  }

  res.once('finish', () => {
    const status = Number(res.statusCode) || 0;

    if (status === 404 && routePath.startsWith('/api/') && !trustedGameLoaderRequest &&
        isRepeatedUnknownApiProbe(getRealIP(req), routePath)) {
      signals.push('unknown_api_route');
    }
    if ((status === 401 || status === 403) && adminPath && !isKnownDecoyRoute) {
      signals.push('blocked_admin_route_request');
    }
    if (status === 401 && canaryApiPath) {
      signals.push('unauthenticated_canary_api_probe');
    }
    if (status === 302 && adminPath && !isKnownDecoyRoute) {
      signals.push('admin_route_login_redirect');
    }

    if (commandLineClient && !trustedGameLoaderRequest && !isBotRoute) {
      signals.push('command_line_http_client');
    }

    if (!signals.length) return;

    const event = signals.includes('scanner_or_recon_user_agent')
      ? 'scanner_request'
      : (signals.includes('blocked_admin_route_request') ||
         signals.includes('unauthenticated_canary_api_probe') ||
         signals.includes('sensitive_path_probe') ||
         signals.includes('unknown_api_route') ||
         signals.includes('unusual_http_method') ||
         signals.includes('admin_route_login_redirect'))
        ? 'suspicious_request'
        : (signals.includes('command_line_http_client') ? 'command_line_http_request' : null);
    if (!event || typeof recordCanaryEvent !== 'function') return;

    recordCanaryEvent(req, event, {
      signals: signals.join(','),
      statusCode: status,
      userAgentClass: signals.includes('scanner_or_recon_user_agent') ? 'scanner' :
        (commandLineClient ? 'command-line-client' : 'other')
    }).catch(() => {});
  });
  next();
});

