function setSecureSessionCookie(res, token, rememberMe = true) {
  const isProd = isSecureCookieEnv();
  const cookieOpts = {
    httpOnly: true,
    secure: isProd,
    sameSite: 'Lax',
    path: '/'
  };
  if (rememberMe) {
    cookieOpts.maxAge = 30 * 24 * 60 * 60 * 1000; // 30 days
  }
  res.cookie('clover_session', token, cookieOpts);
  res.cookie('prey_session', token, cookieOpts);
  res.cookie('token', token, cookieOpts);
  if (rememberMe) {
    res.cookie('clover_remember', '1', { ...cookieOpts, httpOnly: false });
  } else {
    res.clearCookie('clover_remember', { path: '/' });
  }
}

const SESSION_DEVICE_COOKIE = 'clover_dev_bind';

function computeSessionBrowserHash(req) {
  const h = (req && req.headers) ? req.headers : {};
  const ua = String(h['user-agent'] || '').trim().toLowerCase();
  const lang = String(h['accept-language'] || '').split(',')[0].trim().toLowerCase();
  const raw = [ua, lang].join('|');
  return crypto.createHash('sha256').update('clover_browser_v2:' + raw).digest('hex');
}

function createSessionDeviceBinding() {
  const secret = crypto.randomBytes(32).toString('hex');
  const sig = crypto.createHmac('sha256', LOCKOUT_SECRET).update('dev_bind:' + secret).digest('base64url');
  const deviceBindHash = crypto.createHash('sha256').update('dev_bind_hash:' + secret).digest('hex');
  return {
    cookieValue: secret + '.' + sig,
    deviceBindHash
  };
}

function readVerifiedDeviceBindHash(req) {
  let rawCookie = '';
  if (req && req.cookies && typeof req.cookies[SESSION_DEVICE_COOKIE] === 'string') {
    rawCookie = req.cookies[SESSION_DEVICE_COOKIE];
  } else if (req && req.headers && req.headers.cookie && typeof parseCookieHeader === 'function') {
    const parsed = parseCookieHeader(req.headers.cookie);
    rawCookie = parsed && parsed[SESSION_DEVICE_COOKIE] ? parsed[SESSION_DEVICE_COOKIE] : '';
  }
  if (!rawCookie || typeof rawCookie !== 'string') return '';
  const dotIdx = rawCookie.indexOf('.');
  if (dotIdx <= 0) return '';
  const secret = rawCookie.slice(0, dotIdx).trim();
  const sig = rawCookie.slice(dotIdx + 1).trim();
  if (!/^[a-f0-9]{64}$/i.test(secret) || !sig) return '';
  const expectedSig = crypto.createHmac('sha256', LOCKOUT_SECRET).update('dev_bind:' + secret).digest('base64url');
  if (!timingSafeCompare(sig, expectedSig)) return '';
  return crypto.createHash('sha256').update('dev_bind_hash:' + secret).digest('hex');
}

function setSessionDeviceBindCookie(res, cookieValue, rememberMe = true) {
  if (!res || typeof res.cookie !== 'function' || !cookieValue) return;
  res.cookie(SESSION_DEVICE_COOKIE, cookieValue, {
    httpOnly: true,
    secure: isSecureCookieEnv(),
    sameSite: 'Lax',
    path: '/',
    maxAge: rememberMe ? (30 * 24 * 60 * 60 * 1000) : (24 * 60 * 60 * 1000)
  });
}

function clearSessionDeviceBindCookie(res) {
  if (!res || typeof res.clearCookie !== 'function') return;
  res.clearCookie(SESSION_DEVICE_COOKIE, {
    httpOnly: true,
    secure: isSecureCookieEnv(),
    sameSite: 'Lax',
    path: '/'
  });
}

function buildActiveSessionRecord(dbSess, overrides = {}) {
  const tok = String((dbSess && dbSess.token) || overrides.token || '');
  return {
    username: (overrides.username !== undefined ? overrides.username : dbSess?.username) || '',
    role: (overrides.role !== undefined ? overrides.role : dbSess?.role) || 'customer',
    key: (overrides.key !== undefined ? overrides.key : dbSess?.key) || '',
    rememberMe: overrides.rememberMe !== undefined ? Boolean(overrides.rememberMe) : (dbSess?.rememberMe !== false),
    expiresAt: overrides.expiresAt !== undefined
      ? Number(overrides.expiresAt)
      : (dbSess?.expiresAt ? new Date(dbSess.expiresAt).getTime() : 0),
    loaderToken: (overrides.loaderToken || dbSess?.loaderToken || (tok ? deriveSessionLoaderToken(tok) : '')),
    browserHash: String(overrides.browserHash !== undefined ? overrides.browserHash : (dbSess?.browserHash || '')),
    deviceBindHash: String(overrides.deviceBindHash !== undefined ? overrides.deviceBindHash : (dbSess?.deviceBindHash || '')),
    boundIp: String(overrides.boundIp !== undefined ? overrides.boundIp : (dbSess?.boundIp || '')),
    discordAvatar: overrides.discordAvatar !== undefined ? overrides.discordAvatar : (dbSess?.discordAvatar || ''),
    discordUsername: overrides.discordUsername !== undefined ? overrides.discordUsername : (dbSess?.discordUsername || ''),
    discordDisplayName: overrides.discordDisplayName !== undefined ? overrides.discordDisplayName : (dbSess?.discordDisplayName || ''),
    avatar: overrides.avatar !== undefined ? overrides.avatar : (dbSess?.avatar || dbSess?.discordAvatar || '')
  };
}

function verifySessionBinding(req, session) {
  const q = (req && req.query) || {};
  if (q.session || q.sessionId || q.clover_session || q.prey_session) {
    return { ok: false, reason: 'shared_session_link_blocked' };
  }
  if (!session) {
    return { ok: false, reason: 'missing_session' };
  }
  if (session.browserHash) {
    const reqBrowserHash = computeSessionBrowserHash(req);
    if (!timingSafeCompare(String(session.browserHash), reqBrowserHash)) {
      return { ok: false, reason: 'browser_mismatch' };
    }
  }
  if (session.deviceBindHash) {
    const reqBindHash = readVerifiedDeviceBindHash(req);
    if (!reqBindHash || !timingSafeCompare(String(session.deviceBindHash), reqBindHash)) {
      return { ok: false, reason: 'device_bind_mismatch' };
    }
  }
  return { ok: true };
}

function isBrowserNavigationToLoader(req) {
  const h = (req && req.headers) ? req.headers : {};
  const fetchMode = String(h['sec-fetch-mode'] || '').trim().toLowerCase();
  const fetchDest = String(h['sec-fetch-dest'] || '').trim().toLowerCase();
  const accept = String(h['accept'] || '').trim().toLowerCase();
  if (fetchMode === 'navigate' || fetchDest === 'document') return true;
  if (accept.includes('text/html')) return true;
  return false;
}

async function reportSessionHijackBlocked(req, session, reason) {
  if (typeof recordCanaryEvent !== 'function') return;
  try {
    await recordCanaryEvent(req, 'session_share_or_hijack_blocked', {
      targetAccount: session?.username || 'unknown',
      reason: String(reason || 'binding_mismatch'),
      boundIp: session?.boundIp || '',
      attemptedIp: getRealIP(req)
    });
  } catch (_) {}
}

function getOrCreateVaultId(req, res) {
  let vid = req && req.cookies ? req.cookies.clover_vault : '';
  if (!vid || typeof vid !== 'string' || !/^[a-f0-9]{64}$/.test(vid)) {
    vid = crypto.randomBytes(32).toString('hex');
    if (res && typeof res.cookie === 'function') {
      res.cookie('clover_vault', vid, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'Lax',
        path: '/',
        maxAge: 30 * 24 * 60 * 60 * 1000
      });
    }
  }
  return vid;
}

async function getVaultAccounts(vaultId) {
  if (!vaultId) return [];
  let list = accountVaults.get(vaultId);
  if (!list && typeof AccountVault !== 'undefined' && mongoose.connection.readyState === 1) {
    try {
      const doc = await AccountVault.findOne({ vaultId }).lean();
      if (doc && Array.isArray(doc.accounts)) {
        list = doc.accounts.map(a => ({
          username: a.username,
          role: a.role || 'customer',
          avatar: a.avatar || '',
          sessionToken: a.sessionToken || '',
          updatedAt: Number(a.updatedAt) || Date.now()
        }));
        accountVaults.set(vaultId, list);
      }
    } catch (_) {}
  }
  return Array.isArray(list) ? list : [];
}

async function saveSessionToVault(req, res, entry) {
  if (!entry || !entry.username || !entry.sessionToken) return;
  const vaultId = getOrCreateVaultId(req, res);
  let list = await getVaultAccounts(vaultId);
  const targetLower = String(entry.username).trim().toLowerCase();
  list = list.filter(a => a && a.username && a.username.toLowerCase() !== targetLower);
  list.unshift({
    username: String(entry.username).trim(),
    role: String(entry.role || 'customer'),
    avatar: String(entry.avatar || ''),
    sessionToken: String(entry.sessionToken),
    updatedAt: Date.now()
  });
  if (list.length > 10) list = list.slice(0, 10);
  accountVaults.set(vaultId, list);
  if (typeof AccountVault !== 'undefined' && mongoose.connection.readyState === 1) {
    AccountVault.findOneAndUpdate(
      { vaultId },
      { vaultId, accounts: list, updatedAt: new Date() },
      { upsert: true }
    ).catch(() => {});
  }
}

