function buildHardenedAsset(raw, contentType, prefix, ext, kind) {
  let body = String(raw || '');
  try {
    if (kind === 'js-vm') {
      const vmCandidate = compileJsToVmBundle(body, prefix);
      new Function(vmCandidate);
      if (vmCandidate && vmCandidate.length > 0) body = vmCandidate;
    } else {
      const candidate = kind === 'css' ? minifyCssSafe(body) : (kind === 'js' ? minifyJsSafe(body) : body);
      if (kind === 'js') {
        new Function(candidate);
        if (candidate.length > 0) body = candidate;
      } else if (kind === 'css' && candidate.length > 0) {
        body = candidate;
      }
    }
  } catch (e) {
    console.warn(`[Asset Minifier] Falling back to raw source for ${prefix}.${ext}:`, e?.message || e);
  }
  const hashShort = crypto.createHash('sha256').update(body, 'utf8').digest('hex').slice(0, 12);
  const sri = 'sha384-' + crypto.createHash('sha384').update(body, 'utf8').digest('base64');
  const url = `/assets/${prefix}.${hashShort}.min.${ext}`;
  const etag = `"${hashShort}"`;
  return { body, contentType, hashShort, sri, url, etag };
}

function sendHardenedAsset(asset, immutable = true) {
  return (req, res) => {
    res.setHeader('Content-Type', asset.contentType);
    res.setHeader('ETag', asset.etag);
    res.setHeader('Cross-Origin-Resource-Policy', 'same-origin');
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('Cache-Control', immutable ? 'public, max-age=31536000, immutable' : 'no-cache, must-revalidate');
    const inm = String(req.headers['if-none-match'] || '').trim();
    if (inm && inm === asset.etag) {
      return res.status(304).end();
    }
    return res.send(asset.body);
  };
}

