function sanitizeInput(str) {
  if (typeof str !== 'string') return '';
  return str.replace(/[<>&"']/g, c => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;', "'": "&#39;" }[c] || c)).trim().substring(0, 500);
}
function validateUsername(username) {
  if (!username || typeof username !== 'string') return false;
  const clean = username.trim();
  return clean.length >= 3 && clean.length <= 30 && /^[a-zA-Z0-9_]+$/.test(clean);
}


const SERVER_COMMON_PASSWORDS = new Set([
  'password', 'password123', '12345678', '123456789', 'qwerty123', 'admin123',
  'welcome1', 'welcome123', 'letmein123', 'iloveyou1', 'clover123', 'clover2026',
  'pass1234', 'testing123', 'hunter22', 'monkey123', 'dragon123', 'master123'
]);

function isCommonPassword(p) {
  if (!p || typeof p !== 'string') return true;
  return SERVER_COMMON_PASSWORDS.has(p.toLowerCase().trim());
}

function validatePassword(password) {
  if (!password || typeof password !== 'string') return false;
  if (password.length < 8 || password.length > 128) return false;
  const hasUpper = /[A-Z]/.test(password);
  const hasLower = /[a-z]/.test(password);
  const hasNumber = /[0-9]/.test(password);
  const hasSpecial = /[!@#$%^&*(),.?":{}|<_\-]/.test(password);
  return hasUpper && hasLower && hasNumber && hasSpecial;
}
function validateLicenseKey(key) {
  if (!key || typeof key !== 'string') return false;
  const clean = key.trim();
  return clean.length >= 4 && clean.length <= 100 && /^[a-zA-Z0-9_\-]+$/.test(clean);
}


