let dbConnectPromise = null;
let dbStartupTasksDone = false;

async function ensureDbConnected(timeoutMs = 8000) {
  if (mongoose.connection.readyState === 1) return true;
  if (!dbConnectPromise) {
    dbConnectPromise = Promise.resolve().then(() => mongoose.connect(MONGODB_URI, {
      serverSelectionTimeoutMS: 8000,
      connectTimeoutMS: 8000,
      maxPoolSize: 10
    })).then(async () => {
      if (mongoose.connection.readyState !== 1) {
        await new Promise(resolve => setImmediate(resolve));
      }
      if (mongoose.connection.readyState === 1 && !dbStartupTasksDone) {
        dbStartupTasksDone = true;
        console.log('[Clover] Connected to MongoDB');
        migratePastKeysToClover();

        try {
          // Purge fake mock marketplace seeds so only genuine user-created configs exist
          await MarketplaceConfig.deleteMany({
            $or: [
              { author: { $in: ['prey_dev', 'reaper_hc', 'clover_team', 'velocity_dh', 'nightfall'] } },
              { fingerprint: { $regex: /^FPR-(7D891E0AC42B890F|A94BC104938D7122|3C289BF013A987FE|F819A20B3392E104|B581C99042FEE831)/ } }
            ]
          });
          console.log('[Clover] Pure marketplace active. Zero mock data.');
        } catch (e) { }

        try {
          const sty = await User.findOne({ username: { $regex: /^sty$/i } });
          if (sty && sty.role !== 'admin') {
            sty.role = 'admin';
            await sty.save();
            console.log('[Clover] Ensured user "sty" has role=admin.');
          }
        } catch (e) { console.error('[Clover] sty admin check error:', e.message); }
      }
      return mongoose.connection.readyState === 1;
    }).catch(err => {
      dbConnectPromise = null;
      console.error('[Clover] MongoDB error:', err.message);
      return false;
    });
  }
  let tId;
  const timeoutPromise = new Promise(resolve => {
    tId = setTimeout(() => resolve(false), Math.max(500, Number(timeoutMs) || 8000));
    if (tId && typeof tId.unref === 'function') tId.unref();
  });
  await Promise.race([dbConnectPromise, timeoutPromise]);
  if (tId) clearTimeout(tId);
  return mongoose.connection.readyState === 1;
}

