const wsClients = new Set();
const geoCache = new Map();
const geoCacheTimeout = 1000 * 60 * 60;
const kickQueue = new Map();

function hashPassword(password) {
  const salt = crypto.randomBytes(16).toString('hex');
  const derived = crypto.pbkdf2Sync(String(password), salt, 100000, 64, 'sha512').toString('hex');
  return `pbkdf2v2$${salt}$${derived}`;
}

function verifyPassword(inputPassword, storedHash) {
  if (typeof inputPassword !== 'string' || typeof storedHash !== 'string' || !storedHash) return false;
  if (storedHash.startsWith('pbkdf2v2$')) {
    const parts = storedHash.split('$');
    if (parts.length !== 3) return false;
    const salt = parts[1];
    const expectedHex = parts[2];
    const actualHex = crypto.pbkdf2Sync(inputPassword, salt, 100000, 64, 'sha512').toString('hex');
    return timingSafeCompare(actualHex, expectedHex);
  }
  const legacyHex = crypto.pbkdf2Sync(inputPassword, 'prey_salt_secured', 1000, 64, 'sha512').toString('hex');
  return timingSafeCompare(legacyHex, storedHash);
}

async function getIPInfo(ip) {
  if (!ip || ip === '127.0.0.1' || ip === '::1' || ip.startsWith('192.168.') || ip.startsWith('10.')) {
    return { country: 'Local', city: 'Local Network', isp: 'Private', isVPN: false, countryCode: 'XX' };
  }
  if (geoCache.has(ip)) {
    const cached = geoCache.get(ip);
    if (Date.now() - cached.timestamp < geoCacheTimeout) return cached.data;
  }
  try {
    const response = await fetch(`http://ip-api.com/json/${ip}?fields=status,country,countryCode,city,isp,org,proxy,hosting`);
    const data = await response.json();
    if (data.status === 'success') {
      const info = {
        country: data.country || 'Unknown',
        countryCode: data.countryCode || 'XX',
        city: data.city || 'Unknown',
        isp: data.isp || data.org || 'Unknown',
        isVPN: data.proxy || data.hosting || false
      };
      geoCache.set(ip, { data: info, timestamp: Date.now() });
      return info;
    }
  } catch (e) { console.error('[GeoIP]', e.message); }
  return { country: 'Unknown', countryCode: 'XX', city: 'Unknown', isp: 'Unknown', isVPN: false };
}

