const activeTcpByIp = new Map();
server.on('connection', (socket) => {
  const ip = normalizeIp(socket.remoteAddress || 'unknown');
  const count = (activeTcpByIp.get(ip) || 0) + 1;
  if (count > 60) {
    try { socket.destroy(); } catch (_) {}
    return;
  }
  activeTcpByIp.set(ip, count);
  socket.once('close', () => {
    const cur = (activeTcpByIp.get(ip) || 1) - 1;
    if (cur <= 0) activeTcpByIp.delete(ip);
    else activeTcpByIp.set(ip, cur);
  });
});

