const webhookRateLimit = {
  requests: [],
  maxPerMinute: 5,
  queue: [],
  processing: false,
  lastRequest: 0,
  globalCooldownUntil: 0 // When hit with 429, pause ALL Discord requests until this time
};

async function sendDiscordWebhook(type, data) {

  if (Date.now() < webhookRateLimit.globalCooldownUntil) {
    console.log('[Discord] Global cooldown active, dropping webhook');
    return;
  }

  const colors = { invalid_key: 0xff0000, site_access_denied: 0xff6600, key_revoked: 0xff0000, key_created: 0x00ff00, script_executed: 0x7c6aff };
  const embed = { title: `Clover: ${type.replace(/_/g, ' ').toUpperCase()}`, color: colors[type] || 0x7c6aff, fields: [], timestamp: new Date().toISOString() };
  if (data.isp) embed.fields.push({ name: 'ISP', value: data.isp, inline: true });
  if (data.isVPN) embed.fields.push({ name: 'VPN/Proxy', value: '⚠️ Yes', inline: true });
  if (data.siteUsername) embed.fields.push({ name: 'Site Username', value: data.siteUsername, inline: true });
  if (data.robloxUsername) embed.fields.push({ name: 'Roblox User', value: data.robloxUsername, inline: true });
  if (data.discordUsername) embed.fields.push({ name: 'Discord User', value: data.discordUsername, inline: true });
  if (data.discordDisplayName) embed.fields.push({ name: 'Discord Display', value: data.discordDisplayName, inline: true });
  if (data.discordId) embed.fields.push({ name: 'Discord ID', value: data.discordId, inline: true });
  if (data.key) embed.fields.push({ name: 'Key', value: String(data.key).substring(0, 20) + '...' });
  if (data.reason) embed.fields.push({ name: 'Reason', value: data.reason });


  const now = Date.now();
  webhookRateLimit.requests = webhookRateLimit.requests.filter(time => now - time < 60000);

  if (webhookRateLimit.requests.length >= webhookRateLimit.maxPerMinute) {
    console.log('[Discord] Rate limit reached, queuing webhook');
    if (webhookRateLimit.queue.length < 10) {
      webhookRateLimit.queue.push({ type, data, embed });
    } else {
      console.log('[Discord] Queue full, dropping webhook');
    }
    processWebhookQueue();
    return;
  }


  const timeSinceLastRequest = now - webhookRateLimit.lastRequest;
  if (timeSinceLastRequest < 12000) {
    await new Promise(resolve => setTimeout(resolve, 12000 - timeSinceLastRequest));
  }

  webhookRateLimit.requests.push(now);
  webhookRateLimit.lastRequest = now;
  await sendWebhookRequest(embed);
}

async function sendWebhookRequest(embed) {
  try {
    const response = await fetch(DISCORD_WEBHOOK, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ embeds: [embed] }) });
    if (!response.ok) {
      const errorText = await response.text();
      console.error('[Discord] Webhook error:', response.status, errorText);


      if (response.status === 429) {
        console.error('[Discord] Got 429! Activating 5-minute global cooldown. Clearing queue.');
        webhookRateLimit.globalCooldownUntil = Date.now() + 5 * 60 * 1000;
        webhookRateLimit.queue = []; // Drop all queued messages
        webhookRateLimit.requests = [];
      }
    }
  } catch (e) { console.error('[Discord] Webhook failed:', e.message); }
}

async function processWebhookQueue() {
  if (webhookRateLimit.processing || webhookRateLimit.queue.length === 0) return;
  webhookRateLimit.processing = true;

  let attempts = 0;
  while (webhookRateLimit.queue.length > 0 && attempts < 10) {
    attempts++;


    if (Date.now() < webhookRateLimit.globalCooldownUntil) {
      console.log('[Discord] Global cooldown active, clearing queue');
      webhookRateLimit.queue = [];
      break;
    }

    const now = Date.now();
    webhookRateLimit.requests = webhookRateLimit.requests.filter(time => now - time < 60000);

    if (webhookRateLimit.requests.length >= webhookRateLimit.maxPerMinute) {

      console.log('[Discord] Rate limit hit during queue processing, dropping remaining', webhookRateLimit.queue.length, 'items');
      webhookRateLimit.queue = [];
      break;
    }


    const timeSinceLastRequest = now - webhookRateLimit.lastRequest;
    if (timeSinceLastRequest < 12000) {
      await new Promise(resolve => setTimeout(resolve, 12000 - timeSinceLastRequest));
    }

    const item = webhookRateLimit.queue.shift();
    webhookRateLimit.requests.push(Date.now());
    webhookRateLimit.lastRequest = Date.now();
    await sendWebhookRequest(item.embed);
  }

  webhookRateLimit.processing = false;
}

async function updateAnalytics(type, country) {
  const today = new Date().toISOString().split('T')[0];
  try {
    let a = await Analytics.findOne({ date: today });
    if (!a) a = new Analytics({ date: today });
    if (type === 'execution') a.executions++;
    if (type === 'new_key') a.newKeys++;
    if (type === 'revoked') a.revokedKeys++;
    if (type === 'failed') a.failedAttempts++;
    if (country) {
      const cur = a.countryBreakdown.get(country) || 0;
      a.countryBreakdown.set(country, cur + 1);
    }
    await a.save();
  } catch (e) { console.error('[Analytics]', e.message); }
}

