// --- Music search and audio delivery (yt-dlp first, Apple previews as fallback) ---
let ytDlpAvailableCache = null;
let ytDlpRunner = null;
let ytDlpDetectPromise = null;
let activeYtDlpJobs = 0;
const ytDlpStreamCache = new Map();
const ytDlpSearchCache = new Map();
const ytDlpRuntimeArgs = (() => {
  const nodeMajor = Number(String(process.versions.node || '0').split('.')[0]);
  return nodeMajor >= 20 ? ['--js-runtimes', 'node'] : [];
})();

function detectYtDlpRunner() {
  if (ytDlpRunner) return Promise.resolve(ytDlpRunner);
  if (ytDlpDetectPromise) return ytDlpDetectPromise;
  if (ytDlpAvailableCache === false) return Promise.resolve(null);

  const candidates = [];
  const configuredBin = String(process.env.YT_DLP_BIN || process.env.YTDLP_PATH || '').trim();
  if (configuredBin) candidates.push({ cmd: configuredBin, prefix: [] });
  candidates.push(
    { cmd: 'yt-dlp', prefix: [] },
    { cmd: 'python', prefix: ['-m', 'yt_dlp'] },
    { cmd: 'py', prefix: ['-m', 'yt_dlp'] },
    { cmd: 'python3', prefix: ['-m', 'yt_dlp'] }
  );

  ytDlpDetectPromise = new Promise((resolve) => {
    let idx = 0;
    function next() {
      if (idx >= candidates.length) {
        ytDlpAvailableCache = false;
        return resolve(null);
      }
      const candidate = candidates[idx++];
      execFile(candidate.cmd, candidate.prefix.concat(['--version']), {
        timeout: 5000,
        windowsHide: true,
        maxBuffer: 1024 * 1024
      }, (err) => {
        if (!err) {
          ytDlpRunner = candidate;
          ytDlpAvailableCache = true;
          return resolve(candidate);
        }
        next();
      });
    }
    next();
  }).finally(() => {
    ytDlpDetectPromise = null;
  });

  return ytDlpDetectPromise;
}

function checkYtDlpAvailable() {
  if (ytDlpAvailableCache !== null) return Promise.resolve(ytDlpAvailableCache);
  return detectYtDlpRunner().then(Boolean);
}

function runYtDlp(args, timeoutMs = 20000, maxBuffer = 8 * 1024 * 1024) {
  return detectYtDlpRunner().then((runner) => {
    if (!runner) return { ok: false, stdout: '', stderr: 'yt-dlp is not installed' };
    return new Promise((resolve) => {
      if (activeYtDlpJobs >= 4) {
        return resolve({ ok: false, stdout: '', stderr: 'Music engine is busy' });
      }
      activeYtDlpJobs++;
      execFile(runner.cmd, runner.prefix.concat(['--ignore-config']).concat(ytDlpRuntimeArgs, args), {
        timeout: timeoutMs,
        windowsHide: true,
        maxBuffer,
        encoding: 'utf8'
      }, (err, stdout, stderr) => {
        activeYtDlpJobs = Math.max(0, activeYtDlpJobs - 1);
        if (err) {
          return resolve({
            ok: false,
            stdout: String(stdout || ''),
            stderr: String(stderr || err.message || 'yt-dlp request failed').slice(0, 1200)
          });
        }
        resolve({ ok: true, stdout: String(stdout || ''), stderr: String(stderr || '') });
      });
    });
  });
}

function formatMusicDuration(seconds) {
  const total = Math.max(0, Math.floor(Number(seconds) || 0));
  if (!total) return '';
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  const secs = total % 60;
  return hours > 0
    ? `${hours}:${String(minutes).padStart(2, '0')}:${String(secs).padStart(2, '0')}`
    : `${minutes}:${String(secs).padStart(2, '0')}`;
}

function normaliseYtDlpTrack(entry) {
  if (!entry || typeof entry !== 'object') return null;
  const videoId = String(entry.id || entry.display_id || '').trim();
  if (!/^[A-Za-z0-9_-]{11}$/.test(videoId)) return null;

  const rawTitle = String(entry.title || entry.fulltitle || '').trim();
  if (!rawTitle) return null;
  const channel = String(entry.channel || entry.uploader || entry.creator || 'YouTube').replace(/\s*-\s*Topic$/i, '').trim();
  let title = rawTitle;
  let artist = channel || 'YouTube';
  const dashIdx = rawTitle.indexOf(' - ');
  if (dashIdx > 0 && dashIdx < 65) {
    artist = rawTitle.slice(0, dashIdx).trim() || artist;
    title = rawTitle.slice(dashIdx + 3)
      .replace(/\s*\((?:Official\s*)?(?:Music\s*)?(?:Video|Audio|Lyric(?:s)?\s*Video|Visualizer)\)/gi, '')
      .replace(/\s*\[(?:Official\s*)?(?:Audio|Video|Lyrics)\]/gi, '')
      .trim();
  }

  const duration = Number(entry.duration) || 0;
  const thumbnails = Array.isArray(entry.thumbnails) ? entry.thumbnails : [];
  const thumbnail = String(entry.thumbnail || (thumbnails.length ? (thumbnails[thumbnails.length - 1].url || '') : '')).trim();
  return {
    id: videoId,
    ytId: videoId,
    t: title || rawTitle,
    a: artist,
    duration: String(entry.duration_string || formatMusicDuration(duration) || '3:30'),
    artwork: /^https?:\/\//i.test(thumbnail) ? thumbnail : 'https://img.youtube.com/vi/' + videoId + '/hqdefault.jpg'
  };
}

async function fetchYouTubeTracksHtmlFallback(query, limit) {
  try {
    const res = await fetch('https://www.youtube.com/results?search_query=' + encodeURIComponent(query), {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/130.0.0.0 Safari/537.36',
        'Accept-Language': 'en-US,en;q=0.9'
      },
      signal: AbortSignal.timeout(12000)
    });
    if (!res.ok) return [];
    const html = await res.text();
    const match = html.match(/(?:var\s+)?ytInitialData\s*=\s*(\{[\s\S]+?\})\s*;\s*<\/script>/);
    if (!match) return [];
    const data = JSON.parse(match[1]);
    const sections = data?.contents?.twoColumnSearchResultsRenderer?.primaryContents?.sectionListRenderer?.contents || [];
    const out = [];
    const seen = new Set();
    const allowLong = /\b(hour|mix|live|full album)\b/i.test(query);
    for (const section of sections) {
      for (const item of (section?.itemSectionRenderer?.contents || [])) {
        const video = item?.videoRenderer;
        const id = String(video?.videoId || '');
        if (!video || !/^[A-Za-z0-9_-]{11}$/.test(id) || seen.has(id)) continue;
        const durationText = video.lengthText?.simpleText || '';
        if (!durationText && !allowLong) continue;
        if (durationText) {
          const parts = durationText.split(':').map(Number);
          const total = parts.length === 3 ? parts[0] * 3600 + parts[1] * 60 + parts[2] : (parts.length === 2 ? parts[0] * 60 + parts[1] : 0);
          if (!allowLong && (!total || total > 900)) continue;
        }
        seen.add(id);
        const normalised = normaliseYtDlpTrack({
          id,
          title: (video.title?.runs || []).map(r => r.text).join(''),
          channel: (video.ownerText?.runs || []).map(r => r.text).join(''),
          duration_string: durationText,
          thumbnail: 'https://img.youtube.com/vi/' + id + '/hqdefault.jpg'
        });
        if (normalised) out.push(normalised);
        if (out.length >= limit) return out;
      }
    }
    return out;
  } catch (_) {
    return [];
  }
}

async function fetchYouTubeTracks(query, limit = 25) {
  const cleanQuery = String(query || '').replace(/\s+/g, ' ').trim().slice(0, 180);
  const safeLimit = Math.max(1, Math.min(30, Math.floor(Number(limit) || 25)));
  if (!cleanQuery) return [];

  const cacheKey = cleanQuery.toLowerCase() + ':' + safeLimit;
  const cached = ytDlpSearchCache.get(cacheKey);
  if (cached && Date.now() - cached.ts < 5 * 60 * 1000) return cached.tracks.map(track => ({ ...track }));

  const result = await runYtDlp([
    '--no-warnings',
    '--no-call-home',
    '--skip-download',
    '--flat-playlist',
    '--dump-single-json',
    '--playlist-end', String(safeLimit),
    'ytsearch' + safeLimit + ':' + cleanQuery
  ], 25000, 10 * 1024 * 1024);

  let tracks = [];
  if (result.ok && result.stdout.trim()) {
    try {
      const parsed = JSON.parse(result.stdout.trim());
      const entries = Array.isArray(parsed.entries) ? parsed.entries : [parsed];
      const allowLong = /\b(hour|mix|live|full album)\b/i.test(cleanQuery);
      const seen = new Set();
      for (const entry of entries) {
        const track = normaliseYtDlpTrack(entry);
        if (!track || seen.has(track.ytId)) continue;
        const durationParts = track.duration.split(':').map(Number);
        const durationSeconds = durationParts.length === 3
          ? durationParts[0] * 3600 + durationParts[1] * 60 + durationParts[2]
          : (durationParts.length === 2 ? durationParts[0] * 60 + durationParts[1] : 0);
        if (!allowLong && durationSeconds && durationSeconds > 900) continue;
        seen.add(track.ytId);
        tracks.push(track);
        if (tracks.length >= safeLimit) break;
      }
    } catch (err) {
      console.warn('[Clover Music] Could not parse yt-dlp search results:', err?.message || err);
    }
  } else if (result.stderr && result.stderr !== 'yt-dlp is not installed') {
    console.warn('[Clover Music] yt-dlp search failed:', result.stderr.slice(0, 300));
  }

  // YouTube changes its search page periodically. This remains a last-resort
  // metadata fallback; normal search and audio resolution use yt-dlp.
  if (tracks.length === 0) tracks = await fetchYouTubeTracksHtmlFallback(cleanQuery, safeLimit);

  if (tracks.length > 0) {
    ytDlpSearchCache.set(cacheKey, { ts: Date.now(), tracks: tracks.map(track => ({ ...track })) });
    if (ytDlpSearchCache.size > 250) {
      const oldestKey = ytDlpSearchCache.keys().next().value;
      if (oldestKey) ytDlpSearchCache.delete(oldestKey);
    }
  }
  return tracks;
}

async function resolveYtDlpAudioUrl(videoId) {
  const id = String(videoId || '').trim();
  if (!/^[A-Za-z0-9_-]{11}$/.test(id)) return null;

  const cached = ytDlpStreamCache.get(id);
  if (cached && Date.now() - cached.ts < 8 * 60 * 1000) return cached.url;
  if (cached) ytDlpStreamCache.delete(id);

  const result = await runYtDlp([
    '--no-warnings',
    '--no-call-home',
    '--no-playlist',
    '-f', 'bestaudio[ext=m4a]/bestaudio/best',
    '-g',
    'https://www.youtube.com/watch?v=' + id
  ], 25000, 2 * 1024 * 1024);
  if (!result.ok) {
    if (result.stderr && result.stderr !== 'yt-dlp is not installed') {
      console.warn('[Clover Music] yt-dlp stream resolve failed:', result.stderr.slice(0, 300));
    }
    return null;
  }

  const url = String(result.stdout || '').trim().split(/\r?\n/)[0];
  if (!/^https?:\/\//i.test(url)) return null;
  ytDlpAvailableCache = true;
  ytDlpStreamCache.set(id, { url, ts: Date.now() });
  if (ytDlpStreamCache.size > 500) {
    const oldestKey = ytDlpStreamCache.keys().next().value;
    if (oldestKey) ytDlpStreamCache.delete(oldestKey);
  }
  return url;
}

app.get('/api/music/stream/:id', musicLimiter, authMiddleware, async (req, res) => {
  let upstream = null;
  try {
    const id = String(req.params.id || '').trim();
    if (!/^[A-Za-z0-9_-]{11}$/.test(id)) return res.status(400).json({ error: 'Invalid video ID' });
    const streamUrl = await resolveYtDlpAudioUrl(id);
    if (!streamUrl) return res.status(503).json({ available: false, error: 'The music stream is not available right now.' });

    const headers = { 'User-Agent': 'Mozilla/5.0 CloverMusic/1.0' };
    if (req.headers.range) headers.Range = req.headers.range;
    upstream = await fetch(streamUrl, { headers, signal: AbortSignal.timeout(30000) });
    if (!upstream.ok && upstream.status !== 206) {
      return res.status(502).json({ error: 'The music provider could not deliver this audio.' });
    }

    res.status(upstream.status);
    res.setHeader('Cache-Control', 'no-store');
    res.setHeader('Content-Type', upstream.headers.get('content-type') || 'audio/mp4');
    res.setHeader('Accept-Ranges', upstream.headers.get('accept-ranges') || 'bytes');
    const contentLength = upstream.headers.get('content-length');
    const contentRange = upstream.headers.get('content-range');
    if (contentLength) res.setHeader('Content-Length', contentLength);
    if (contentRange) res.setHeader('Content-Range', contentRange);

    const { Readable } = require('stream');
    const audioStream = Readable.fromWeb(upstream.body);
    audioStream.on('error', (err) => {
      if (!res.headersSent) res.status(502).json({ error: 'Audio stream interrupted.' });
      else res.destroy(err);
    });
    res.on('close', () => {
      if (!res.writableEnded && upstream && upstream.body) {
        try { upstream.body.cancel(); } catch (_) {}
      }
    });
    audioStream.pipe(res);
  } catch (err) {
    if (upstream && upstream.body) {
      try { upstream.body.cancel(); } catch (_) {}
    }
    if (!res.headersSent) res.status(502).json({ error: 'Unable to start the audio stream.' });
  }
});

app.get('/api/music/resolve', musicLimiter, authMiddleware, async (req, res) => {
  try {
    const q = typeof req.query.q === 'string' ? req.query.q.trim().slice(0, 180) : '';
    const exclude = new Set(String(req.query.exclude || '').split(',').map(value => value.trim()).filter(Boolean));
    if (!q) return res.json({ ytCandidates: [], previewUrl: '', ytDlpAvailable: await checkYtDlpAvailable() });

    const [ytResult, itunesResult, ytDlpAvailable] = await Promise.allSettled([
      fetchYouTubeTracks(q, 18),
      fetch('https://itunes.apple.com/search?term=' + encodeURIComponent(q) + '&media=music&entity=song&limit=5', {
        signal: AbortSignal.timeout(12000)
      }).then(response => response.ok ? response.json() : { results: [] }),
      checkYtDlpAvailable()
    ]);

    const ytCandidates = (ytResult.status === 'fulfilled' ? ytResult.value : []).filter(track => track && track.ytId && !exclude.has(track.ytId));
    const itunesItems = itunesResult.status === 'fulfilled' && Array.isArray(itunesResult.value?.results)
      ? itunesResult.value.results.filter(item => item && item.previewUrl)
      : [];
    const firstItunes = itunesItems[0] || null;
    return res.json({
      ytCandidates,
      previewUrl: firstItunes ? firstItunes.previewUrl : '',
      artwork: firstItunes?.artworkUrl100 ? firstItunes.artworkUrl100.replace('100x100bb', '300x300bb') : '',
      ytDlpAvailable: ytDlpAvailable.status === 'fulfilled' ? Boolean(ytDlpAvailable.value) : false
    });
  } catch (err) {
    return res.status(500).json({ ytCandidates: [], previewUrl: '', error: 'Music lookup failed.' });
  }
});

app.get('/api/music/search', musicLimiter, authMiddleware, async (req, res) => {
  try {
    const q = typeof req.query.q === 'string' ? req.query.q.trim().slice(0, 180) : '';
    if (!q) return res.json({ results: [], ytResults: [], ytDlpAvailable: await checkYtDlpAvailable() });
    res.setHeader('Cache-Control', 'no-store');

    const itunesUrl = 'https://itunes.apple.com/search?term=' + encodeURIComponent(q) + '&media=music&entity=song&limit=30';
    const [ytSettled, itunesSettled, ytDlpSettled] = await Promise.allSettled([
      fetchYouTubeTracks(q, 25),
      fetch(itunesUrl, { signal: AbortSignal.timeout(12000) }).then(response => response.ok ? response.json() : { results: [] }),
      checkYtDlpAvailable()
    ]);

    const ytResults = ytSettled.status === 'fulfilled' ? ytSettled.value : [];
    const data = itunesSettled.status === 'fulfilled' ? itunesSettled.value : { results: [] };
    const queryLower = q.toLowerCase();
    const raw = Array.isArray(data?.results) ? data.results.filter(item => item && item.previewUrl) : [];
    raw.sort((a, b) => {
      const score = (title, artist) => {
        const track = String(title || '').toLowerCase();
        const performer = String(artist || '').toLowerCase();
        if (track === queryLower) return 100;
        if ((track + ' ' + performer) === queryLower || (performer + ' ' + track) === queryLower) return 95;
        if (track.startsWith(queryLower)) return 80;
        if (track.includes(queryLower)) return 65;
        return queryLower.split(/\s+/).filter(Boolean).reduce((total, word) => {
          return total + (track.includes(word) ? 2 : (performer.includes(word) ? 1 : 0));
        }, 0) * 10;
      };
      return score(b.trackName, b.artistName) - score(a.trackName, a.artistName);
    });

    return res.json({
      results: raw,
      ytResults,
      ytDlpAvailable: ytDlpSettled.status === 'fulfilled' ? Boolean(ytDlpSettled.value) : false
    });
  } catch (err) {
    return res.status(500).json({ error: 'Music search failed. Please try again.', results: [], ytResults: [], ytDlpAvailable: false });
  }
});

app.get('/api/music/chart', musicLimiter, authMiddleware, async (req, res) => {
  try {
    const chartUrl = 'https://itunes.apple.com/us/rss/topsongs/limit=100/json';
    const response = await fetch(chartUrl);
    if (!response.ok) return res.status(response.status).json({ error: 'Upstream chart error' });
    const data = await response.json();
    const entries = (data && data.feed && data.feed.entry) || [];
    const songs = entries.map((e, idx) => {
      let preview = '';
      if (Array.isArray(e.link)) {
        const audioLink = e.link.find(l => l.attributes && l.attributes.type && l.attributes.type.includes('audio'));
        if (audioLink && audioLink.attributes) preview = audioLink.attributes.href;
      }
      const artwork = (e['im:image'] && e['im:image'][2] && e['im:image'][2].label) || '';
      return {
        id: (e.id && e.id.attributes && e.id.attributes['im:id']) || ('top-' + idx),
        title: (e['im:name'] && e['im:name'].label) || 'Unknown Track',
        artist: (e['im:artist'] && e['im:artist'].label) || 'Unknown Artist',
        album: (e['im:collection'] && e['im:collection']['im:name'] && e['im:collection']['im:name'].label) || 'Top Chart',
        artwork: artwork.replace('170x170bb', '600x600bb').replace('100x100bb', '600x600bb'),
        previewUrl: preview,
        duration: '3:30'
      };
    });
    return res.json({ songs });
  } catch (err) {
    return res.status(500).json({ error: err.message || 'Chart fetch failed' });
  }
});

let musicBrowseCache = { ts: 0, shelves: null };
app.get('/api/music/browse', musicLimiter, authMiddleware, async (req, res) => {
  try {
    if (musicBrowseCache.shelves && (Date.now() - musicBrowseCache.ts) < 15 * 60 * 1000) {
      return res.json({ shelves: musicBrowseCache.shelves });
    }
    const defs = [
      { id: 'new', title: 'New Releases', url: 'https://itunes.apple.com/us/rss/topsongs/limit=24/json' },
      { id: 'top', title: 'Top Hits', url: 'https://itunes.apple.com/us/rss/topsongs/limit=24/explicit=true/json' },
      { id: 'pop', title: 'Pop', url: 'https://itunes.apple.com/us/rss/topsongs/limit=24/genre=14/json' },
      { id: 'hiphop', title: 'Hip-Hop', url: 'https://itunes.apple.com/us/rss/topsongs/limit=24/genre=18/json' },
      { id: 'indie', title: 'Indie', url: 'https://itunes.apple.com/search?term=indie+alternative&entity=song&limit=24' },
      { id: 'rock', title: 'Rock', url: 'https://itunes.apple.com/us/rss/topsongs/limit=24/genre=21/json' },
      { id: 'rnb', title: 'R&B', url: 'https://itunes.apple.com/us/rss/topsongs/limit=24/genre=15/json' },
      { id: 'latin', title: 'Latin', url: 'https://itunes.apple.com/us/rss/topsongs/limit=24/genre=12/json' },
      { id: 'electronic', title: 'Electronic', url: 'https://itunes.apple.com/us/rss/topsongs/limit=24/genre=7/json' },
      { id: 'kpop', title: 'K-Pop', url: 'https://itunes.apple.com/us/rss/topsongs/limit=24/genre=51/json' },
      { id: 'chill', title: 'Chill', url: 'https://itunes.apple.com/search?term=chill+lofi+beats&entity=song&limit=24' }
    ];
    const settled = await Promise.allSettled(defs.map(async (d) => {
      const r = await fetch(d.url);
      if (!r.ok) return { id: d.id, title: d.title, songs: [] };
      const j = await r.json();
      let songs = [];
      if (j && j.feed && Array.isArray(j.feed.entry)) {
        songs = j.feed.entry.map((e, idx) => {
          let preview = '';
          if (Array.isArray(e.link)) {
            const audioLink = e.link.find(l => l.attributes && l.attributes.type && l.attributes.type.includes('audio'));
            if (audioLink && audioLink.attributes) preview = audioLink.attributes.href;
          }
          const artwork = (e['im:image'] && e['im:image'][2] && e['im:image'][2].label) || '';
          return {
            id: (e.id && e.id.attributes && e.id.attributes['im:id']) || (d.id + '-' + idx),
            t: (e['im:name'] && e['im:name'].label) || 'Unknown Track',
            a: (e['im:artist'] && e['im:artist'].label) || 'Unknown Artist',
            album: (e['im:collection'] && e['im:collection']['im:name'] && e['im:collection']['im:name'].label) || d.title,
            artwork: artwork.replace('170x170bb', '300x300bb').replace('100x100bb', '300x300bb'),
            previewUrl: preview,
            duration: '3:30'
          };
        }).filter(s => s.previewUrl);
      } else if (j && Array.isArray(j.results)) {
        songs = j.results.map((rItem) => {
          const durSec = Math.round((rItem.trackTimeMillis || 180000) / 1000);
          const m = Math.floor(durSec / 60);
          const s = durSec % 60;
          return {
            id: 'itunes-' + rItem.trackId,
            t: rItem.trackName || 'Unknown Track',
            a: rItem.artistName || 'Unknown Artist',
            album: rItem.collectionName || d.title,
            artwork: (rItem.artworkUrl100 || '').replace('100x100bb', '300x300bb'),
            previewUrl: rItem.previewUrl || '',
            duration: m + ':' + (s < 10 ? '0' : '') + s
          };
        }).filter(s => s.previewUrl);
      }
      return { id: d.id, title: d.title, songs };
    }));
    const shelves = settled
      .filter(s => s.status === 'fulfilled' && s.value && s.value.songs.length > 0)
      .map(s => s.value);
    if (shelves.length > 0) musicBrowseCache = { ts: Date.now(), shelves };
    return res.json({ shelves });
  } catch (err) {
    return res.status(500).json({ error: err.message || 'Browse fetch failed' });
  }
});

