function stripLuaComments(luaSrc) {
  let out = '';
  let i = 0;
  const n = luaSrc.length;
  while (i < n) {
    const ch = luaSrc[i];
    if (ch === "'" || ch === '"') {
      const q = ch;
      out += q;
      i++;
      while (i < n) {
        if (luaSrc[i] === '\\' && i + 1 < n) {
          out += luaSrc[i] + luaSrc[i + 1];
          i += 2;
          continue;
        }
        out += luaSrc[i];
        if (luaSrc[i] === q) { i++; break; }
        i++;
      }
      continue;
    }
    if (ch === '[' && (luaSrc[i + 1] === '[' || luaSrc[i + 1] === '=')) {
      let eq = 0;
      let j = i + 1;
      while (j < n && luaSrc[j] === '=') { eq++; j++; }
      if (j < n && luaSrc[j] === '[') {
        const closeTag = ']' + '='.repeat(eq) + ']';
        const endIdx = luaSrc.indexOf(closeTag, j + 1);
        if (endIdx !== -1) {
          out += luaSrc.slice(i, endIdx + closeTag.length);
          i = endIdx + closeTag.length;
          continue;
        }
      }
    }
    if (ch === '-' && luaSrc[i + 1] === '-') {
      if (luaSrc[i + 2] === '[' && (luaSrc[i + 3] === '[' || luaSrc[i + 3] === '=')) {
        let eq = 0;
        let j = i + 3;
        while (j < n && luaSrc[j] === '=') { eq++; j++; }
        if (j < n && luaSrc[j] === '[') {
          const closeTag = ']' + '='.repeat(eq) + ']';
          const endIdx = luaSrc.indexOf(closeTag, j + 1);
          if (endIdx !== -1) {
            i = endIdx + closeTag.length;
            continue;
          }
        }
      }
      while (i < n && luaSrc[i] !== '\n') i++;
      continue;
    }
    out += ch;
    i++;
  }
  return out;
}

function rc4Transform(plainBuf, keyBuf) {
  const S = new Uint8Array(256);
  for (let i = 0; i < 256; i++) S[i] = i;
  let j = 0;
  for (let i = 0; i < 256; i++) {
    j = (j + S[i] + keyBuf[i % keyBuf.length]) & 255;
    const tmp = S[i]; S[i] = S[j]; S[j] = tmp;
  }
  const out = Buffer.allocUnsafe(plainBuf.length);
  let iIdx = 0, jIdx = 0;
  for (let n = 0; n < plainBuf.length; n++) {
    iIdx = (iIdx + 1) & 255;
    jIdx = (jIdx + S[iIdx]) & 255;
    const tmp = S[iIdx]; S[iIdx] = S[jIdx]; S[jIdx] = tmp;
    out[n] = plainBuf[n] ^ S[(S[iIdx] + S[jIdx]) & 255];
  }
  return out;
}

const vmGateKeys = new Map();
const vmGateUsedNonces = new Map();
function getVmGateAesKey() {
  return crypto.createHash('sha256').update('vm-gate:' + LOCKOUT_SECRET).digest();
}
function sealVmGateToken(keyHex, ttlMs = 120000) {
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', getVmGateAesKey(), iv);
  const payload = JSON.stringify({
    k: String(keyHex || ''),
    exp: Date.now() + Math.max(10000, Number(ttlMs) || 120000),
    n: crypto.randomBytes(8).toString('hex')
  });
  const enc = Buffer.concat([cipher.update(payload, 'utf8'), cipher.final()]);
  const tag = cipher.getAuthTag();
  return iv.toString('base64url') + '.' + tag.toString('base64url') + '.' + enc.toString('base64url');
}
function openVmGateToken(token) {
  if (!token || typeof token !== 'string') return null;
  const parts = token.split('.');
  if (parts.length !== 3) return null;
  try {
    const iv = Buffer.from(parts[0], 'base64url');
    const tag = Buffer.from(parts[1], 'base64url');
    const enc = Buffer.from(parts[2], 'base64url');
    if (iv.length !== 12 || tag.length !== 16 || !enc.length) return null;
    const decipher = crypto.createDecipheriv('aes-256-gcm', getVmGateAesKey(), iv);
    decipher.setAuthTag(tag);
    const raw = Buffer.concat([decipher.update(enc), decipher.final()]).toString('utf8');
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed.k !== 'string' || !/^[a-f0-9]{64}$/i.test(parsed.k)) return null;
    const exp = Number(parsed.exp) || 0;
    if (!exp || Date.now() > exp) return null;
    const nonce = String(parsed.n || '');
    if (nonce && vmGateUsedNonces.has(nonce)) return null;
    if (nonce) vmGateUsedNonces.set(nonce, exp);
    return { keyHex: parsed.k, expires: exp };
  } catch (_) {
    return null;
  }
}
setInterval(() => {
  const now = Date.now();
  for (const [id, entry] of vmGateKeys.entries()) {
    if (!entry || now > entry.expires) vmGateKeys.delete(id);
  }
  for (const [n, exp] of vmGateUsedNonces.entries()) {
    if (!exp || now > exp) vmGateUsedNonces.delete(n);
  }
}, 60000);

const VM_OP_NAMES = [
  'LOADK', 'LOADBOOL', 'LOADNIL', 'MOVE',
  'ADD', 'SUB', 'MUL', 'DIV', 'MOD', 'POW', 'CONCAT',
  'EQ', 'LT', 'LE', 'NOT', 'LEN', 'UNM',
  'JMP', 'JMPIF', 'JMPIFNOT',
  'CALL', 'RETURN',
  'GETTABLE', 'SETTABLE', 'GETGLOBAL', 'SETGLOBAL', 'NEWTABLE', 'SELF',
  'CLOSURE', 'GETUPVAL', 'SETUPVAL',
  'FORPREP', 'FORLOOP', 'TFORCALL'
];

function tokenizeLuaForVM(src) {
  const kw = new Set(['and', 'break', 'do', 'else', 'elseif', 'end', 'false', 'for', 'function', 'if', 'in', 'local', 'nil', 'not', 'or', 'repeat', 'return', 'then', 'true', 'until', 'while']);
  const toks = [];
  let i = 0, n = src.length, line = 1;
  while (i < n) {
    const ch = src[i];
    if (ch === '\n') { line++; i++; continue; }
    if (ch === ' ' || ch === '\t' || ch === '\r') { i++; continue; }
    if (ch === '-' && src[i + 1] === '-') {
      if (src[i + 2] === '[' && src[i + 3] === '[') {
        i += 4;
        while (i < n && !(src[i] === ']' && src[i + 1] === ']')) { if (src[i] === '\n') line++; i++; }
        i += 2; continue;
      }
      while (i < n && src[i] !== '\n') i++;
      continue;
    }
    if (ch === '[' && src[i + 1] === '[') {
      const startL = line; i += 2; let s = '';
      while (i < n && !(src[i] === ']' && src[i + 1] === ']')) { if (src[i] === '\n') line++; s += src[i++]; }
      i += 2; toks.push({ t: 'STR', v: s, l: startL }); continue;
    }
    if (ch === "'" || ch === '"') {
      const q = ch, startL = line; i++; let s = '';
      while (i < n && src[i] !== q) {
        if (src[i] === '\\' && i + 1 < n) {
          const esc = src[i + 1];
          if (esc === 'n') s += '\n';
          else if (esc === 'r') s += '\r';
          else if (esc === 't') s += '\t';
          else s += esc;
          i += 2; continue;
        }
        if (src[i] === '\n') line++;
        s += src[i++];
      }
      i++; toks.push({ t: 'STR', v: s, l: startL }); continue;
    }
    if ((ch >= '0' && ch <= '9') || (ch === '.' && src[i + 1] >= '0' && src[i + 1] <= '9')) {
      const start = i;
      if (ch === '0' && (src[i + 1] === 'x' || src[i + 1] === 'X')) {
        i += 2; while (i < n && /[0-9a-fA-F_]/.test(src[i])) i++;
        toks.push({ t: 'NUM', v: Number(src.slice(start, i).replace(/_/g, '')), l: line });
      } else {
        while (i < n && /[0-9._]/.test(src[i])) i++;
        if (i < n && (src[i] === 'e' || src[i] === 'E')) {
          i++; if (src[i] === '+' || src[i] === '-') i++;
          while (i < n && /[0-9]/.test(src[i])) i++;
        }
        toks.push({ t: 'NUM', v: Number(src.slice(start, i).replace(/_/g, '')), l: line });
      }
      continue;
    }
    if (/[a-zA-Z_]/.test(ch)) {
      const start = i; while (i < n && /[a-zA-Z0-9_]/.test(src[i])) i++;
      const w = src.slice(start, i);
      toks.push({ t: kw.has(w) ? 'KW' : 'ID', v: w, l: line });
      continue;
    }
    const three = src.slice(i, i + 3);
    if (three === '...') { toks.push({ t: 'SYM', v: '...', l: line }); i += 3; continue; }
    const two = src.slice(i, i + 2);
    if (['..', '==', '~=', '<=', '>='].includes(two)) { toks.push({ t: 'SYM', v: two, l: line }); i += 2; continue; }
    toks.push({ t: 'SYM', v: ch, l: line }); i++;
  }
  toks.push({ t: 'EOF', v: '', l: line });
  return toks;
}

function parseLuaForVM(toks) {
  let pos = 0;
  const peek = (o = 0) => toks[pos + o] || toks[toks.length - 1];
  const next = () => toks[pos++];
  const match = (t, v) => { const p = peek(); if (p.t === t && (v === undefined || p.v === v)) { pos++; return p; } return null; };
  const expect = (t, v) => { const m = match(t, v); if (!m) throw new Error(`VM Parse error at line ${peek().l}: expected ${v || t}, got ${peek().v}`); return m; };
  const isBlockEnd = () => { const p = peek(); return p.t === 'EOF' || (p.t === 'KW' && (p.v === 'end' || p.v === 'else' || p.v === 'elseif' || p.v === 'until')); };

  function parseBlock() {
    const stmts = [];
    while (!isBlockEnd()) {
      if (match('SYM', ';')) continue;
      const st = parseStmt();
      if (st) stmts.push(st);
      match('SYM', ';');
      if (st && (st.type === 'Return' || st.type === 'Break')) break;
    }
    return stmts;
  }

  function parseFuncBody(hasSelf) {
    expect('SYM', '(');
    const params = hasSelf ? ['self'] : [];
    let isVararg = false;
    if (!match('SYM', ')')) {
      while (true) {
        if (match('SYM', '...')) { isVararg = true; match('SYM', ','); break; }
        params.push(expect('ID').v);
        if (!match('SYM', ',')) break;
      }
      expect('SYM', ')');
    }
    const body = parseBlock();
    expect('KW', 'end');
    return { type: 'FuncExpr', params, isVararg, body };
  }

  function parseStmt() {
    const p = peek();
    if (p.t === 'KW' && p.v === 'local') {
      next();
      if (match('KW', 'function')) {
        const name = expect('ID').v;
        return { type: 'LocalFunc', name, fn: parseFuncBody(false) };
      }
      const names = [expect('ID').v];
      while (match('SYM', ',')) names.push(expect('ID').v);
      let init = [];
      if (match('SYM', '=')) init = parseExprList();
      return { type: 'Local', names, init };
    }
    if (p.t === 'KW' && p.v === 'function') {
      next();
      let expr = { type: 'Id', v: expect('ID').v };
      while (match('SYM', '.')) expr = { type: 'Member', obj: expr, prop: expect('ID').v };
      let hasSelf = false;
      if (match('SYM', ':')) { expr = { type: 'Member', obj: expr, prop: expect('ID').v }; hasSelf = true; }
      return { type: 'Assign', lhs: [expr], rhs: [parseFuncBody(hasSelf)] };
    }
    if (p.t === 'KW' && p.v === 'if') {
      next();
      const branches = [];
      const c0 = parseExpr(); expect('KW', 'then'); const b0 = parseBlock();
      branches.push({ cond: c0, body: b0 });
      while (match('KW', 'elseif')) {
        const c = parseExpr(); expect('KW', 'then'); const b = parseBlock();
        branches.push({ cond: c, body: b });
      }
      let elseBody = null;
      if (match('KW', 'else')) elseBody = parseBlock();
      expect('KW', 'end');
      return { type: 'If', branches, elseBody };
    }
    if (p.t === 'KW' && p.v === 'while') {
      next(); const cond = parseExpr(); expect('KW', 'do'); const body = parseBlock(); expect('KW', 'end');
      return { type: 'While', cond, body };
    }
    if (p.t === 'KW' && p.v === 'do') {
      next(); const body = parseBlock(); expect('KW', 'end');
      return { type: 'Do', body };
    }
    if (p.t === 'KW' && p.v === 'for') {
      next();
      const v1 = expect('ID').v;
      if (match('SYM', '=')) {
        const start = parseExpr(); expect('SYM', ','); const stop = parseExpr();
        const step = match('SYM', ',') ? parseExpr() : { type: 'Num', v: 1 };
        expect('KW', 'do'); const body = parseBlock(); expect('KW', 'end');
        return { type: 'NumFor', var: v1, start, stop, step, body };
      }
      const vars = [v1];
      while (match('SYM', ',')) vars.push(expect('ID').v);
      expect('KW', 'in'); const iters = parseExprList(); expect('KW', 'do'); const body = parseBlock(); expect('KW', 'end');
      return { type: 'GenFor', vars, iters, body };
    }
    if (p.t === 'KW' && p.v === 'return') {
      next();
      const vals = (isBlockEnd() || peek().v === ';') ? [] : parseExprList();
      return { type: 'Return', vals };
    }
    if (p.t === 'KW' && p.v === 'break') { next(); return { type: 'Break' }; }
    const expr = parsePrimary();
    if (peek().v === ',' || peek().v === '=') {
      const lhs = [expr];
      while (match('SYM', ',')) lhs.push(parsePrimary());
      expect('SYM', '=');
      const rhs = parseExprList();
      return { type: 'Assign', lhs, rhs };
    }
    return { type: 'CallStmt', expr };
  }

  function parseExprList() {
    const arr = [parseExpr()];
    while (match('SYM', ',')) arr.push(parseExpr());
    return arr;
  }

  const PREC = { or: 1, and: 2, '<': 3, '>': 3, '<=': 3, '>=': 3, '~=': 3, '==': 3, '..': 4, '+': 5, '-': 5, '*': 6, '/': 6, '%': 6, '^': 8 };
  function parseExpr(minP = 1) {
    let left;
    const p = peek();
    if ((p.t === 'KW' && p.v === 'not') || (p.t === 'SYM' && (p.v === '-' || p.v === '#'))) {
      next();
      left = { type: 'UnOp', op: p.v, arg: parseExpr(7) };
    } else {
      left = parseSimple();
    }
    while (true) {
      const opTok = peek();
      const op = (opTok.t === 'KW' && (opTok.v === 'and' || opTok.v === 'or')) || opTok.t === 'SYM' ? opTok.v : null;
      const pr = op ? PREC[op] : 0;
      if (!pr || pr < minP) break;
      next();
      const right = parseExpr(op === '^' || op === '..' ? pr : pr + 1);
      left = { type: 'BinOp', op, left, right };
    }
    return left;
  }

  function parseSimple() {
    const p = peek();
    if (p.t === 'KW' && p.v === 'nil') { next(); return { type: 'Nil' }; }
    if (p.t === 'KW' && p.v === 'true') { next(); return { type: 'Bool', v: true }; }
    if (p.t === 'KW' && p.v === 'false') { next(); return { type: 'Bool', v: false }; }
    if (p.t === 'NUM') { next(); return { type: 'Num', v: p.v }; }
    if (p.t === 'STR') { next(); return { type: 'Str', v: p.v }; }
    if (p.t === 'SYM' && p.v === '...') { next(); return { type: 'Vararg' }; }
    if (p.t === 'KW' && p.v === 'function') { next(); return parseFuncBody(false); }
    if (p.t === 'SYM' && p.v === '{') return parseTable();
    return parsePrimary();
  }

  function parseTable() {
    expect('SYM', '{');
    const fields = [];
    while (!match('SYM', '}')) {
      if (match('SYM', '[')) {
        const k = parseExpr(); expect('SYM', ']'); expect('SYM', '='); const v = parseExpr();
        fields.push({ k, v });
      } else if (peek().t === 'ID' && peek(1).v === '=') {
        const k = { type: 'Str', v: next().v }; expect('SYM', '='); const v = parseExpr();
        fields.push({ k, v });
      } else {
        fields.push({ k: null, v: parseExpr() });
      }
      if (!match('SYM', ',') && !match('SYM', ';')) { expect('SYM', '}'); break; }
    }
    return { type: 'Table', fields };
  }

  function parseArgs() {
    if (peek().t === 'STR') return [{ type: 'Str', v: next().v }];
    if (peek().v === '{') return [parseTable()];
    expect('SYM', '(');
    const args = [];
    if (!match('SYM', ')')) {
      args.push(...parseExprList());
      expect('SYM', ')');
    }
    return args;
  }

  function parsePrimary() {
    let e;
    if (match('SYM', '(')) { e = parseExpr(); expect('SYM', ')'); }
    else e = { type: 'Id', v: expect('ID').v };
    while (true) {
      if (match('SYM', '.')) e = { type: 'Member', obj: e, prop: expect('ID').v };
      else if (match('SYM', '[')) { const k = parseExpr(); expect('SYM', ']'); e = { type: 'Index', obj: e, key: k }; }
      else if (match('SYM', ':')) { const m = expect('ID').v; e = { type: 'MethodCall', obj: e, prop: m, args: parseArgs() }; }
      else if (peek().v === '(' || peek().v === '{' || peek().t === 'STR') e = { type: 'Call', fn: e, args: parseArgs() };
      else break;
    }
    return e;
  }

  return parseBlock();
}

function compileLuaProto(params, isVararg, stmts, parentScope) {
  const code = [];
  const consts = [];
  const constMap = new Map();
  const protos = [];
  const upvals = [];
  const locals = [];
  let maxRegs = 0;
  let nextReg = 0;

  const alloc = (count = 1) => { const r = nextReg; nextReg += count; if (nextReg > maxRegs) maxRegs = nextReg; return r; };
  const addK = (val) => {
    const tag = (typeof val) + ':' + String(val);
    if (constMap.has(tag)) return constMap.get(tag);
    const idx = consts.length;
    consts.push(val);
    constMap.set(tag, idx);
    return idx;
  };
  const emit = (op, a = 0, b = 0, c = 0) => { code.push([op, a, b, c]); return code.length - 1; };
  const patchJmp = (idx, target) => { code[idx][2] = target; };

  const scope = {
    vars: new Map(),
    parent: parentScope,
    resolve(name) {
      if (this.vars.has(name)) return { kind: 'local', reg: this.vars.get(name) };
      if (this.parent) {
        const res = this.parent.resolve(name);
        if (res.kind === 'local') {
          let uid = upvals.findIndex(u => u.inStack && u.idx === res.reg);
          if (uid === -1) { uid = upvals.length; upvals.push({ inStack: true, idx: res.reg }); }
          return { kind: 'upval', idx: uid };
        }
        if (res.kind === 'upval') {
          let uid = upvals.findIndex(u => !u.inStack && u.idx === res.idx);
          if (uid === -1) { uid = upvals.length; upvals.push({ inStack: false, idx: res.idx }); }
          return { kind: 'upval', idx: uid };
        }
      }
      return { kind: 'global', k: addK(name) };
    }
  };

  params.forEach(p => { const r = alloc(1); scope.vars.set(p, r); locals.push(r); });
  const loopBreaks = [];

  function compExpr(e, dest) {
    if (e.type === 'Nil') { emit('LOADNIL', dest, 0, 0); return dest; }
    if (e.type === 'Bool') { emit('LOADBOOL', dest, e.v ? 1 : 0, 0); return dest; }
    if (e.type === 'Num' || e.type === 'Str') { emit('LOADK', dest, addK(e.v), 0); return dest; }
    if (e.type === 'Id') {
      const r = scope.resolve(e.v);
      if (r.kind === 'local') { if (r.reg !== dest) emit('MOVE', dest, r.reg, 0); }
      else if (r.kind === 'upval') emit('GETUPVAL', dest, r.idx, 0);
      else emit('GETGLOBAL', dest, r.k, 0);
      return dest;
    }
    if (e.type === 'Member' || e.type === 'Index') {
      const objR = alloc(1); compExpr(e.obj, objR);
      const keyR = alloc(1);
      if (e.type === 'Member') emit('LOADK', keyR, addK(e.prop), 0);
      else compExpr(e.key, keyR);
      emit('GETTABLE', dest, objR, keyR);
      nextReg -= 2; return dest;
    }
    if (e.type === 'Table') {
      emit('NEWTABLE', dest, 0, 0);
      let arrIdx = 1;
      for (const f of e.fields) {
        const kr = alloc(1), vr = alloc(1);
        if (f.k === null) emit('LOADK', kr, addK(arrIdx++), 0);
        else compExpr(f.k, kr);
        compExpr(f.v, vr);
        emit('SETTABLE', dest, kr, vr);
        nextReg -= 2;
      }
      return dest;
    }
    if (e.type === 'UnOp') {
      const ar = alloc(1); compExpr(e.arg, ar);
      const op = e.op === 'not' ? 'NOT' : (e.op === '#' ? 'LEN' : 'UNM');
      emit(op, dest, ar, 0);
      nextReg -= 1; return dest;
    }
    if (e.type === 'BinOp') {
      if (e.op === 'and' || e.op === 'or') {
        compExpr(e.left, dest);
        const j = emit(e.op === 'and' ? 'JMPIFNOT' : 'JMPIF', dest, 0, 0);
        compExpr(e.right, dest);
        patchJmp(j, code.length);
        return dest;
      }
      const lr = alloc(1); compExpr(e.left, lr);
      const rr = alloc(1); compExpr(e.right, rr);
      const map = { '+': 'ADD', '-': 'SUB', '*': 'MUL', '/': 'DIV', '%': 'MOD', '^': 'POW', '..': 'CONCAT', '==': 'EQ', '<': 'LT', '<=': 'LE' };
      if (map[e.op]) emit(map[e.op], dest, lr, rr);
      else if (e.op === '~=') { emit('EQ', dest, lr, rr); emit('NOT', dest, dest, 0); }
      else if (e.op === '>') emit('LT', dest, rr, lr);
      else if (e.op === '>=') emit('LE', dest, rr, lr);
      nextReg -= 2; return dest;
    }
    if (e.type === 'FuncExpr') {
      const pIdx = protos.length;
      protos.push(compileLuaProto(e.params, e.isVararg, e.body, scope));
      emit('CLOSURE', dest, pIdx, 0);
      return dest;
    }
    if (e.type === 'Call' || e.type === 'MethodCall') {
      return compCall(e, dest, 1);
    }
    emit('LOADNIL', dest, 0, 0);
    return dest;
  }

  function compCall(e, base, nRet) {
    const saved = nextReg;
    if (nextReg < base + 1) nextReg = base + 1;
    if (e.type === 'MethodCall') {
      const objR = alloc(1); compExpr(e.obj, objR);
      const mKeyR = alloc(1); emit('LOADK', mKeyR, addK(e.prop), 0);
      emit('SELF', base, objR, mKeyR);
      nextReg = base + 2;
      for (const a of e.args) { const ar = alloc(1); compExpr(a, ar); }
      emit('CALL', base, e.args.length + 1, nRet);
    } else {
      compExpr(e.fn, base);
      nextReg = base + 1;
      for (const a of e.args) { const ar = alloc(1); compExpr(a, ar); }
      emit('CALL', base, e.args.length, nRet);
    }
    nextReg = saved;
    return base;
  }

  function compStmt(st) {
    if (st.type === 'Do') {
      const savedVars = new Map(scope.vars);
      const savedReg = nextReg;
      st.body.forEach(compStmt);
      scope.vars = savedVars; nextReg = savedReg; return;
    }
    if (st.type === 'LocalFunc') {
      const r = alloc(1); scope.vars.set(st.name, r); locals.push(r);
      compExpr(st.fn, r); return;
    }
    if (st.type === 'Local') {
      const regs = st.names.map(() => alloc(1));
      if (st.init.length === 1 && (st.init[0].type === 'Call' || st.init[0].type === 'MethodCall') && st.names.length > 1) {
        compCall(st.init[0], regs[0], st.names.length);
      } else {
        for (let idx = 0; idx < regs.length; idx++) {
          if (idx < st.init.length) compExpr(st.init[idx], regs[idx]);
          else emit('LOADNIL', regs[idx], 0, 0);
        }
      }
      st.names.forEach((nm, idx) => { scope.vars.set(nm, regs[idx]); locals.push(regs[idx]); });
      return;
    }
    if (st.type === 'Assign') {
      const vals = [];
      if (st.rhs.length === 1 && (st.rhs[0].type === 'Call' || st.rhs[0].type === 'MethodCall') && st.lhs.length > 1) {
        const base = alloc(st.lhs.length);
        compCall(st.rhs[0], base, st.lhs.length);
        for (let idx = 0; idx < st.lhs.length; idx++) vals.push(base + idx);
      } else {
        for (let idx = 0; idx < st.lhs.length; idx++) {
          const vr = alloc(1);
          if (idx < st.rhs.length) compExpr(st.rhs[idx], vr);
          else emit('LOADNIL', vr, 0, 0);
          vals.push(vr);
        }
      }
      for (let idx = 0; idx < st.lhs.length; idx++) {
        const lh = st.lhs[idx], vr = vals[idx];
        if (lh.type === 'Id') {
          const r = scope.resolve(lh.v);
          if (r.kind === 'local') emit('MOVE', r.reg, vr, 0);
          else if (r.kind === 'upval') emit('SETUPVAL', vr, r.idx, 0);
          else emit('SETGLOBAL', vr, r.k, 0);
        } else {
          const or = alloc(1), kr = alloc(1);
          compExpr(lh.obj, or);
          if (lh.type === 'Member') emit('LOADK', kr, addK(lh.prop), 0);
          else compExpr(lh.key, kr);
          emit('SETTABLE', or, kr, vr);
          nextReg -= 2;
        }
      }
      nextReg -= vals.length; return;
    }
    if (st.type === 'CallStmt') {
      const br = alloc(1); compCall(st.expr, br, 0); nextReg -= 1; return;
    }
    if (st.type === 'If') {
      const endJmps = [];
      for (const br of st.branches) {
        const cr = alloc(1); compExpr(br.cond, cr); nextReg -= 1;
        const jFalse = emit('JMPIFNOT', cr, 0, 0);
        const savedVars = new Map(scope.vars), savedReg = nextReg;
        br.body.forEach(compStmt);
        scope.vars = savedVars; nextReg = savedReg;
        endJmps.push(emit('JMP', 0, 0, 0));
        patchJmp(jFalse, code.length);
      }
      if (st.elseBody) {
        const savedVars = new Map(scope.vars), savedReg = nextReg;
        st.elseBody.forEach(compStmt);
        scope.vars = savedVars; nextReg = savedReg;
      }
      endJmps.forEach(j => patchJmp(j, code.length));
      return;
    }
    if (st.type === 'While') {
      const top = code.length;
      const cr = alloc(1); compExpr(st.cond, cr); nextReg -= 1;
      const jExit = emit('JMPIFNOT', cr, 0, 0);
      const brks = []; loopBreaks.push(brks);
      const savedVars = new Map(scope.vars), savedReg = nextReg;
      st.body.forEach(compStmt);
      scope.vars = savedVars; nextReg = savedReg;
      emit('JMP', 0, top, 0);
      patchJmp(jExit, code.length);
      loopBreaks.pop();
      brks.forEach(b => patchJmp(b, code.length));
      return;
    }
    if (st.type === 'NumFor') {
      const base = alloc(4);
      compExpr(st.start, base); compExpr(st.stop, base + 1); compExpr(st.step, base + 2);
      const jPrep = emit('FORPREP', base, 0, 0);
      const bodyTop = code.length;
      const brks = []; loopBreaks.push(brks);
      const savedVars = new Map(scope.vars), savedReg = nextReg;
      scope.vars.set(st.var, base + 3); locals.push(base + 3);
      st.body.forEach(compStmt);
      scope.vars = savedVars; nextReg = savedReg;
      patchJmp(jPrep, code.length);
      emit('FORLOOP', base, bodyTop, 0);
      loopBreaks.pop();
      brks.forEach(b => patchJmp(b, code.length));
      nextReg -= 4; return;
    }
    if (st.type === 'GenFor') {
      const base = alloc(3 + st.vars.length);
      if (st.iters.length === 1 && (st.iters[0].type === 'Call' || st.iters[0].type === 'MethodCall')) {
        compCall(st.iters[0], base, 3);
      } else {
        if (st.iters[0]) compExpr(st.iters[0], base); else emit('LOADNIL', base, 0, 0);
        if (st.iters[1]) compExpr(st.iters[1], base + 1); else emit('LOADNIL', base + 1, 0, 0);
        if (st.iters[2]) compExpr(st.iters[2], base + 2); else emit('LOADNIL', base + 2, 0, 0);
      }
      const jTop = emit('JMP', 0, 0, 0);
      const bodyTop = code.length;
      const brks = []; loopBreaks.push(brks);
      const savedVars = new Map(scope.vars), savedReg = nextReg;
      st.vars.forEach((vn, idx) => { scope.vars.set(vn, base + 3 + idx); locals.push(base + 3 + idx); });
      st.body.forEach(compStmt);
      scope.vars = savedVars; nextReg = savedReg;
      patchJmp(jTop, code.length);
      emit('TFORCALL', base, st.vars.length, bodyTop);
      loopBreaks.pop();
      brks.forEach(b => patchJmp(b, code.length));
      nextReg -= (3 + st.vars.length); return;
    }
    if (st.type === 'Break') {
      if (loopBreaks.length) loopBreaks[loopBreaks.length - 1].push(emit('JMP', 0, 0, 0));
      return;
    }
    if (st.type === 'Return') {
      if (!st.vals.length) { emit('RETURN', 0, 0, 0); return; }
      const base = alloc(st.vals.length);
      st.vals.forEach((v, idx) => compExpr(v, base + idx));
      emit('RETURN', base, st.vals.length, 0);
      nextReg -= st.vals.length; return;
    }
  }

  stmts.forEach(compStmt);
  emit('RETURN', 0, 0, 0);
  return { code, consts, protos, upvals, numParams: params.length, maxRegs };
}

function buildRandomizedVM(luaSrc, gateBuildId, gateKeyBuf, apiBaseUrl) {
  const cleanSrc = stripLuaComments(luaSrc);
  const ast = parseLuaForVM(tokenizeLuaForVM(cleanSrc));
  const rootProto = compileLuaProto([], false, ast, null);

  // Per-build randomized opcode mapping (0..255)
  const pool = Array.from({ length: 256 }, (_, i) => i);
  for (let i = pool.length - 1; i > 0; i--) {
    const j = crypto.randomInt(0, i + 1);
    const t = pool[i]; pool[i] = pool[j]; pool[j] = t;
  }
  const opMap = {};
  VM_OP_NAMES.forEach((nm, idx) => { opMap[nm] = pool[idx]; });

  // Per-build randomized handler dispatch registration order
  const dispatchOrder = VM_OP_NAMES.slice();
  for (let i = dispatchOrder.length - 1; i > 0; i--) {
    const j = crypto.randomInt(0, i + 1);
    const t = dispatchOrder[i]; dispatchOrder[i] = dispatchOrder[j]; dispatchOrder[j] = t;
  }

  const CLEAN_MASK = 0xA5;
  const constSalt = crypto.randomInt(17, 240);

  function serializeProto(pr) {
    const encCodeBytes = [];
    for (let pc = 0; pc < pr.code.length; pc++) {
      const [opName, a, b, c] = pr.code[pc];
      const opByte = opMap[opName];
      const kByte = gateKeyBuf[pc % gateKeyBuf.length];
      encCodeBytes.push(opByte ^ kByte ^ CLEAN_MASK);
      encCodeBytes.push(a & 0xFF, (a >> 8) & 0xFF);
      encCodeBytes.push(b & 0xFF, (b >> 8) & 0xFF);
      encCodeBytes.push(c & 0xFF, (c >> 8) & 0xFF);
    }
    const encConsts = pr.consts.map((val, cIdx) => {
      if (typeof val === 'number') {
        const s = String(val);
        const raw = Buffer.from(s, 'utf8');
        const out = Buffer.allocUnsafe(raw.length);
        for (let i = 0; i < raw.length; i++) out[i] = raw[i] ^ gateKeyBuf[(i + cIdx) % gateKeyBuf.length] ^ constSalt;
        return [1, out.toString('base64')];
      }
      const raw = Buffer.from(String(val), 'utf8');
      const out = Buffer.allocUnsafe(raw.length);
      for (let i = 0; i < raw.length; i++) out[i] = raw[i] ^ gateKeyBuf[(i + cIdx) % gateKeyBuf.length] ^ constSalt;
      return [2, out.toString('base64')];
    });
    return {
      c: Buffer.from(encCodeBytes).toString('base64'),
      n: pr.code.length,
      k: encConsts,
      p: pr.protos.map(serializeProto),
      u: pr.upvals.map(u => [u.inStack ? 1 : 0, u.idx]),
      a: pr.numParams
    };
  }

  const serializedRoot = serializeProto(rootProto);
  const v = '_0x' + crypto.randomBytes(2).toString('hex');

  const handlerBodies = {
    LOADK: `local ${v}d=${v}dk(${v}p.k[${v}B+1],${v}B);${v}R[${v}A]=${v}d;${v}d=nil`,
    LOADBOOL: `${v}R[${v}A]=(${v}B==1)`,
    LOADNIL: `${v}R[${v}A]=nil`,
    MOVE: `${v}R[${v}A]=${v}R[${v}B]`,
    ADD: `${v}R[${v}A]=${v}R[${v}B]+${v}R[${v}C]`,
    SUB: `${v}R[${v}A]=${v}R[${v}B]-${v}R[${v}C]`,
    MUL: `${v}R[${v}A]=${v}R[${v}B]*${v}R[${v}C]`,
    DIV: `${v}R[${v}A]=${v}R[${v}B]/${v}R[${v}C]`,
    MOD: `${v}R[${v}A]=${v}R[${v}B]%${v}R[${v}C]`,
    POW: `${v}R[${v}A]=${v}R[${v}B]^${v}R[${v}C]`,
    CONCAT: `${v}R[${v}A]=tostring(${v}R[${v}B])..tostring(${v}R[${v}C])`,
    EQ: `${v}R[${v}A]=(${v}R[${v}B]==${v}R[${v}C])`,
    LT: `${v}R[${v}A]=(${v}R[${v}B]<${v}R[${v}C])`,
    LE: `${v}R[${v}A]=(${v}R[${v}B]<=${v}R[${v}C])`,
    NOT: `${v}R[${v}A]=not ${v}R[${v}B]`,
    LEN: `${v}R[${v}A]=#${v}R[${v}B]`,
    UNM: `${v}R[${v}A]=-${v}R[${v}B]`,
    JMP: `${v}pc=${v}B;${v}jmp=true`,
    JMPIF: `if ${v}R[${v}A] then ${v}pc=${v}B;${v}jmp=true end`,
    JMPIFNOT: `if not ${v}R[${v}A] then ${v}pc=${v}B;${v}jmp=true end`,
    CALL: `local ${v}ag={};for ${v}z=1,${v}B do ${v}ag[${v}z]=${v}R[${v}A+${v}z]end;local ${v}rt={${v}R[${v}A](table.unpack(${v}ag,1,${v}B))};for ${v}z=1,${v}C do ${v}R[${v}A+${v}z-1]=${v}rt[${v}z]end`,
    RETURN: `if ${v}B==0 then return end;local ${v}rt={};for ${v}z=0,${v}B-1 do ${v}rt[${v}z+1]=${v}R[${v}A+${v}z]end;return table.unpack(${v}rt,1,${v}B)`,
    GETTABLE: `${v}R[${v}A]=${v}R[${v}B][${v}R[${v}C]]`,
    SETTABLE: `${v}R[${v}A][${v}R[${v}B]]=${v}R[${v}C]`,
    GETGLOBAL: `local ${v}g=${v}dk(${v}p.k[${v}B+1],${v}B);${v}R[${v}A]=${v}env[${v}g];${v}g=nil`,
    SETGLOBAL: `local ${v}g=${v}dk(${v}p.k[${v}B+1],${v}B);${v}env[${v}g]=${v}R[${v}A];${v}g=nil`,
    NEWTABLE: `${v}R[${v}A]={}`,
    SELF: `${v}R[${v}A+1]=${v}R[${v}B];${v}R[${v}A]=${v}R[${v}B][${v}R[${v}C]]`,
    CLOSURE: `local ${v}cp=${v}p.p[${v}B+1];local ${v}nu={};for ${v}z=1,#${v}cp.u do local ${v}ud=${v}cp.u[${v}z];if ${v}ud[1]==1 then if not ${v}uv[${v}ud[2]] then ${v}uv[${v}ud[2]]={v=${v}R[${v}ud[2]],l=${v}R[${v}ud[2]]}end;${v}nu[${v}z]=${v}uv[${v}ud[2]]else ${v}nu[${v}z]=${v}U[${v}ud[2]+1]end end;${v}R[${v}A]=${v}mk(${v}cp,${v}nu)`,
    GETUPVAL: `${v}R[${v}A]=${v}U[${v}B+1].v`,
    SETUPVAL: `${v}U[${v}B+1].v=${v}R[${v}A]`,
    FORPREP: `${v}R[${v}A]=${v}R[${v}A]-${v}R[${v}A+2];${v}pc=${v}B;${v}jmp=true`,
    FORLOOP: `${v}R[${v}A]=${v}R[${v}A]+${v}R[${v}A+2];local ${v}st=${v}R[${v}A+2];if (${v}st>0 and ${v}R[${v}A]<=${v}R[${v}A+1]) or (${v}st<=0 and ${v}R[${v}A]>=${v}R[${v}A+1]) then ${v}R[${v}A+3]=${v}R[${v}A];${v}pc=${v}B;${v}jmp=true end`,
    TFORCALL: `local ${v}rt={${v}R[${v}A](${v}R[${v}A+1],${v}R[${v}A+2])};for ${v}z=1,${v}B do ${v}R[${v}A+2+${v}z]=${v}rt[${v}z]end;if ${v}R[${v}A+3]~=nil then ${v}R[${v}A+2]=${v}R[${v}A+3];${v}pc=${v}C;${v}jmp=true end`
  };

  const dispatchRegLines = dispatchOrder.map(nm => {
    if (nm === 'RETURN') {
      return `${v}dt[${opMap[nm]}]=function(${v}A,${v}B,${v}C,${v}R,${v}U,${v}p,${v}uv)${handlerBodies[nm]} end`;
    }
    return `${v}dt[${opMap[nm]}]=function(${v}A,${v}B,${v}C,${v}R,${v}U,${v}p,${v}uv)local ${v}jmp=false;local ${v}pc=nil;${handlerBodies[nm]};return ${v}jmp,${v}pc end`;
  }).join(';');

  const protoLuaLiteral = JSON.stringify(JSON.stringify(serializedRoot));
  return [
    `(function(${v}env,${v}ld,${v}rq,${v}hr,${v}sr,${v}db,${v}b32,${v}pl,${v}hs)`,
    `local ${v}chk=function()local ${v}m=${CLEAN_MASK};local ${v}t={${v}ld,${v}rq,${v}hr,${v}sr,game.HttpGet};for _,${v}f in ipairs(${v}t) do if type(${v}f)=="function" then if type(isfunctionhooked)=="function" then local ${v}o,${v}h=pcall(isfunctionhooked,${v}f);if ${v}o and ${v}h then ${v}m=${v}b32.bxor(${v}m,0x98)end end;if type(islclosure)=="function" then local ${v}o,${v}l=pcall(islclosure,${v}f);if ${v}o and ${v}l then ${v}m=${v}b32.bxor(${v}m,0x98)end end;if ${v}db and type(${v}db.getupvalues)=="function" then local ${v}o,${v}u=pcall(${v}db.getupvalues,${v}f);if ${v}o and type(${v}u)=="table" and #${v}u>0 then ${v}m=${v}b32.bxor(${v}m,0x98)end end end end;return ${v}m end;`,
    `local ${v}key=nil;local ${v}sk=${v}env.getgenv and ${v}env.getgenv().script_key;`,
    `if not ${v}sk or ${v}sk=="" then local ${v}lp=${v}pl.LocalPlayer;if ${v}lp then ${v}lp:Kick("No script_key detected. Please set getgenv().script_key = 'YOUR-KEY-HERE'")end;return end;`,
    `local ${v}lp=${v}pl.LocalPlayer;local ${v}sg={tostring(${v}lp and ${v}lp.UserId or "0")};if ${v}env.getmachineidentifier then local ${v}o,${v}m=pcall(${v}env.getmachineidentifier);if ${v}o and ${v}m then ${v}sg[#${v}sg+1]="EXEC:"..tostring(${v}m)end end;if ${v}env.gethwid then local ${v}o,${v}h=pcall(${v}env.gethwid);if ${v}o and ${v}h then ${v}sg[#${v}sg+1]="HWID:"..tostring(${v}h)end end;local ${v}rs=table.concat(${v}sg,"|");local ${v}dh=5381;for ${v}i=1,#${v}rs do ${v}dh=((${v}dh*33)+string.byte(${v}rs,${v}i))%0xFFFFFFFF end;local ${v}hw=string.format("RBX-%s-%08X",tostring(${v}lp and ${v}lp.UserId or "0"),${v}dh);`,
    `local ${v}rf=${v}rq or ${v}hr or ${v}sr or (${v}env.http and ${v}env.http.request) or (${v}env.fluxus and ${v}env.fluxus.request);if not ${v}rf then return end;`,
    `local ${v}ok,${v}res=pcall(${v}rf,{Url="${apiBaseUrl}/api/vm-key",Method="POST",Headers={["Content-Type"]="application/json"},Body=${v}hs:JSONEncode({buildId="${gateBuildId}",key=tostring(${v}sk),hwid=${v}hw})});`,
    `if not ${v}ok or not ${v}res or not ${v}res.Body then if ${v}lp then ${v}lp:Kick("Failed to connect to authentication server.")end;return end;`,
    `local ${v}jok,${v}jd=pcall(${v}hs.JSONDecode,${v}hs,${v}res.Body);`,
    `if not ${v}jok or type(${v}jd)~="table" or not ${v}jd.ok or not ${v}jd.k then if ${v}lp then ${v}lp:Kick((type(${v}jd)=="table" and ${v}jd.error) or "Authentication failed.")end;return end;`,
    `local ${v}kb={};for ${v}i=1,#${v}jd.k,2 do ${v}kb[#${v}kb+1]=tonumber(${v}jd.k:sub(${v}i,${v}i+1),16)end;`,
    `local ${v}b64="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";`,
    `local ${v}bd=function(${v}s)${v}s=string.gsub(${v}s,"[^"..${v}b64.."=]","");return(${v}s:gsub(".",function(${v}x)if ${v}x=="=" then return""end;local ${v}r,${v}v="",(${v}b64:find(${v}x)-1);for ${v}i=6,1,-1 do ${v}r=${v}r..(${v}v%2^${v}i-${v}v%2^(${v}i-1)>0 and"1"or"0")end;return ${v}r end):gsub("%d%d%d?%d?%d?%d?%d?%d?",function(${v}x)if #${v}x~=8 then return""end;local ${v}c=0;for ${v}i=1,8 do ${v}c=${v}c+(${v}x:sub(${v}i,${v}i)=="1"and 2^(8-${v}i)or 0)end;return string.char(${v}c)end))end;`,
    `local ${v}dk=function(${v}ce,${v}ci)local ${v}raw=${v}bd(${v}ce[2]);local ${v}out=table.create(#${v}raw);for ${v}i=1,#${v}raw do ${v}out[${v}i]=string.char(${v}b32.bxor(string.byte(${v}raw,${v}i),${v}kb[((${v}i-1+${v}ci)%#${v}kb)+1],${constSalt}))end;local ${v}st=table.concat(${v}out);if ${v}ce[1]==1 then return tonumber(${v}st)end;return ${v}st end;`,
    `local ${v}dt={};local ${v}mk;${dispatchRegLines};`,
    `${v}mk=function(${v}p,${v}U)return function(...)local ${v}R={};local ${v}ag={...};for ${v}i=1,${v}p.a do ${v}R[${v}i-1]=${v}ag[${v}i]end;local ${v}uv={};local ${v}cb=${v}p._cb;if not ${v}cb then ${v}cb=${v}bd(${v}p.c);${v}p._cb=${v}cb end;local ${v}pc=0;local ${v}cm=${v}chk();while true do if ${v}pc>=${v}p.n then break end;if ${v}pc%4096==0 then ${v}cm=${v}chk()end;local ${v}o=${v}pc*7+1;local ${v}op=${v}b32.bxor(string.byte(${v}cb,${v}o),${v}kb[(${v}pc%#${v}kb)+1],${v}cm);local ${v}A=string.byte(${v}cb,${v}o+1)+string.byte(${v}cb,${v}o+2)*256;local ${v}B=string.byte(${v}cb,${v}o+3)+string.byte(${v}cb,${v}o+4)*256;local ${v}C=string.byte(${v}cb,${v}o+5)+string.byte(${v}cb,${v}o+6)*256;local ${v}h=${v}dt[${v}op];if not ${v}h then break end;local ${v}r1,${v}r2,${v}r3,${v}r4=${v}h(${v}A,${v}B,${v}C,${v}R,${v}U,${v}p,${v}uv);if next(${v}uv)~=nil then for ${v}k,${v}c in pairs(${v}uv)do if ${v}R[${v}k]~=${v}c.l then ${v}c.v=${v}R[${v}k];${v}c.l=${v}R[${v}k]elseif ${v}c.v~=${v}c.l then ${v}R[${v}k]=${v}c.v;${v}c.l=${v}c.v end end end;if ${v}op==${opMap.RETURN} then return ${v}r1,${v}r2,${v}r3,${v}r4 elseif ${v}r1==true then ${v}pc=${v}r2 else ${v}pc=${v}pc+1 end end end end;`,
    `local ${v}rt=${v}hs:JSONDecode(${protoLuaLiteral});${v}mk(${v}rt,{})()`,
    `end)(getfenv and getfenv() or _G,loadstring,request,http_request,syn and syn.request,debug,bit32,game:GetService("Players"),game:GetService("HttpService"))`
  ].join('\n');
}

app.post('/api/vm-key', loaderLimiter, async (req, res) => {
  try {
    await ensureDbConnected(5000).catch(() => false);
    const { buildId, key, hwid } = req.body || {};
    let entry = null;
    if (buildId && vmGateKeys.has(buildId)) {
      entry = vmGateKeys.get(buildId);
      vmGateKeys.delete(buildId);
    }
    if (!entry && buildId) {
      entry = openVmGateToken(String(buildId));
    }
    if (!entry) return res.json({ ok: false, error: 'VM session expired. Re-execute loader.' });
    if (Date.now() > entry.expires) return res.json({ ok: false, error: 'VM session expired.' });
    if (!key) return res.json({ ok: false, error: 'No key provided.' });
    const kd = await Key.findById(String(key).trim()).catch(() => null);
    if (!kd) return res.json({ ok: false, error: 'Invalid license key.' });
    if (kd.blacklisted || kd.status === 'blacklisted') return res.json({ ok: false, error: 'Your key has been blacklisted.' });
    if (kd.status === 'revoked') return res.json({ ok: false, error: 'Your key has been revoked.' });
    if (kd.status === 'suspended') return res.json({ ok: false, error: 'Your key has been suspended.' });
    if (isExpired(kd)) return res.json({ ok: false, error: 'Your key has expired.' });
    if (kd.status !== 'active') return res.json({ ok: false, error: 'Key is not active.' });
    if (hwid && kd.activations && kd.activations.length > 0 && kd.activations[0].hwid && kd.activations[0].hwid !== hwid) {
      return res.json({ ok: false, error: 'Security Error 267: HWID Mismatch! Use HWID reset.' });
    }
    return res.json({ ok: true, k: entry.keyHex });
  } catch (e) {
    return res.json({ ok: false, error: 'Server gate error.' });
  }
});

let _cachedServerCloverCodec = null;
let _customDefaultCloverLua = null;
let _customDefaultForceDisabled = false;
let _customDefaultUpdatedAt = null;
let _defaultCloverTableLoaded = false;
let globalDefaultTableUpdate = 0;

function getServerCloverCodec() {
  if (_cachedServerCloverCodec) return _cachedServerCloverCodec;
  try {
    const dummyHtml = typeof getAppHTMLRaw === 'function' ? getAppHTMLRaw('', false, { username: '', key: '' }) : '';
    const defStart = dummyHtml.indexOf("    'default': [");
    const defEnd = dummyHtml.indexOf("    'legit_aim':", defStart);
    const codecStart = dummyHtml.indexOf("  function vcDeepClone(v) {");
    const codecEnd = dummyHtml.indexOf("  function syncVisualStateToCode() {", codecStart);
    const upStart = dummyHtml.indexOf("  function buildNeutralDefaultClover() {");
    const upEnd = dummyHtml.indexOf("  var CANONICAL_TOP_ORDER =", upStart);
    if (defStart !== -1 && defEnd !== -1 && codecStart !== -1 && codecEnd !== -1 && upStart !== -1 && upEnd !== -1) {
      const defaultBlock = "var defaultPresets = {\n" + dummyHtml.slice(defStart, defEnd).replace(/,\s*$/, '') + "\n};\n";
      const src = defaultBlock + "\n" + dummyHtml.slice(codecStart, codecEnd) + "\n" + dummyHtml.slice(upStart, upEnd) + "\nreturn { builtinDefaultLua: defaultPresets['default'], parseLuaCloverConfig: parseLuaCloverConfig, serializeCloverToLua: serializeCloverToLua, vcUpgradeConfigLua: vcUpgradeConfigLua, vcNormalizeState: vcNormalizeState, vcFillMissingFromDefault: vcFillMissingFromDefault };";
      _cachedServerCloverCodec = new Function(src)();
    }
  } catch (e) {
    console.error('[Clover] getServerCloverCodec error:', e?.message || e);
  }
  return _cachedServerCloverCodec;
}

async function loadDefaultCloverTableFromDb(force = false) {
  try {
    if (typeof Setting === 'undefined' || !mongoose) return;
    if (_defaultCloverTableLoaded && !force) return;
    if (mongoose.connection.readyState !== 1) {
      // Already have a copy in memory: keep serving it rather than falling back to the built-in default.
      if (_defaultCloverTableLoaded) return;
      // Cold start: give Mongo a few seconds to connect so the first page load does NOT get the built-in default.
      for (let i = 0; i < 25 && mongoose.connection.readyState !== 1; i++) {
        await new Promise(r => setTimeout(r, 200));
      }
      if (mongoose.connection.readyState !== 1) return;
    }
    // NOTE: no .catch(() => []) here. A failed query must NOT look like "no custom default saved",
    // otherwise the saved default gets wiped from memory and everyone silently gets the built-in one.
    const docs = await Setting.find({ key: { $in: ['default_clover_table', 'default_clover_force_disabled', 'default_clover_updated_at'] } }).lean();
    const map = {};
    for (const d of docs) {
      if (d && d.key) map[d.key] = d.value;
    }
    _customDefaultCloverLua = (typeof map.default_clover_table === 'string' && map.default_clover_table.trim()) ? map.default_clover_table : null;
    _customDefaultForceDisabled = (map.default_clover_force_disabled === '1' || map.default_clover_force_disabled === 'true');
    _customDefaultUpdatedAt = map.default_clover_updated_at || null;
    _defaultCloverTableLoaded = true;
  } catch (e) {
    console.error('[Clover] loadDefaultCloverTableFromDb error:', e?.message || e);
  }
}

function getDefaultServerCloverLua() {
  if (_customDefaultCloverLua && _customDefaultCloverLua.trim()) return _customDefaultCloverLua;
  const codec = getServerCloverCodec();
  if (codec && typeof codec.builtinDefaultLua === 'string' && codec.builtinDefaultLua.trim()) {
    return codec.builtinDefaultLua;
  }
  return upgradeServerCloverConfigLua('getgenv().Clover = {}');
}

function upgradeServerCloverConfigLua(userLua, overrideDefaultLua, overrideForceDisabled) {
  try {
    if (typeof userLua !== 'string' || !userLua.trim()) return userLua;
    const codec = getServerCloverCodec();
    if (codec && typeof codec.vcUpgradeConfigLua === 'function') {
      const defLua = (typeof overrideDefaultLua === 'string' && overrideDefaultLua.trim()) ? overrideDefaultLua : getDefaultServerCloverLua();
      const useForce = overrideForceDisabled !== undefined ? Boolean(overrideForceDisabled) : Boolean(_customDefaultForceDisabled);
      return codec.vcUpgradeConfigLua(userLua, defLua, useForce);
    }
  } catch (e) {}
  return userLua;
}

function collectAddedTablePaths(prevObj, nextObj, prefix = '') {
  const added = [];
  if (!nextObj || typeof nextObj !== 'object' || Array.isArray(nextObj) || nextObj.__cloverColor3) return added;
  const hasPrev = Boolean(prevObj && typeof prevObj === 'object' && !Array.isArray(prevObj) && !prevObj.__cloverColor3);
  for (const k of Object.keys(nextObj)) {
    const pathKey = prefix ? `${prefix}.${k}` : k;
    const nv = nextObj[k];
    const pv = hasPrev ? prevObj[k] : undefined;
    if (pv === undefined) {
      added.push(pathKey);
    } else if (nv && typeof nv === 'object' && !Array.isArray(nv) && !nv.__cloverColor3 && pv && typeof pv === 'object' && !Array.isArray(pv) && !pv.__cloverColor3) {
      added.push(...collectAddedTablePaths(pv, nv, pathKey));
    }
  }
  return added;
}

app.get('/settings.lua', async (req, res) => {
  res.setHeader('Content-Type', 'text/plain');
  res.setHeader('Cache-Control', 'no-cache, no-store, must-revalidate');
  await loadDefaultCloverTableFromDb();




  const key = typeof req.query.key === 'string' ? req.query.key.trim() : '';

  if (!key) return res.send('-- ERROR: No key provided. Set getgenv().script_key before executing.');

  const kd = await Key.findById(key).catch(() => null);
  if (!kd) return res.send('-- ERROR: Invalid key.');
  if (kd.blacklisted) return res.send('-- ERROR: Your key has been blacklisted.');
  if (kd.status === 'suspended') return res.send('-- ERROR: Your key has been suspended.');
  if (kd.status === 'revoked') return res.send('-- ERROR: Your key has been revoked.');
  if (kd.status === 'blacklisted') return res.send('-- ERROR: Your key has been blacklisted.');
  if (isExpired(kd)) return res.send('-- ERROR: Your key has expired.');
  if (kd.status !== 'active') return res.send('-- ERROR: Key is not active.');


  const clientHWID = req.headers['x-hwid'] || req.headers['hwid'] || req.headers['roblox-hwid'] || req.query.hwid || req.headers['fingerprint'];
  if (clientHWID) {
    if (kd.activations && kd.activations.length > 0 && kd.activations[0].hwid) {
      const boundHWID = kd.activations[0].hwid;
      if (boundHWID !== clientHWID) {
        await addLog('invalid_key', { key, ip: getRealIP(req), hwid: clientHWID, reason: 'HWID mismatch (Error 267)' });
        return res.send(`game:GetService("Players").LocalPlayer:Kick("Security Error 267: HWID Mismatch! Key bound to another device. Use HWID reset in Discord.") error("HWID Mismatch")`);
      }
    } else {

      kd.activations = [{ hwid: clientHWID, firstSeen: new Date(), lastSeen: new Date(), ip: getRealIP(req) }];
      await kd.save();
      console.log(`[HWID Lock] Bound key ${key} to HWID: ${clientHWID}`);
    }
  }

  const user = await User.findOne({ licenseKey: key });
  if (!user) return res.send('-- ERROR: No account linked to this key.');

  const activeName = kd.activeConfig || 'default';
  let rawLua = '';

  if (kd.activeConfig === '__live__' && kd.liveConfigContent) {
    rawLua = String(kd.liveConfigContent);
  } else {
    const cfg = await Config.findOne({
      name: activeName,
      $or: [
        { ownerKey: key },
        { owner: user.username, ownerKey: { $in: ['', null, undefined] } }
      ]
    });
    if (cfg) {
      if (!cfg.ownerKey) { cfg.ownerKey = key; cfg.save().catch(() => { }); }
      rawLua = cfg.content || '';
    } else if (kd.liveConfigContent) {
      rawLua = String(kd.liveConfigContent);
    } else if (!kd.activeConfig || activeName.toLowerCase() === 'default') {
      const fallbackDefault = await Config.findOne({
        name: 'default',
        $or: [
          { ownerKey: key },
          { owner: user.username, ownerKey: { $in: ['', null, undefined] } }
        ]
      });
      rawLua = fallbackDefault ? (fallbackDefault.content || '') : getDefaultServerCloverLua();
    } else {
      return res.send('-- ERROR: Config "' + activeName + '" not found for this key.');
    }
  }

  const upgradedContent = upgradeServerCloverConfigLua(rawLua);
  if (req.query.enc === '1' && req.query.nonce) {
    const cfgHash = crypto.createHash('sha256').update(`${activeName}\n${String(upgradedContent)}`).digest('hex').slice(0, 16);
    res.setHeader('Content-Type', 'application/json');
    if (req.query.hash && req.query.hash === cfgHash) {
      return res.json({ unchanged: true, hash: cfgHash });
    }
    const nonce = String(req.query.nonce).slice(0, 64);
    const streamKey = Buffer.from(`${nonce}:${key}:${clientHWID || ''}`, 'utf8');
    const encBuf = rc4Transform(Buffer.from(upgradedContent, 'utf8'), streamKey);
    return res.json({ payload: encBuf.toString('base64'), nonce, hash: cfgHash });
  }
  return res.send(upgradedContent);
});

app.get('/cloudconfig', async (req, res) => {
  try {
    await loadDefaultCloverTableFromDb();
    const key = req.query.key;
    if (!key) return res.status(400).json({ success: false, error: 'Key required' });

    const kd = await Key.findById(key);
    if (!kd || kd.status !== 'active' || isExpired(kd) || kd.blacklisted) return res.status(403).json({ success: false, error: 'Key invalid or blacklisted' });

    const user = await User.findOne({ licenseKey: key });
    if (!user) return res.status(404).json({ success: false, error: 'User not found' });

    const activeName = kd.activeConfig || 'default';
    if (kd.activeConfig === '__live__' && kd.liveConfigContent) {
      return res.json({ success: true, config: upgradeServerCloverConfigLua(String(kd.liveConfigContent)), name: 'default' });
    }

    const cfg = await Config.findOne({
      name: activeName,
      $or: [
        { ownerKey: key },
        { owner: user.username, ownerKey: { $in: ['', null, undefined] } }
      ]
    });
    if (cfg) {

      if (!cfg.ownerKey) { cfg.ownerKey = key; await cfg.save(); }
      return res.json({ success: true, config: upgradeServerCloverConfigLua(cfg.content), name: activeName });
    }

    if (kd.liveConfigContent) {
      return res.json({ success: true, config: upgradeServerCloverConfigLua(String(kd.liveConfigContent)), name: 'default' });
    }
    if (!kd.activeConfig || activeName.toLowerCase() === 'default') {
      return res.json({ success: true, config: getDefaultServerCloverLua(), name: 'default' });
    }

    res.status(404).json({ success: false, error: 'Config not found for this key' });
  } catch (e) {
    res.status(500).json({ success: false, error: 'Server error' });
  }
});

app.post('/cloudconfig/save', async (req, res) => {
  try {
    const { key, config, configName } = req.body;
    if (!key || config === undefined) return res.status(400).json({ success: false, error: 'Key and config required' });

    const kd = await Key.findById(key);
    if (!kd || kd.status !== 'active' || isExpired(kd) || kd.blacklisted) return res.status(403).json({ success: false, error: 'Key invalid or blacklisted' });

    const user = await User.findOne({ licenseKey: key });
    if (!user) return res.status(404).json({ success: false, error: 'User not found' });


    let targetName = configName || kd.activeConfig || 'Default';

    const target = await Config.findOne({
      name: targetName,
      $or: [{ ownerKey: key }, { owner: user.username, ownerKey: { $in: ['', null] } }]
    });

    if (target) {
      target.content = config;
      target.ownerKey = key;
      target.owner = user.username;
      await target.save();
    } else {
      await Config.create({
        name: targetName,
        content: config,
        owner: user.username,
        ownerKey: key,
        createdAt: new Date()
      });
    }


    await Key.findByIdAndUpdate(key, { activeConfig: targetName });


    const updateTime = Date.now();
    keyConfigUpdates.set(key, updateTime);
    broadcastToKey(key, { type: 'settings_updated', timestamp: updateTime, key: key });

    res.json({ success: true, name: targetName });
  } catch (e) {
    res.status(500).json({ success: false, error: 'Save failed' });
  }
});

