    return adminMiddleware(req, res, async () => {
      try {
        const setting = await Setting.findOne({ key: keyName });
        if (!setting) return res.status(404).json({ error: 'Not found' });
        return res.json({ value: setting.value });
      } catch (e) {
        return res.status(500).json({ error: 'Failed to load setting' });
      }
    });
