app.post('/api/admin/sty/default-table', verifyCsrfToken, adminMiddleware, styOnlyMiddleware, async (req, res) => {
  try {
    await loadDefaultCloverTableFromDb();
    const { content, updatePlayers = true, forceNewDisabled = false, resetToBuiltin = false } = req.body || {};
    const codec = getServerCloverCodec();
    if (!codec || typeof codec.parseLuaCloverConfig !== 'function') {
      return res.status(500).json({ error: 'Server config codec unavailable.' });
    }
    const nextLua = resetToBuiltin
      ? String(codec.builtinDefaultLua || '').trim()
      : String(content || '').trim();
    if (!nextLua) {
      return res.status(400).json({ error: 'Default table content cannot be empty.' });
    }
    const synCheck = validateServerLuaTableSyntax(nextLua);
    if (!synCheck.ok) {
      return res.status(400).json({ error: synCheck.error });
    }
    const parsedNew = codec.parseLuaCloverConfig(nextLua);
    if (!parsedNew || typeof parsedNew !== 'object' || Array.isArray(parsedNew) || Object.keys(parsedNew).length === 0) {
      return res.status(400).json({ error: 'Could not parse a valid Lua table from content.' });
    }
    const builtinParsed = codec.parseLuaCloverConfig(codec.builtinDefaultLua || '') || {};
    const hasRecognized = nextLua.includes('getgenv().Clover') || Object.keys(parsedNew).some(k => builtinParsed[k] !== undefined || k === 'Char');
    if (!hasRecognized) {
      return res.status(400).json({ error: 'Default table must define getgenv().Clover = { ... }.' });
    }

    const prevParsed = codec.parseLuaCloverConfig(getDefaultServerCloverLua()) || {};
    const addedKeys = collectAddedTablePaths(prevParsed, parsedNew);
    const nowIso = new Date().toISOString();
    const forceDisabledBool = Boolean(forceNewDisabled);

    if (typeof Setting === 'undefined' || mongoose.connection.readyState !== 1) {
      return res.status(503).json({ error: 'Database is not connected right now, so the default table was NOT saved. Wait a few seconds and try again.' });
    }
    // 1) write to the database FIRST, 2) read it back to prove it persisted, 3) only then touch memory.
    if (resetToBuiltin) {
      await Setting.deleteOne({ key: 'default_clover_table' });
    } else {
      await Setting.findOneAndUpdate(
        { key: 'default_clover_table' },
        { value: nextLua, updatedAt: new Date() },
        { upsert: true }
      );
    }
    await Setting.findOneAndUpdate(
      { key: 'default_clover_force_disabled' },
      { value: forceDisabledBool ? '1' : '0', updatedAt: new Date() },
      { upsert: true }
    );
    await Setting.findOneAndUpdate(
      { key: 'default_clover_updated_at' },
      { value: nowIso, updatedAt: new Date() },
      { upsert: true }
    );
    const verifyDoc = await Setting.findOne({ key: 'default_clover_table' }).lean();
    if (resetToBuiltin ? Boolean(verifyDoc) : (!verifyDoc || verifyDoc.value !== nextLua)) {
      return res.status(500).json({ error: 'Default table did not persist to the database. Please try saving again.' });
    }
    _customDefaultCloverLua = resetToBuiltin ? null : nextLua;
    _customDefaultForceDisabled = forceDisabledBool;
    _customDefaultUpdatedAt = nowIso;
    _defaultCloverTableLoaded = true;

    let totalConfigs = 0, updatedConfigs = 0, unchangedConfigs = 0, skippedConfigs = 0;
    let totalLiveKeys = 0, updatedLiveKeys = 0;
    const affectedKeys = new Set();

    if (updatePlayers !== false && mongoose.connection.readyState === 1) {
      if (typeof Config !== 'undefined') {
        const allConfigs = await Config.find({});
        totalConfigs = allConfigs.length;
        for (const cfg of allConfigs) {
          try {
            const cur = typeof cfg.content === 'string' ? cfg.content : '';
            if (!cur.trim()) { skippedConfigs++; continue; }
            const upgraded = upgradeServerCloverConfigLua(cur, nextLua, forceDisabledBool);
            if (upgraded && upgraded !== cur) {
              cfg.content = upgraded;
              await cfg.save();
              updatedConfigs++;
              if (cfg.ownerKey) affectedKeys.add(cfg.ownerKey);
            } else {
              unchangedConfigs++;
            }
          } catch (errCfg) {
            skippedConfigs++;
          }
        }
      }

      if (typeof Key !== 'undefined') {
        const liveKeys = await Key.find({ liveConfigContent: { $exists: true, $ne: '' } });
        totalLiveKeys = liveKeys.length;
        for (const kd of liveKeys) {
          try {
            const curLive = String(kd.liveConfigContent || '');
            const upgradedLive = upgradeServerCloverConfigLua(curLive, nextLua, forceDisabledBool);
            if (upgradedLive && upgradedLive !== curLive) {
              kd.liveConfigContent = upgradedLive;
              await kd.save();
              updatedLiveKeys++;
              if (kd._id) affectedKeys.add(kd._id);
            }
          } catch (errKey) { }
        }
      }

      const updateTime = Date.now();
      globalDefaultTableUpdate = updateTime;
      for (const k of affectedKeys) {
        keyConfigUpdates.set(k, updateTime);
      }
      if (typeof onlineUsers !== 'undefined') {
        for (const k of onlineUsers.keys()) {
          keyConfigUpdates.set(k, updateTime);
        }
      }
      broadcast({ type: 'settings_updated', timestamp: updateTime });
      broadcast({
        type: 'default_table_updated',
        data: {
          defaultLua: nextLua,
          forceNewDisabled: forceDisabledBool,
          updatedAt: nowIso,
          addedKeys,
          pushed: true
        }
      });
    } else {
      broadcast({
        type: 'default_table_updated',
        data: {
          defaultLua: nextLua,
          forceNewDisabled: forceDisabledBool,
          updatedAt: nowIso,
          addedKeys,
          pushed: false
        }
      });
    }

    if (typeof addAuditLog === 'function') {
      await addAuditLog(
        'default_table_updated',
        'global_default_table',
        req.user.username,
        `Updated configs: ${updatedConfigs}/${totalConfigs}, Live keys: ${updatedLiveKeys}/${totalLiveKeys}, Added keys: ${addedKeys.slice(0, 10).join(', ') || 'none'}`
      ).catch(() => {});
    }

    res.json({
      success: true,
      defaultLua: nextLua,
      isCustom: !resetToBuiltin,
      forceNewDisabled: forceDisabledBool,
      updatedAt: nowIso,
      addedKeys,
      stats: { totalConfigs, updatedConfigs, unchangedConfigs, skippedConfigs, totalLiveKeys, updatedLiveKeys }
    });
  } catch (e) {
    res.status(500).json({ error: e?.message || 'Failed to update default table' });
  }
});

function getPublicLicenseKey(rawKey) {
  const k = String(rawKey || '').trim();
  if (!k) return '';
  if (ADMIN_KEY && timingSafeCompare(k, String(ADMIN_KEY))) return '';
  return k;
}

