app.get('/api/auth/saved-accounts', authMiddleware, async (req, res) => {
  try {
    const vaultId = getOrCreateVaultId(req, res);
    const list = await getVaultAccounts(vaultId);
    const accounts = [];
    for (const acc of list) {
      if (!acc || !acc.username) continue;
      let hasActiveSession = false;
      if (acc.sessionToken) {
        if (activeSessions.has(acc.sessionToken)) {
          hasActiveSession = true;
        } else if (typeof Session !== 'undefined' && mongoose.connection.readyState === 1) {
          const sDoc = await Session.findOne({ token: acc.sessionToken }).select('_id').lean().catch(() => null);
          if (sDoc) hasActiveSession = true;
        }
      }
      accounts.push({
        username: acc.username,
        role: acc.role || 'customer',
        avatar: acc.avatar || '',
        hasActiveSession,
        updatedAt: Number(acc.updatedAt) || Date.now()
      });
    }
    res.json({ success: true, accounts });
  } catch (e) {
    res.status(500).json({ success: false, error: 'Failed to load saved accounts' });
  }
});

