app.post('/api/auth/switch-session', switchSessionLimiter, async (req, res) => {
  try {
    const targetUsername = typeof req.body?.username === 'string' ? req.body.username.trim() : '';
    if (!targetUsername) {
      return res.status(400).json({ success: false, error: 'Missing account username', expired: true });
    }
    const vaultId = req.cookies?.clover_vault || '';
    const vaultList = await getVaultAccounts(vaultId);
    const entry = vaultList.find(a => a && a.username && a.username.toLowerCase() === targetUsername.toLowerCase());
    const token = entry && entry.sessionToken ? String(entry.sessionToken).trim() : '';
    if (!token) {
      return res.status(401).json({ success: false, error: 'Saved session expired. Enter password to sign back in.', expired: true });
    }
    let session = activeSessions.get(token);
    if (!session) {
      const dbSess = await Session.findOne({ token });
      if (dbSess) session = buildActiveSessionRecord(dbSess);
    }
    if (!session || !session.username) {
      return res.status(401).json({ success: false, error: 'Saved session expired. Enter password to sign back in.', expired: true });
    }
    const switchBindRes = verifySessionBinding(req, session);
    if (!switchBindRes.ok) {
      await reportSessionHijackBlocked(req, session, switchBindRes.reason);
      return res.status(401).json({ success: false, error: 'Session locked to original browser and device.', expired: true });
    }
    if (session.username === 'Admin' && ADMIN_KEY && session.key === ADMIN_KEY) {
      activeSessions.set(token, buildActiveSessionRecord(session, { token, username: 'Admin', role: 'admin', key: ADMIN_KEY, rememberMe: true }));
      setSecureSessionCookie(res, token, true);
      return res.json({ success: true, username: 'Admin', role: 'admin', hasKey: false, avatar: '' });
    }
    const user = await User.findOne({ username: session.username });
    if (!user || user.blacklisted) {
      activeSessions.delete(token);
      await Session.deleteOne({ token }).catch(() => {});
      return res.status(401).json({ success: false, error: 'Account session is no longer valid.', expired: true });
    }
    if (user.licenseKey) {
      const keyDoc = await Key.findById(user.licenseKey);
      if (keyDoc && keyDoc.blacklisted) {
        activeSessions.delete(token);
        await Session.deleteOne({ token }).catch(() => {});
        return res.status(403).json({ success: false, error: 'Access denied' });
      }
    }
    activeSessions.set(token, buildActiveSessionRecord(session, { token, username: user.username, role: user.role, key: user.licenseKey || '', rememberMe: true }));
    setSecureSessionCookie(res, token, true);
    await saveSessionToVault(req, res, { username: user.username, role: user.role, avatar: user.discordAvatar || '', sessionToken: token });
    res.json({
      success: true,
      username: user.username,
      role: user.role,
      hasKey: Boolean(user.licenseKey),
      avatar: user.discordAvatar || ''
    });
  } catch (e) { res.status(500).json({ success: false, error: 'Failed to switch session' }); }
});

