app.post('/api/bot/keys/issue', botLimiter, async (req, res) => {
  if (!BOT_API_KEY || BOT_API_KEY.length < 8 || !timingSafeCompare(String(req.headers['x-bot-key'] || ''), BOT_API_KEY)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  const durationDaysRaw = req.body && req.body.durationDays !== undefined ? Number(req.body.durationDays) : 30;
  const durationDays = Number.isFinite(durationDaysRaw) && durationDaysRaw >= 0 ? Math.min(durationDaysRaw, 3650) : 30;
  const maxUsesRaw = req.body && req.body.maxUses !== undefined ? Number(req.body.maxUses) : 1;
  const maxUses = Number.isFinite(maxUsesRaw) && maxUsesRaw >= 1 ? Math.min(Math.floor(maxUsesRaw), 100) : 1;
  const prefix = typeof req.body?.prefix === 'string' && req.body.prefix.trim() ? req.body.prefix.trim().slice(0, 12) : 'CLOVER';
  const label = typeof req.body?.label === 'string' && req.body.label.trim() ? req.body.label.trim().slice(0, 60) : 'bot-dm';

  const newKey = generateKey(prefix);
  const keyExpires = durationDays === 0 ? null : new Date(Date.now() + durationDays * 86400000);
  await Key.create({
    _id: newKey,
    hwidResetCount: 0,
    ipHistory: [],
    activations: [],
    sessions: new Map(),
    expires: keyExpires,
    uses: 0,
    maxUses,
    status: 'active',
    label,
    createdAt: new Date(),
    requiresRedemption: false,
    redeemed: true,
    durationDays
  });
  await updateAnalytics('new_key', null);
  await addAuditLog('bot_key_issued', newKey, 'discord-bot', `Prefix: ${prefix}, Duration: ${durationDays}d, Label: ${label}`);
  return res.json({ success: true, key: newKey, durationDays, expires: keyExpires });
});

app.post('/api/bot/keys/bulk', botLimiter, async (req, res) => {
  if (!BOT_API_KEY || BOT_API_KEY.length < 8 || !timingSafeCompare(String(req.headers['x-bot-key'] || ''), BOT_API_KEY)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  const { count = 1, durationDays = 30, maxUses = 1, label = 'bot', prefix = 'CLOVER' } = req.body;
  const out = [];
  console.log(`[Bulk Key Generation] Creating ${count} keys with durationDays: ${durationDays}`);
  for (let i = 0; i < Math.min(count, 100); i++) {
    const newKey = generateKey(prefix);

    let keyExpires = null;
    if (durationDays !== 0) {
      keyExpires = new Date(Date.now() + durationDays * 86400000);
    }
    const keyData = {
      _id: newKey, hwidResetCount: 0, ipHistory: [], activations: [],
      sessions: new Map(), expires: keyExpires,
      uses: 0, maxUses, status: 'pending_redemption', label, createdAt: new Date(),
      requiresRedemption: true, redeemed: false, durationDays
    };
    console.log(`[Bulk Key Generation] Creating key ${newKey} with durationDays: ${durationDays}, expires: ${keyExpires}`);
    await Key.create(keyData);
    out.push(newKey);
  }
  await updateAnalytics('new_key', null);
  await addAuditLog('bulk_keys_created', `${out.length} keys`, 'discord-bot', `Prefix: ${prefix}, Duration: ${durationDays}d, pending redemption`);
  res.json({ keys: out });
});

app.post('/api/bot/keys/redeem', botLimiter, async (req, res) => {
  if (!BOT_API_KEY || BOT_API_KEY.length < 8 || !timingSafeCompare(String(req.headers['x-bot-key'] || ''), BOT_API_KEY)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  const { key, discordUserId, discordUsername } = req.body || {};
  if (!key) return res.status(400).json({ error: 'Key required' });

  const kd = await Key.findById(key);
  if (!kd) return res.status(404).json({ error: 'Key not found' });

  if (!kd.requiresRedemption) {
    return res.json({ ok: true, notRequired: true });
  }
  if (kd.redeemed) {
    return res.json({ ok: true, alreadyRedeemed: true, redeemedAt: kd.redeemedAt, redeemedBy: kd.redeemedBy });
  }

  kd.redeemed = true;
  kd.redeemedAt = new Date();
  kd.redeemedBy = { discordId: String(discordUserId || ''), discordUsername: discordUsername || '' };
  kd.status = 'active';


  const daysToSet = (kd.durationDays && kd.durationDays > 0) ? kd.durationDays : 7;
  if (!kd.expires || kd.durationDays === 0) {
    kd.durationDays = daysToSet;
    const newExpiry = new Date(Date.now() + daysToSet * 24 * 60 * 60 * 1000);
    kd.expires = newExpiry;
    console.log(`[Key Redemption] Set ${daysToSet}-day expiration for key ${key}: ${newExpiry.toISOString()}`);
  } else {
    console.log(`[Key Redemption] Key ${key} - durationDays: ${kd.durationDays}, expires: ${kd.expires?.toISOString()}`);
  }

  await kd.save();

  await addLog('key_redeemed', {
    key, discordId: String(discordUserId || ''), discordUsername: discordUsername || '',
    reason: 'Redeemed via Discord bot', success: true
  });
  await addAuditLog('key_redeemed', key, `discord:${discordUsername || discordUserId}`, `Discord ID: ${discordUserId}, redeemed at ${kd.redeemedAt.toISOString()}`);

  res.json({ ok: true, redeemedAt: kd.redeemedAt });
});

app.post('/api/bot/keys/hwid-reset', botLimiter, async (req, res) => {
  if (!BOT_API_KEY || BOT_API_KEY.length < 8 || !timingSafeCompare(String(req.headers['x-bot-key'] || ''), BOT_API_KEY)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  const { key, discordUserId } = req.body || {};
  if (!key) return res.status(400).json({ error: 'Key required' });

  const kd = await Key.findById(key);
  if (!kd) return res.status(404).json({ error: 'Key not found' });

  if (kd.requiresRedemption && !kd.redeemed) {
    return res.status(400).json({ error: 'This key must be redeemed before its HWID can be reset.' });
  }




  const linkedUser = await User.findOne({ licenseKey: key });
  const owningDiscordId = linkedUser?.discordId || kd.redeemedBy?.discordId || '';
  if (owningDiscordId && String(discordUserId) !== String(owningDiscordId)) {
    return res.status(403).json({ error: 'This key is not linked to your Discord account.' });
  }

  kd.activations = [];
  kd.sessions = new Map();
  kd.hwidResetCount = (kd.hwidResetCount || 0) + 1;
  await kd.save();

  await addLog('hwid_reset', { key, discordId: String(discordUserId || ''), reason: 'Reset via Discord bot' });
  await addAuditLog('hwid_reset', key, `discord:${discordUserId}`, 'Reset via Discord bot button');

  res.json({ ok: true, hwidResetCount: kd.hwidResetCount });
});

app.post('/api/bot/keys/blacklist', botLimiter, async (req, res) => {
  try {
    if (!BOT_API_KEY || BOT_API_KEY.length < 8 || !timingSafeCompare(String(req.headers['x-bot-key'] || ''), BOT_API_KEY)) {
      return res.status(401).json({ error: 'Unauthorized' });
    }
    const { key, discordUserId, websiteUsername, reason, forceLogout } = req.body || {};
    if (!key && !discordUserId && !websiteUsername) {
      return res.status(400).json({ error: 'Key, discordUserId, or websiteUsername required' });
    }

    const banReason = reason || 'Blacklisted via Discord bot';
    let keyFound = false;
    let userFound = false;


    if (key) {
      let kd = await Key.findById(key);
      if (!kd) {

        kd = new Key({
          _id: key,
          status: 'blacklisted',
          blacklisted: true,
          requiresRedemption: true,
          redeemed: false
        });
      } else {
        kd.blacklisted = true;
        kd.status = 'blacklisted';
      }
      await kd.save();
      keyFound = true;
    }


    let user = null;
    if (key && typeof key === 'string') user = await User.findOne({ licenseKey: key });
    if (!user && websiteUsername && typeof websiteUsername === 'string') user = await User.findOne({ username: { $regex: new RegExp(`^${escapeRegex(websiteUsername)}$`, 'i') } });
    if (!user && discordUserId) user = await User.findOne({ discordId: String(discordUserId) });

    if (user) {
      user.blacklisted = true;
      user.blacklistedAt = new Date();
      user.blacklistReason = banReason;
      await user.save();
      userFound = true;


      await Blacklist.create({
        type: 'username',
        value: user.username.toLowerCase(),
        reason: banReason,
        admin: 'discord-bot'
      }).catch(() => { });
    }


    if (discordUserId) {
      await Blacklist.create({
        type: 'username',
        value: `discord_${discordUserId}`,
        reason: banReason,
        admin: 'discord-bot'
      }).catch(() => { });
    }


    const targetUsername = user ? user.username : null;
    for (const [token, sess] of activeSessions.entries()) {
      if ((targetUsername && sess.username === targetUsername) || (key && sess.key === key)) {
        activeSessions.delete(token);
        await Session.deleteOne({ token }).catch(() => { });
      }
    }

    if (key) onlineUsers.delete(key);


    const logoutPayload = JSON.stringify({
      type: 'blacklisted',
      reason: banReason,
      logout: true,
      error: `Your account has been permanently blacklisted: ${banReason}`
    });

    wsClients.forEach(client => {
      if (client.readyState === WebSocket.OPEN) {
        if ((key && client.licenseKey === key) || (targetUsername && client.username === targetUsername)) {
          try { client.send(logoutPayload); } catch (_) { }
          try { client.close(4003, 'Blacklisted'); } catch (_) { }
        }
      }
    });

    await addLog('key_blacklisted', { key: key || 'N/A', username: targetUsername || 'N/A', reason: banReason });
    await addAuditLog('key_blacklisted', key || targetUsername || 'N/A', 'discord-bot', `Reason: ${banReason}`);

    res.json({
      ok: true,
      message: 'Blacklisted successfully',
      keyBlacklisted: keyFound,
      userBlacklisted: userFound,
      liveLogoutExecuted: true
    });
  } catch (error) {
    console.error('Blacklist error:', error);
    res.status(500).json({ error: 'Internal server error', details: error.message });
  }
});

