app.post('/api/admin/blacklist', adminMiddleware, async (req, res) => {
  const { type, value, reason = '' } = req.body;
  if (!type || !value || typeof value !== 'string' || !['ip', 'country', 'username'].includes(type)) return res.status(400).json({ error: 'Invalid type or missing value' });
  const cleanVal = value.trim();
  const lookupFilter = type === 'username'
    ? { type: 'username', value: { $regex: '^' + escapeRegex(cleanVal) + '$', $options: 'i' } }
    : { type, value: cleanVal };
  const existing = await Blacklist.findOne(lookupFilter);
  if (existing) return res.status(400).json({ error: 'Already blacklisted' });
  const storedVal = type === 'username' ? cleanVal.toLowerCase() : cleanVal;
  const item = await Blacklist.create({ type, value: storedVal, reason: String(reason || '').slice(0, 200), admin: req.user.username });
  if (type === 'ip') blacklistedIpCache.set.add(normalizeIp(cleanVal));
  if (type === 'username') {
    const lowerUser = cleanVal.toLowerCase();
    blacklistedUsernameCache.set.add(lowerUser);
    if (typeof User !== 'undefined') {
      await User.updateOne(
        { username: { $regex: '^' + escapeRegex(cleanVal) + '$', $options: 'i' } },
        { $set: { blacklisted: true, blacklistedAt: new Date(), blacklistReason: String(reason || '').slice(0, 200) } }
      ).catch(() => {});
    }
    for (const [tok, sess] of activeSessions.entries()) {
      if (sess && String(sess.username || '').trim().toLowerCase() === lowerUser) {
        activeSessions.delete(tok);
      }
    }
    if (typeof Session !== 'undefined') {
      await Session.deleteMany({ username: { $regex: '^' + escapeRegex(cleanVal) + '$', $options: 'i' } }).catch(() => {});
    }
  }
  await addAuditLog('blacklist_add', cleanVal, req.user.username, `Type: ${type}, Reason: ${reason}`);
  res.json({ success: true, item });
});

app.delete('/api/admin/blacklist/:id', adminMiddleware, async (req, res) => {
  const item = await Blacklist.findByIdAndDelete(req.params.id);
  if (!item) return res.status(404).json({ error: 'Not found' });
  if (item.type === 'ip') blacklistedIpCache.set.delete(normalizeIp(item.value));
  if (item.type === 'username' && item.value) {
    const lowerUser = String(item.value).trim().toLowerCase();
    blacklistedUsernameCache.set.delete(lowerUser);
    if (typeof User !== 'undefined') {
      await User.updateOne(
        { username: { $regex: '^' + escapeRegex(item.value) + '$', $options: 'i' } },
        { $set: { blacklisted: false } }
      ).catch(() => {});
    }
  }
  await addAuditLog('blacklist_remove', item.value, req.user.username, `Type: ${item.type}`);
  res.json({ success: true });
});

