const styDemoteStrikes = new Map();

async function enforceStyDemoteProtection(req, res, targetUser, desiredRole) {
  const nextRole = desiredRole || (targetUser.role === 'admin' ? 'customer' : 'admin');
  const isTargetSty = String(targetUser.username || '').trim().toLowerCase() === 'sty';
  const isDemotingSty = isTargetSty && nextRole !== 'admin' && nextRole !== 'owner';
  if (!isDemotingSty) return false;

  const actorName = String(req.user?.username || '').trim();
  const actorKey = actorName.toLowerCase();
  if (actorKey === 'sty') {
    res.status(403).json({ success: false, protected: true, error: 'Protected admin account cannot be demoted.' });
    return true;
  }

  const actorDoc = await User.findOne({ username: actorName });
  const prevStrikes = Math.max(
    styDemoteStrikes.get(actorKey) || 0,
    (actorDoc && Number(actorDoc.styDemoteWarnings)) || 0
  );
  const strikes = prevStrikes + 1;
  styDemoteStrikes.set(actorKey, strikes);

  if (strikes === 1) {
    if (actorDoc) {
      actorDoc.styDemoteWarnings = 1;
      await actorDoc.save();
    }
    if (typeof addAuditLog === 'function') {
      await addAuditLog('sty_demote_warning', targetUser.username, actorName, 'Attempt 1 blocked; warned actor');
    }
    res.status(403).json({
      success: false,
      warning: true,
      revoked: false,
      error: 'try demoting one more time your admin will be revoked.'
    });
    return true;
  }

  if (actorDoc) {
    actorDoc.role = 'customer';
    actorDoc.styDemoteWarnings = strikes;
    await actorDoc.save();
  }
  for (const [token, session] of activeSessions.entries()) {
    if (String(session.username || '').trim().toLowerCase() === actorKey) {
      session.role = 'customer';
      activeSessions.set(token, session);
    }
  }
  if (typeof Session !== 'undefined') {
    await Session.updateMany({ username: actorName }, { $set: { role: 'customer' } }).catch(() => {});
  }
  if (typeof addAuditLog === 'function') {
    await addAuditLog('admin_revoked', actorName, actorName, 'Admin revoked for repeated attempt to demote sty');
  }
  if (typeof broadcastToUser === 'function') {
    broadcastToUser(actorName, { type: 'role_changed', data: { username: actorName, role: 'customer', revoked: true } });
  }
  res.status(403).json({
    success: false,
    warning: false,
    revoked: true,
    role: 'customer',
    error: 'Your admin role has been revoked.'
  });
  return true;
}

app.post('/api/admin/users/role', adminMiddleware, async (req, res) => {
  try {
    const { username, role } = req.body;
    if (!username || typeof username !== 'string') return res.status(400).json({ error: 'Username is required' });
    if (role && !['admin', 'customer', 'owner'].includes(role)) return res.status(400).json({ error: 'Invalid role' });
    const user = await User.findOne({ username: username.trim() });
    if (!user) return res.status(404).json({ error: 'User not found' });
    if (await enforceStyDemoteProtection(req, res, user, role)) return;
    const oldRole = user.role;
    user.role = role || (user.role === 'admin' ? 'customer' : 'admin');
    await user.save();
    for (const [token, session] of activeSessions.entries()) {
      if (session.username === user.username) {
        session.role = user.role;
        activeSessions.set(token, session);
      }
    }
    if (typeof Session !== 'undefined') {
      await Session.updateMany({ username: user.username }, { $set: { role: user.role } }).catch(() => {});
    }
    if (typeof addAuditLog === 'function') {
      await addAuditLog('user_role_change', user.username, req.user.username, `${oldRole} -> ${user.role}`);
    }
    if (typeof broadcastToUser === 'function') {
      broadcastToUser(user.username, { type: 'role_changed', data: { username: user.username, role: user.role } });
    }
    res.json({ success: true, role: user.role });
  } catch (e) {
    res.status(500).json({ error: 'Failed to update user role' });
  }
});

