app.post('/api/admin/users/:username/reassign-key', adminMiddleware, async (req, res) => {
  try {
    const rawNewKey = req.body && req.body.newKey;
    if (!rawNewKey || typeof rawNewKey !== 'string' || rawNewKey.trim().length < 4) {
      return res.status(400).json({ error: 'Valid new license key (at least 4 characters) is required' });
    }
    const cleanKey = rawNewKey.trim();
    const user = await User.findOne({ username: req.params.username });
    if (!user) return res.status(404).json({ error: 'User not found' });

    const oldKey = user.licenseKey ? String(user.licenseKey).trim() : '';
    if (oldKey === cleanKey) {
      return res.json({ success: true, key: cleanKey, deletedOldKey: '' });
    }

    const conflictingUser = await User.findOne({ licenseKey: cleanKey, username: { $ne: user.username } });
    if (conflictingUser) {
      return res.status(409).json({ error: 'That key is already assigned to another user (' + conflictingUser.username + ')' });
    }

    const oldKeyDoc = oldKey ? await Key.findById(oldKey).catch(() => null) : null;
    const existingNewKeyDoc = await Key.findById(cleanKey).catch(() => null);

    if (existingNewKeyDoc) {
      if (existingNewKeyDoc.status === 'pending_redemption' || !existingNewKeyDoc.status) {
        existingNewKeyDoc.status = 'active';
      }
      if (!existingNewKeyDoc.activeConfig && oldKeyDoc && oldKeyDoc.activeConfig) {
        existingNewKeyDoc.activeConfig = oldKeyDoc.activeConfig;
      }
      if (!existingNewKeyDoc.liveConfigContent && oldKeyDoc && oldKeyDoc.liveConfigContent) {
        existingNewKeyDoc.liveConfigContent = oldKeyDoc.liveConfigContent;
      }
      existingNewKeyDoc.redeemed = true;
      existingNewKeyDoc.redeemedAt = existingNewKeyDoc.redeemedAt || new Date();
      await existingNewKeyDoc.save();
    } else {
      await Key.create({
        _id: cleanKey,
        status: 'active',
        expires: oldKeyDoc ? oldKeyDoc.expires : null,
        maxUses: oldKeyDoc && oldKeyDoc.maxUses ? oldKeyDoc.maxUses : 1,
        uses: oldKeyDoc ? (oldKeyDoc.uses || 0) : 0,
        label: oldKeyDoc ? (oldKeyDoc.label || '') : '',
        note: oldKeyDoc ? (oldKeyDoc.note || '') : 'Assigned via Admin Change Key',
        activeConfig: oldKeyDoc ? (oldKeyDoc.activeConfig || '') : '',
        liveConfigContent: oldKeyDoc ? (oldKeyDoc.liveConfigContent || '') : '',
        totalExecutions: oldKeyDoc ? (oldKeyDoc.totalExecutions || 0) : 0,
        activations: oldKeyDoc && Array.isArray(oldKeyDoc.activations) ? oldKeyDoc.activations : [],
        hwidResetCount: oldKeyDoc ? (oldKeyDoc.hwidResetCount || 0) : 0,
        createdAt: new Date()
      });
    }

    if (oldKey && oldKey !== cleanKey) {
      await Key.deleteOne({ _id: oldKey }).catch(() => { });
      await Config.updateMany({ ownerKey: oldKey }, { $set: { ownerKey: cleanKey } }).catch(() => { });
      await MarketplaceConfig.updateMany({ authorKey: oldKey }, { $set: { authorKey: cleanKey } }).catch(() => { });
    }
    await Config.updateMany(
      { owner: user.username, ownerKey: { $in: ['', null, oldKey] } },
      { $set: { ownerKey: cleanKey } }
    ).catch(() => { });

    user.licenseKey = cleanKey;
    await user.save();

    await Session.updateMany({ username: user.username }, { $set: { key: cleanKey } }).catch(() => { });

    for (const [token, session] of activeSessions.entries()) {
      if (session.username === user.username || (oldKey && session.key === oldKey)) {
        session.key = cleanKey;
        activeSessions.set(token, session);
      }
    }

    if (oldKey && typeof onlineUsers !== 'undefined' && onlineUsers.has(oldKey)) {
      const onlineData = onlineUsers.get(oldKey);
      onlineUsers.delete(oldKey);
      onlineUsers.set(cleanKey, onlineData);
    }
    if (oldKey && typeof keyConfigUpdates !== 'undefined' && keyConfigUpdates.has(oldKey)) {
      const ts = keyConfigUpdates.get(oldKey);
      keyConfigUpdates.delete(oldKey);
      keyConfigUpdates.set(cleanKey, ts);
    }
    if (typeof wsClients !== 'undefined') {
      wsClients.forEach((c) => {
        if ((oldKey && c.licenseKey === oldKey) || (c.username && c.username === user.username)) {
          c.licenseKey = cleanKey;
        }
      });
    }

    if (typeof addAuditLog === 'function') {
      await addAuditLog('user_key_reassign', user.username, req.user.username, `${oldKey || 'none'} -> ${cleanKey} (old key deleted)`);
    }

    if (typeof broadcastToKey === 'function') {
      broadcastToKey(cleanKey, { type: 'key_changed', username: user.username });
    }
    if (typeof broadcastToAdmins === 'function') {
      broadcastToAdmins({ type: 'keys_updated' });
    }

    res.json({ success: true, key: cleanKey, deletedOldKey: oldKey });
  } catch (e) {
    res.status(500).json({ error: e.message || 'Failed to reassign key' });
  }
});

