app.get('/api/discord/link', authMiddleware, async (req, res) => {
  if (!DISCORD_CLIENT_ID || !DISCORD_CLIENT_SECRET) return res.status(500).json({ error: 'Discord OAuth not configured' });


  const user = await User.findOne({ username: req.user.username });
  if (user && user.discordLinkedIP && user.discordId) {
    const currentIP = getRealIP(req);
    if (user.discordLinkedIP !== currentIP) {
      return res.status(403).json({ error: 'fuck off nerd nothing to see here' });
    }
  }

  const state = crypto.randomBytes(16).toString('hex');
  const sessionToken = req.headers['x-auth-token'] || req.cookies?.clover_session || req.cookies?.prey_session || req.cookies?.token || '';
  if (!sessionToken) return res.status(401).json({ error: 'Missing active session token' });
  try {
    await DiscordOAuthState.create({
      state,
      token: sessionToken,
      ip: getRealIP(req)
    });
  } catch (error) {
    console.error('[Discord Auth] Failed to save state to MongoDB:', error);
    return res.status(500).json({ error: 'Failed to create OAuth state' });
  }
  const redirectUri = getDiscordLoginRedirectUri(req);
  const url = `https://discord.com/oauth2/authorize?client_id=${DISCORD_CLIENT_ID}&redirect_uri=${encodeURIComponent(redirectUri)}&response_type=code&scope=identify&state=${state}`;
  console.log('[Discord Auth] OAuth URL generated with redirect URI:', redirectUri);
  res.json({ url });
});

app.get('/api/discord/callback', async (req, res) => {
  await ensureDbConnected(5000).catch(() => false);
  const cbState = typeof req.query?.state === 'string' ? req.query.state.trim() : '';
  const cbOAuthErr = typeof req.query?.error === 'string' ? req.query.error.trim() : '';
  const cbCookieState = verifyDiscordOAuthStateCookie(req.cookies?.[DISCORD_STATE_COOKIE]);
  const isLoginWhitelistFlow = Boolean(
    (cbState && pendingDiscordOAuthStates.has(cbState)) ||
    (cbState && cbCookieState && timingSafeCompare(cbCookieState.state, cbState)) ||
    (cbState && mongoose.connection.readyState === 1 && await DiscordOAuthState.exists({ state: cbState, purpose: 'login_whitelist' }).catch(() => null)) ||
    (cbOAuthErr && (req.cookies?.[DISCORD_STATE_COOKIE] || req.cookies?.[DISCORD_PENDING_COOKIE]))
  );
  if (isLoginWhitelistFlow) {
    return handleDiscordLoginWhitelistCallback(req, res);
  }

  const { code, state } = req.query;

  console.log('[Discord Auth] Callback received. State:', state, 'Code:', code ? 'present' : 'missing');

  if (!code || !state) {
    console.error('[Discord Auth] Missing code/state. State:', state);
    return res.status(400).send('Invalid or expired state');
  }

  console.log('[Discord Auth] Looking up state in MongoDB...');
  const stateData = await DiscordOAuthState.findOne({ state });
  console.log('[Discord Auth] State lookup result:', stateData ? 'found' : 'not found');
  if (!stateData) {
    console.error('[Discord Auth] State not found or expired. State:', state);
    return res.status(400).send('Invalid or expired state');
  }

  const token = stateData.token; // This is the user's session token
  await DiscordOAuthState.deleteOne({ state });

  let session = activeSessions.get(token);
  if (!session) {
    const dbSession = await Session.findOne({ token });
    if (!dbSession) {
      console.error('[Discord Auth] Session not found for token:', token);
      return res.status(401).send('Session expired');
    }
    session = buildActiveSessionRecord(dbSession);
  }

  try {
    const redirectUri = getDiscordLoginRedirectUri(req);
    const tokenBody = new URLSearchParams({
      client_id: DISCORD_CLIENT_ID,
      client_secret: DISCORD_CLIENT_SECRET,
      grant_type: 'authorization_code',
      code,
      redirect_uri: redirectUri
    });

    let tokenData;
    let discordUser;


    if (DISCORD_PROXY_URL) {
      console.log('[Discord Auth] Using Cloudflare proxy for token exchange');


      const tokenRes = await fetch(`${DISCORD_PROXY_URL}/token`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          'X-Proxy-Secret': DISCORD_PROXY_SECRET
        },
        body: tokenBody
      });
      tokenData = await tokenRes.json();

      if (!tokenData.access_token) {
        console.error('[Discord Auth] Proxy token exchange failed:', JSON.stringify(tokenData));
        return res.status(400).send('Discord auth failed: ' + (tokenData.error_description || tokenData.error || 'Unknown error'));
      }


      const userRes = await fetch(`${DISCORD_PROXY_URL}/user`, {
        headers: {
          'Authorization': `Bearer ${tokenData.access_token}`,
          'X-Proxy-Secret': DISCORD_PROXY_SECRET
        }
      });
      discordUser = await userRes.json();

    } else {
      console.log('[Discord Auth] Calling Discord API directly (no proxy configured)');


      const tokenRes = await fetch('https://discord.com/api/oauth2/token', {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: tokenBody
      });


      if (tokenRes.status === 429) {
        const retryData = await tokenRes.json();
        const retryAfter = (retryData.retry_after || 5) * 1000;
        console.warn(`[Discord Auth] Rate limited! Waiting ${retryAfter / 1000}s...`);
        await new Promise(resolve => setTimeout(resolve, Math.min(retryAfter, 30000)));
        const retryRes = await fetch('https://discord.com/api/oauth2/token', {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: tokenBody
        });
        tokenData = await retryRes.json();
      } else {
        tokenData = await tokenRes.json();
      }

      if (!tokenData.access_token) {
        console.error('[Discord Auth] Token exchange failed:', JSON.stringify(tokenData));
        if (tokenData.message && tokenData.message.includes('rate limit')) {
          return res.status(429).send('Discord is rate limiting this server. Please wait 2-3 minutes and try again.');
        }
        return res.status(400).send('Discord auth failed: ' + (tokenData.error_description || tokenData.error || 'Unknown error'));
      }

      const userRes = await fetch('https://discord.com/api/users/@me', { headers: { Authorization: `Bearer ${tokenData.access_token}` } });
      discordUser = await userRes.json();
    }

    if (!discordUser.id) return res.status(400).send('Failed to fetch Discord user');

    const existingUser = await User.findOne({ discordId: discordUser.id });
    if (existingUser) {

      if (existingUser.username === session.username) {
        return res.redirect('/app?discord=linked');
      }

      await User.findOneAndUpdate({ discordId: discordUser.id }, { discordId: '', discordUsername: '', discordDisplayName: '', discordAvatar: '' });
    }

    let avatarUrl = '';
    if (discordUser.avatar) {
      avatarUrl = `https://cdn.discordapp.com/avatars/${discordUser.id}/${discordUser.avatar}.png?size=256`;
    } else {
      const defaultIndex = parseInt(discordUser.id.slice(-1)) % 5;
      avatarUrl = `https://cdn.discordapp.com/embed/avatars/${defaultIndex}.png`;
    }

    await User.findOneAndUpdate({ username: session.username }, {
      discordId: discordUser.id,
      discordUsername: discordUser.username + (discordUser.discriminator && discordUser.discriminator !== '0' ? '#' + discordUser.discriminator : ''),
      discordDisplayName: discordUser.global_name || discordUser.username,
      discordAvatar: avatarUrl,
      discordLinkedIP: stateData.ip || ''
    });


    if (typeof activeSessions !== 'undefined' && token) {
      const cur = activeSessions.get(token) || {};
      cur.discordAvatar = avatarUrl;
      cur.discordUsername = discordUser.username + (discordUser.discriminator && discordUser.discriminator !== '0' ? '#' + discordUser.discriminator : '');
      cur.discordDisplayName = discordUser.global_name || discordUser.username;
      cur.avatar = avatarUrl;
      activeSessions.set(token, cur);
    }
    res.redirect('/app?discord=linked');
  } catch (e) {
    console.error('[Discord OAuth] Server Error:', e);
    res.status(500).send('Discord OAuth error');
  }
});

function getDiscordLoginRedirectUri(req) {
  if (DISCORD_REDIRECT_URI && String(DISCORD_REDIRECT_URI).trim()) {
    return String(DISCORD_REDIRECT_URI).trim();
  }
  const host = String(req.get('x-forwarded-host') || req.get('host') || 'hello-drab-sigma.vercel.app').split(',')[0].trim().toLowerCase();
  const proto = isSecureCookieEnv()
    ? 'https'
    : String(req.headers['x-forwarded-proto'] || req.protocol || 'https').split(',')[0].trim();
  return `${proto}://${host}/api/discord/callback`;
}

async function verifyDiscordServerWhitelist(discordUserId, accessToken) {
  if (!DISCORD_GUILD_ID) {
    return { ok: false, code: 'config', reason: 'Discord server whitelist is not configured.' };
  }
  const cleanUserId = String(discordUserId || '').trim();
  if (!cleanUserId) {
    return { ok: false, code: 'missing_user', reason: 'Missing Discord user id.' };
  }
  try {
    if (DISCORD_BOT_TOKEN) {
      try {
        const memberRes = await fetch(`https://discord.com/api/v10/guilds/${encodeURIComponent(DISCORD_GUILD_ID)}/members/${encodeURIComponent(cleanUserId)}`, {
          headers: { Authorization: `Bot ${DISCORD_BOT_TOKEN}` }
        });
        if (memberRes && memberRes.ok) {
          const member = await memberRes.json().catch(() => null);
          if (DISCORD_WHITELIST_ROLE_ID) {
            if (!member || !Array.isArray(member.roles) || !member.roles.includes(DISCORD_WHITELIST_ROLE_ID)) {
              return { ok: false, code: 'no_role', reason: 'Discord account lacks the required whitelist role.' };
            }
          }
          return { ok: true };
        }
        const errBody = memberRes ? await memberRes.json().catch(() => null) : null;
        if (memberRes && memberRes.status === 404 && errBody && Number(errBody.code) === 10007) {
          return { ok: false, code: 'not_in_server', reason: 'Discord account is not in the whitelisted server.' };
        }
        console.warn(`[Discord Whitelist] Bot API lookup failed (${memberRes ? memberRes.status : 'no-res'}) — falling back to OAuth bearer check`);
      } catch (botErr) {
        console.warn('[Discord Whitelist] Bot API error — falling back to OAuth bearer check:', botErr?.message || botErr);
      }
    }

    if (!accessToken) {
      return { ok: false, code: 'missing_token', reason: 'Missing Discord OAuth access token.' };
    }
    if (DISCORD_WHITELIST_ROLE_ID) {
      const memberRes = await fetch(`https://discord.com/api/v10/users/@me/guilds/${encodeURIComponent(DISCORD_GUILD_ID)}/member`, {
        headers: { Authorization: `Bearer ${accessToken}` }
      });
      if (!memberRes || !memberRes.ok) {
        return { ok: false, code: 'not_in_server', reason: 'Discord account is not in the whitelisted server.' };
      }
      const member = await memberRes.json().catch(() => null);
      if (!member || !Array.isArray(member.roles) || !member.roles.includes(DISCORD_WHITELIST_ROLE_ID)) {
        return { ok: false, code: 'no_role', reason: 'Discord account lacks the required whitelist role.' };
      }
      return { ok: true };
    }

    const guildsRes = await fetch('https://discord.com/api/v10/users/@me/guilds', {
      headers: { Authorization: `Bearer ${accessToken}` }
    });
    if (!guildsRes || !guildsRes.ok) {
      return { ok: false, code: 'guild_lookup_failed', reason: 'Unable to verify Discord server membership.' };
    }
    const guilds = await guildsRes.json().catch(() => null);
    if (!Array.isArray(guilds) || !guilds.some(g => g && String(g.id) === DISCORD_GUILD_ID)) {
      return { ok: false, code: 'not_in_server', reason: 'Discord account is not in the whitelisted server.' };
    }
    return { ok: true };
  } catch (err) {
    console.error('[Discord Whitelist Verify Error]', err?.message || err);
    return { ok: false, code: 'error', reason: 'Discord whitelist verification failed.' };
  }
}

app.get('/api/discord/login-start', async (req, res) => {
  await ensureDbConnected(4000).catch(() => false);
  const dcLock = getDiscordClientLockState(req);
  if (dcLock.locked) {
    return res.redirect('/login?discord_error=locked&dc_left=0');
  }
  const pendingToken = String(req.query?.pending || req.cookies?.[DISCORD_PENDING_COOKIE] || '').trim();
  const pendingEntry = (pendingToken ? pendingDiscordLogins.get(pendingToken) : null) || verifyPendingDiscordToken(pendingToken);
  if (!pendingEntry || (pendingEntry.expiresAt && Date.now() > pendingEntry.expiresAt)) {
    if (pendingToken) pendingDiscordLogins.delete(pendingToken);
    return res.redirect('/login?discord_error=expired');
  }
  if (!DISCORD_CLIENT_ID || !DISCORD_CLIENT_SECRET) {
    return res.redirect('/login?discord_error=config');
  }

  pruneBoundedMap(pendingDiscordOAuthStates, (v, t) => !v || (v.expiresAt && t > v.expiresAt));
  const state = crypto.randomBytes(16).toString('hex');
  const stateRecord = {
    state,
    token: pendingToken,
    ip: getRealIP(req),
    purpose: 'login_whitelist',
    pendingLogin: pendingEntry,
    expiresAt: Date.now() + 10 * 60 * 1000
  };
  pendingDiscordOAuthStates.set(state, stateRecord);
  if (mongoose.connection.readyState === 1) {
    await DiscordOAuthState.create({
      state,
      token: pendingToken,
      ip: stateRecord.ip,
      purpose: 'login_whitelist',
      pendingLogin: pendingEntry
    }).catch(() => {});
  }
  res.cookie(DISCORD_STATE_COOKIE, signDiscordOAuthStateCookie(state, pendingToken), {
    httpOnly: true,
    secure: isSecureCookieEnv(),
    sameSite: 'Lax',
    path: '/',
    maxAge: 10 * 60 * 1000
  });

  const redirectUri = getDiscordLoginRedirectUri(req);
  const scope = DISCORD_WHITELIST_ROLE_ID ? 'identify guilds guilds.members.read' : 'identify guilds';
  const url = `https://discord.com/oauth2/authorize?client_id=${encodeURIComponent(DISCORD_CLIENT_ID)}&redirect_uri=${encodeURIComponent(redirectUri)}&response_type=code&scope=${encodeURIComponent(scope)}&state=${encodeURIComponent(state)}&prompt=consent`;
  return res.redirect(url);
});

async function handleDiscordLoginWhitelistCallback(req, res) {
  await ensureDbConnected(7000).catch(() => false);
  const isProdCookie = isSecureCookieEnv();
  const clearPendingCookie = () => {
    res.clearCookie(DISCORD_PENDING_COOKIE, { path: '/', sameSite: 'Lax', httpOnly: true, secure: isProdCookie });
    res.clearCookie(DISCORD_STATE_COOKIE, { path: '/', sameSite: 'Lax', httpOnly: true, secure: isProdCookie });
  };
  const failWhitelistRedirect = (reasonCode = 'failed') => {
    clearPendingCookie();
    const lockState = recordDiscordClientFail(req, res);
    const errParam = lockState.locked ? 'locked' : encodeURIComponent(reasonCode || 'failed');
    return res.redirect(`/login?discord_error=${errParam}&dc_left=${lockState.attemptsRemaining}`);
  };

  if (getDiscordClientLockState(req).locked) {
    clearPendingCookie();
    return res.redirect('/login?discord_error=locked&dc_left=0');
  }

  const code = typeof req.query?.code === 'string' ? req.query.code.trim() : '';
  const state = typeof req.query?.state === 'string' ? req.query.state.trim() : '';
  const oauthErr = typeof req.query?.error === 'string' ? req.query.error.trim() : '';

  let stateData = state ? pendingDiscordOAuthStates.get(state) : null;
  if (state) pendingDiscordOAuthStates.delete(state);
  if (!stateData && state && mongoose.connection.readyState === 1) {
    stateData = await DiscordOAuthState.findOne({ state, purpose: 'login_whitelist' }).catch(() => null);
  }
  if (!stateData && state) {
    const cookieState = verifyDiscordOAuthStateCookie(req.cookies?.[DISCORD_STATE_COOKIE]);
    if (cookieState && timingSafeCompare(cookieState.state, state)) {
      stateData = {
        state: cookieState.state,
        token: cookieState.token,
        expiresAt: cookieState.expiresAt,
        pendingLogin: verifyPendingDiscordToken(cookieState.token)
      };
    }
  }
  if (state && mongoose.connection.readyState === 1) {
    await DiscordOAuthState.deleteOne({ state }).catch(() => {});
  }

  if (!state || !stateData || (stateData.expiresAt && Date.now() > stateData.expiresAt) || oauthErr || !code) {
    if (stateData && stateData.token) pendingDiscordLogins.delete(stateData.token);
    return failWhitelistRedirect('failed');
  }

  const pendingEntry = stateData.pendingLogin || (stateData.token ? (pendingDiscordLogins.get(stateData.token) || verifyPendingDiscordToken(stateData.token)) : null);
  if (stateData.token) pendingDiscordLogins.delete(stateData.token);
  if (!pendingEntry || (pendingEntry.expiresAt && Date.now() > pendingEntry.expiresAt)) {
    clearPendingCookie();
    return res.redirect('/login?discord_error=expired');
  }

  try {
    const redirectUri = getDiscordLoginRedirectUri(req);
    const tokenBody = new URLSearchParams({
      client_id: DISCORD_CLIENT_ID,
      client_secret: DISCORD_CLIENT_SECRET,
      grant_type: 'authorization_code',
      code,
      redirect_uri: redirectUri
    });

    let tokenData = null;
    let discordUser = null;

    if (DISCORD_PROXY_URL) {
      try {
        const tokenRes = await fetch(`${DISCORD_PROXY_URL}/token`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
            'X-Proxy-Secret': DISCORD_PROXY_SECRET
          },
          body: tokenBody
        });
        tokenData = await tokenRes.json().catch(() => null);
        if (tokenData && tokenData.access_token) {
          const userRes = await fetch(`${DISCORD_PROXY_URL}/user`, {
            headers: {
              'Authorization': `Bearer ${tokenData.access_token}`,
              'X-Proxy-Secret': DISCORD_PROXY_SECRET
            }
          });
          discordUser = await userRes.json().catch(() => null);
        }
      } catch (proxyErr) {
        console.warn('[Discord Login Callback] Proxy fetch error:', proxyErr?.message || proxyErr);
      }
      if (!tokenData || !tokenData.access_token || !discordUser || !discordUser.id) {
        console.warn('[Discord Login Callback] Proxy exchange failed — retrying direct Discord API');
        tokenData = null;
        discordUser = null;
      }
    }

    if (!tokenData || !tokenData.access_token) {
      const tokenRes = await fetch('https://discord.com/api/oauth2/token', {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: tokenBody
      });
      tokenData = await tokenRes.json().catch(() => null);
      if (!tokenData || !tokenData.access_token) {
        console.error('[Discord Login Callback] OAuth token exchange failed:', JSON.stringify(tokenData));
        clearPendingCookie();
        return res.redirect('/login?discord_error=oauth_exchange');
      }
      const userRes = await fetch('https://discord.com/api/users/@me', {
        headers: { Authorization: `Bearer ${tokenData.access_token}` }
      });
      discordUser = await userRes.json().catch(() => null);
    }

    if (!discordUser || !discordUser.id) {
      console.error('[Discord Login Callback] Failed to load Discord user profile after token exchange');
      clearPendingCookie();
      return res.redirect('/login?discord_error=oauth_exchange');
    }

    const wl = await verifyDiscordServerWhitelist(discordUser.id, tokenData.access_token);
    if (!wl || !wl.ok) {
      console.warn('[Discord Login Callback] Whitelist check denied:', wl ? wl.reason : 'unknown');
      if (wl && wl.code === 'config') {
        clearPendingCookie();
        return res.redirect('/login?discord_error=config');
      }
      return failWhitelistRedirect('failed');
    }

    let avatarUrl = '';
    if (discordUser.avatar) {
      avatarUrl = `https://cdn.discordapp.com/avatars/${discordUser.id}/${discordUser.avatar}.png?size=256`;
    } else {
      const defaultIndex = parseInt(String(discordUser.id).slice(-1), 10) % 5;
      avatarUrl = `https://cdn.discordapp.com/embed/avatars/${isNaN(defaultIndex) ? 0 : defaultIndex}.png`;
    }
    const discordTag = discordUser.username + (discordUser.discriminator && discordUser.discriminator !== '0' ? '#' + discordUser.discriminator : '');
    const discordDisplay = discordUser.global_name || discordUser.username || '';

    const isRegFlow = pendingEntry.action === 'register';
    if (isRegFlow) {
      if (!pendingEntry.passwordHash || !pendingEntry.key) {
        clearPendingCookie();
        return res.redirect('/login?discord_error=expired');
      }
      const keyDoc = await Key.findById(pendingEntry.key).catch(() => null);
      if (!keyDoc || keyDoc.blacklisted || (keyDoc.requiresRedemption && !keyDoc.redeemed) || keyDoc.status !== 'active' || keyDoc.uses >= keyDoc.maxUses) {
        clearPendingCookie();
        return res.redirect('/login?discord_error=register_unavailable');
      }
      const existing = await User.findOne({ username: { $regex: '^' + escapeRegex(pendingEntry.username) + '$', $options: 'i' } }).catch(() => null);
      if (existing) {
        clearPendingCookie();
        return res.redirect('/login?discord_error=register_unavailable');
      }
      keyDoc.uses += 1;
      await keyDoc.save();
      await User.create({
        username: pendingEntry.username,
        password: pendingEntry.passwordHash,
        licenseKey: pendingEntry.key,
        role: pendingEntry.role || 'customer',
        discordId: discordUser.id,
        discordUsername: discordTag,
        discordDisplayName: discordDisplay,
        discordAvatar: avatarUrl
      });
    } else if (pendingEntry.username !== 'Admin' && typeof User !== 'undefined') {
      const dbUser = await User.findOne({ username: pendingEntry.username }).catch(() => null);
      if (dbUser && dbUser.blacklisted) {
        return failWhitelistRedirect('failed');
      }
      if (dbUser && dbUser.discordId && String(dbUser.discordId).trim() !== '' && String(dbUser.discordId).trim() !== String(discordUser.id)) {
        if (typeof recordCanaryEvent === 'function') {
          await recordCanaryEvent(req, 'discord_account_mismatch', {
            targetAccount: dbUser.username,
            boundDiscordId: String(dbUser.discordId),
            boundDiscordUsername: dbUser.discordUsername || 'unknown',
            attemptedDiscordId: String(discordUser.id),
            attemptedDiscordUsername: discordTag
          }).catch(() => {});
        }
        return failWhitelistRedirect('mismatch');
      }
      await User.findOneAndUpdate({ username: pendingEntry.username }, {
        discordId: discordUser.id,
        discordUsername: discordTag,
        discordDisplayName: discordDisplay,
        discordAvatar: avatarUrl
      }).catch(() => {});
    }

    resetDiscordClientLock(res);
    clearPendingCookie();

    const token = crypto.randomBytes(32).toString('hex');
    const loaderToken = deriveSessionLoaderToken(token);
    const rememberMe = Boolean(pendingEntry.rememberMe);
    const ttlMs = rememberMe ? (30 * 24 * 60 * 60 * 1000) : (24 * 60 * 60 * 1000);
    const expiresAt = new Date(Date.now() + ttlMs);
    const browserHash = computeSessionBrowserHash(req);
    const devBind = createSessionDeviceBinding();
    const boundIp = getRealIP(req);

    activeSessions.set(token, {
      username: pendingEntry.username,
      role: pendingEntry.role || 'customer',
      key: pendingEntry.key || '',
      rememberMe,
      expiresAt: expiresAt.getTime(),
      loaderToken,
      browserHash,
      deviceBindHash: devBind.deviceBindHash,
      boundIp,
      discordAvatar: avatarUrl,
      discordUsername: discordTag,
      discordDisplayName: discordDisplay,
      avatar: avatarUrl
    });
    await Session.create({
      token,
      loaderToken,
      username: pendingEntry.username,
      role: pendingEntry.role || 'customer',
      key: pendingEntry.key || '',
      browserHash,
      deviceBindHash: devBind.deviceBindHash,
      boundIp,
      rememberMe,
      expiresAt
    }).catch(() => {});

    setSecureSessionCookie(res, token, rememberMe);
    setSessionDeviceBindCookie(res, devBind.cookieValue, rememberMe);
    await saveSessionToVault(req, res, {
      username: pendingEntry.username,
      role: pendingEntry.role || 'customer',
      avatar: avatarUrl || pendingEntry.avatar || '',
      sessionToken: token
    }).catch(() => {});

    return res.redirect(isRegFlow ? '/app?registered=1' : '/app');
  } catch (e) {
    console.error('[Discord Login Whitelist Callback Error]', e?.message || e);
    return failWhitelistRedirect('failed');
  }
}

app.get('/api/discord/login-callback', handleDiscordLoginWhitelistCallback);

