app.get('/api/configs', authMiddleware, async (req, res) => {
  try {
    await loadDefaultCloverTableFromDb();
    const user = await User.findOne({ username: req.user.username });
    if (!user || !user.licenseKey) return res.status(400).json({ error: 'No linked key' });
    if (req.user.key !== user.licenseKey) return res.status(403).json({ error: 'Key mismatch' });
    const configs = await Config.find({
      $or: [{ ownerKey: user.licenseKey }, { owner: req.user.username, ownerKey: { $in: ['', null] } }]
    }).sort({ createdAt: -1 });
    const upgradedList = configs.map(c => {
      const obj = typeof c.toObject === 'function' ? c.toObject() : Object.assign({}, c);
      if (typeof obj.content === 'string') obj.content = upgradeServerCloverConfigLua(obj.content);
      return obj;
    });
    res.json(upgradedList);
  } catch (e) { res.status(500).json({ error: 'Database error' }); }
});

app.post('/api/configs/save', writeLimiter, verifyCsrfToken, authMiddleware, async (req, res) => {
  try {
    const { name, content, activate } = req.body;
    if (!name || typeof name !== 'string' || !name.trim() || name.length > 100) return res.status(400).json({ error: 'Invalid config name' });
    if (typeof content !== 'string' || content.length > 400000) return res.status(400).json({ error: 'Invalid config content' });
    const user = await User.findOne({ username: req.user.username });
    if (!user || !user.licenseKey) return res.status(400).json({ error: 'No linked key' });
    if (req.user.key !== user.licenseKey) return res.status(403).json({ error: 'Key mismatch' });

    // Always merge the current global default into a config at the persistence boundary.
    // This prevents a stale editor/client snapshot from saving a config without newly
    // published table features. Existing user values remain intact; only missing keys
    // are supplied by upgradeServerCloverConfigLua.
    await loadDefaultCloverTableFromDb(true);
    const savedContent = upgradeServerCloverConfigLua(content);

    const target = await Config.findOne({ name, $or: [{ ownerKey: user.licenseKey }, { owner: req.user.username, ownerKey: { $in: ['', null] } }] });
    if (target) {
      target.content = savedContent;
      target.ownerKey = user.licenseKey;
      target.createdAt = new Date();
      await target.save();
    } else {
      await Config.create({ name, content: savedContent, owner: req.user.username, ownerKey: user.licenseKey, createdAt: new Date() });
    }

    const kd = await Key.findById(user.licenseKey).catch(() => null);
    if (kd && (activate === true || !kd.activeConfig)) {
      kd.activeConfig = name;
      await kd.save();
    }

    const updateTime = Date.now();
    keyConfigUpdates.set(user.licenseKey, updateTime);
    broadcastToKey(user.licenseKey, { type: 'settings_updated', timestamp: updateTime, key: user.licenseKey });
    // Return the canonical stored content so the editor can adopt the exact version
    // that includes the latest global default fields.
    res.json({ success: true, activeConfig: kd ? kd.activeConfig : name, content: savedContent });
  } catch (e) { res.status(500).json({ error: 'Save failed' }); }
});

app.post('/api/configs/apply-live', writeLimiter, verifyCsrfToken, authMiddleware, async (req, res) => {
  try {
    const content = typeof req.body?.content === 'string' ? req.body.content : '';
    if (!content || content.length > 400000) return res.status(400).json({ error: 'Config content is required' });
    const user = await User.findOne({ username: req.user.username });
    if (!user || !user.licenseKey) return res.status(400).json({ error: 'No linked key' });
    if (req.user.key !== user.licenseKey) return res.status(403).json({ error: 'Key mismatch' });

    const kd = await Key.findById(user.licenseKey).catch(() => null);
    if (!kd) return res.status(404).json({ error: 'Key not found' });

    kd.liveConfigContent = content;
    kd.activeConfig = '__live__';
    await kd.save();

    if (onlineUsers.has(user.licenseKey)) {
      const u = onlineUsers.get(user.licenseKey);
      u.config = 'default';
      onlineUsers.set(user.licenseKey, u);
    }

    const updateTime = Date.now();
    keyConfigUpdates.set(user.licenseKey, updateTime);
    broadcastToKey(user.licenseKey, { type: 'settings_updated', timestamp: updateTime, key: user.licenseKey });
    res.json({ success: true, activeConfig: 'default' });
  } catch (e) {
    res.status(500).json({ error: 'Apply failed' });
  }
});

app.delete('/api/configs/:name', verifyCsrfToken, authMiddleware, async (req, res) => {
  try {
    const user = await User.findOne({ username: req.user.username });
    if (!user || !user.licenseKey) return res.status(400).json({ error: 'No linked key' });
    if (req.user.key !== user.licenseKey) return res.status(403).json({ error: 'Key mismatch' });
    const result = await Config.findOneAndDelete({
      name: req.params.name,
      $or: [{ ownerKey: user.licenseKey }, { owner: req.user.username, ownerKey: { $in: ['', null] } }]
    });
    if (!result) return res.status(404).json({ error: 'Config not found or access denied' });
    res.json({ success: true });
  } catch (e) { res.status(500).json({ error: 'Delete failed' }); }
});

app.get('/api/get-config/:name', async (req, res) => {
  try {
    await loadDefaultCloverTableFromDb();
    res.setHeader('Cache-Control', 'no-cache, no-store, must-revalidate');
    let key = typeof req.query.key === 'string' ? req.query.key.trim() : '';
    if (!key) {
      let sessToken = req.headers['x-auth-token'] || req.cookies?.clover_session || req.cookies?.prey_session || req.cookies?.token || '';
      sessToken = String(sessToken || '').trim();
      if (sessToken) {
        let sessUser = activeSessions.get(sessToken);
        if (!sessUser) {
          const dbSess = await Session.findOne({ token: sessToken }).lean().catch(() => null);
          if (dbSess) sessUser = buildActiveSessionRecord(dbSess);
        }
        if (sessUser) {
          const cfgBind = verifySessionBinding(req, sessUser);
          if (!cfgBind.ok) {
            await reportSessionHijackBlocked(req, sessUser, cfgBind.reason);
            return res.status(401).send('-- Clover: Session locked to original browser and device.');
          }
        }
        if (sessUser && sessUser.key) {
          key = sessUser.key;
        } else if (sessUser && sessUser.username) {
          const u = await User.findOne({ username: sessUser.username }).lean().catch(() => null);
          if (u && u.licenseKey) key = u.licenseKey;
        }

      }
    }
    if (!key) return res.send('-- Clover: Missing key');

    const kd = await Key.findById(key);
    if (!kd || kd.status !== 'active' || isExpired(kd)) return res.send('-- Clover: Key invalid');

    const user = await User.findOne({ licenseKey: key });
    if (!user) return res.send('-- Clover: User not found');

    const requestedName = String(req.params.name || '').trim();
    const cfg = await Config.findOne({
      name: requestedName,
      $or: [{ ownerKey: key }, { owner: user.username, ownerKey: { $in: ['', null] } }]
    }) || await Config.findOne({
      name: new RegExp('^' + escapeRegex(requestedName) + '$', 'i'),
      $or: [{ ownerKey: key }, { owner: user.username, ownerKey: { $in: ['', null] } }]
    });
    if (cfg) return res.send(upgradeServerCloverConfigLua(cfg.content));

    res.send('-- Clover: Config not found');
  } catch (e) { res.send('-- Clover: Server error'); }
});

app.post('/api/change-password', sensitiveUserLimiter, authMiddleware, async (req, res) => {
  try {
    if (!verifyCsrfToken(req, res)) return res.status(403).json({ error: 'Invalid or missing CSRF token' });
    const { currentPassword, newPassword } = req.body;
    if (!currentPassword || !newPassword || typeof currentPassword !== 'string' || typeof newPassword !== 'string') {
      return res.status(400).json({ error: 'Missing fields' });
    }
    if (newPassword.length < 8 || newPassword.length > 128) {
      return res.status(400).json({ error: 'New password must be at least 8 characters' });
    }
    const user = await User.findOne({ username: req.user.username });
    if (!user) return res.status(404).json({ error: 'User not found' });
    if (!verifyPassword(currentPassword, user.password)) {
      return res.status(403).json({ error: 'Current password incorrect' });
    }
    user.password = hashPassword(newPassword);
    await user.save();

    const currentToken = req.headers['x-auth-token'] || req.cookies?.clover_session || req.cookies?.prey_session || req.cookies?.token;
    await Session.deleteMany({ username: user.username, token: { $ne: currentToken } }).catch(() => { });
    await addAuditLog('password_change', user.username, user.username, 'Password updated');
    res.json({ success: true });
  } catch (e) { res.status(500).json({ error: 'Change failed' }); }
});

app.get('/api/activity', authMiddleware, async (req, res) => {
  try {
    const user = await User.findOne({ username: req.user.username });
    if (!user || !user.licenseKey) return res.status(400).json({ error: 'No linked key' });
    const keyDoc = await Key.findById(user.licenseKey);
    const logs = await Log.find({ key: user.licenseKey }).sort({ timestamp: -1 }).limit(50);
    const onlineInfo = onlineUsers.get(user.licenseKey);
    const activeCfgDisplay = (keyDoc?.activeConfig && keyDoc.activeConfig !== '__live__') ? keyDoc.activeConfig : 'Default';
    res.json({
      key: { totalExecutions: keyDoc?.totalExecutions || 0, lastUsed: keyDoc?.lastUsed, activeConfig: activeCfgDisplay, status: keyDoc?.status || 'unknown', expires: keyDoc?.expires, isOnline: Boolean(onlineInfo), placeId: onlineInfo?.placeId || '', gameName: onlineInfo?.gameName || '', gameIcon: onlineInfo?.gameIcon || '' },
      logs: logs.map(l => ({ type: l.type, ip: l.ip, country: l.country, timestamp: l.timestamp }))
    });
  } catch (e) { res.status(500).json({ error: 'Failed' }); }
});

app.get('/api/security', authMiddleware, async (req, res) => {
  try {
    const user = await User.findOne({ username: req.user.username });
    if (!user || !user.licenseKey) return res.status(400).json({ error: 'No linked key' });
    const keyDoc = await Key.findById(user.licenseKey);
    if (!keyDoc) return res.status(404).json({ error: 'Key not found' });
    const sessions = [];
    if (keyDoc.sessions) {
      keyDoc.sessions.forEach((val, sid) => {
        sessions.push({ id: sid, hwid: val.hwid, expires: val.expires, used: val.used });
      });
    }
    const lastLog = await Log.findOne({ key: user.licenseKey }).sort({ timestamp: -1 });

    const blurIP = (ip) => {
      if (!ip || ip === 'Unknown') return 'Unknown';
      const parts = ip.split('.');
      if (parts.length === 4) return `${parts[0]}.${parts[1]}.***.***.***`;
      return 'Unknown';
    };
    const boundHwid = (Array.isArray(keyDoc.activations) && keyDoc.activations.length > 0 && keyDoc.activations[0].hwid)
      || (sessions.length > 0 ? sessions[0].hwid : null)
      || keyDoc.hwid
      || 'Unknown';
    res.json({
      hwid: boundHwid,
      lastIP: blurIP(lastLog?.ip || 'Unknown'),
      lastCountry: lastLog?.country || 'Unknown',
      sessions: sessions.slice(0, 10),
      hwidResetCount: keyDoc.hwidResetCount || 0
    });
  } catch (e) { res.status(500).json({ error: 'Failed' }); }
});

app.post(['/api/hwid-reset', '/api/hwid/reset'], sensitiveUserLimiter, authMiddleware, async (req, res) => {
  try {
    if (!verifyCsrfToken(req, res)) return res.status(403).json({ error: 'Invalid or missing CSRF token' });
    const user = await User.findOne({ username: req.user.username });
    if (!user || !user.licenseKey) return res.status(400).json({ error: 'No linked key' });
    const keyDoc = await Key.findById(user.licenseKey);
    if (!keyDoc) return res.status(404).json({ error: 'Key not found' });
    if (keyDoc.blacklisted) return res.status(403).json({ error: 'Key is blacklisted' });
    keyDoc.activations = [];
    keyDoc.sessions = new Map();
    keyDoc.hwid = null;
    keyDoc.hwidResetCooldown = 0;
    keyDoc.hwidResetCount = (keyDoc.hwidResetCount || 0) + 1;
    await keyDoc.save();
    await addLog('hwid_reset', { key: user.licenseKey, username: user.username, ip: getRealIP(req) });
    await addAuditLog('hwid_reset', user.licenseKey, user.username, 'Self-service HWID reset');
    res.json({ success: true });
  } catch (e) { res.status(500).json({ error: 'Reset failed' }); }
});

