app.post('/api/configs/activate', verifyCsrfToken, authMiddleware, async (req, res) => {
  try {
    const configName = req.body.configName || req.body.name;
    if (!configName) return res.status(400).json({ error: 'Config name required' });
    const user = await User.findOne({ username: req.user.username });
    if (!user || !user.licenseKey) return res.status(400).json({ error: 'No linked key' });
    if (req.user.key !== user.licenseKey) return res.status(403).json({ error: 'Key mismatch' });
    const cfg = await Config.findOne({
      name: configName,
      $or: [{ ownerKey: user.licenseKey }, { owner: req.user.username, ownerKey: { $in: ['', null] } }]
    });
    if (!cfg) return res.status(404).json({ error: 'Config not found' });
    await Key.findByIdAndUpdate(user.licenseKey, { activeConfig: configName });
    if (onlineUsers.has(user.licenseKey)) {
      const u = onlineUsers.get(user.licenseKey);
      u.config = configName;
      onlineUsers.set(user.licenseKey, u);
    }

    const updateTime = Date.now();
    keyConfigUpdates.set(user.licenseKey, updateTime);
    broadcastToKey(user.licenseKey, { type: 'settings_updated', timestamp: updateTime, key: user.licenseKey });
    res.json({ success: true });
  } catch (e) { res.status(500).json({ error: 'Activation failed' }); }
});

app.post('/api/set-active-config', async (req, res) => {
  const { key, hwid, configName } = req.body;
  if (!key || !hwid || !configName) return res.json({ success: false });
  const kd = await Key.findById(key);
  if (!kd) return res.json({ success: false, error: 'Key not found' });
  const user = await User.findOne({ licenseKey: key });
  if (!user) return res.json({ success: false, error: 'User not found' });
  if (onlineUsers.has(key)) {
    const u = onlineUsers.get(key);
    if (u.hwid === hwid) {
      const cfg = await Config.findOne({
        name: configName,
        $or: [{ ownerKey: key }, { owner: user.username, ownerKey: { $in: ['', null] } }]
      });
      if (!cfg) return res.json({ success: false, error: 'Config not found' });
      u.config = configName;
      onlineUsers.set(key, u);
      kd.activeConfig = configName;
      await kd.save();
      return res.json({ success: true });
    }
  }
  res.json({ success: false });
});

app.get('/api/get-active-config', async (req, res) => {
  const key = req.query.key;
  if (!key) return res.json({ success: false, error: 'Missing key' });
  const kd = await Key.findById(key);
  if (!kd || kd.status !== 'active' || isExpired(kd)) return res.json({ success: false, error: 'Key invalid' });
  const rawActive = kd?.activeConfig;
  const active = (rawActive && rawActive !== '__live__') ? rawActive : 'Default';
  res.json({ success: true, config: active });
});

function canPost(req, res, next) {
  if (!req.user) return res.status(401).json({ error: 'Unauthorized' });
  const role = String(req.user.role || '').trim().toLowerCase();
  if (role !== 'admin' && role !== 'owner') {
    return res.status(403).json({ error: 'Admin permission required' });
  }
  return next();
}

