app.post('/api/site-ping', authMiddleware, async (req, res) => {
  if (req.user && req.user.username) {
    const uname = req.user.username;
    if (!hiddenOnlineUsers.has(uname)) {
      const u = await User.findOne({ username: uname }).select('hideOnline').lean().catch(() => null);
      if (u && u.hideOnline) {
        hiddenOnlineUsers.add(uname);
        onlineWebUsers.delete(uname);
      } else {
        onlineWebUsers.set(uname, Date.now());
      }
    }
  }
  res.json({ ok: true });
});

