app.get('/api/marketplace/configs', authMiddleware, async (req, res) => {
  try {
    const viewerUsername = String((req.user && req.user.username) || '').trim();

    const hiddenDb = await User.find({ hideOnline: true }).select('username').lean().catch(() => []);
    hiddenDb.forEach(u => { if (u && u.username) hiddenOnlineUsers.add(u.username); });
    if (viewerUsername) {
      if (hiddenOnlineUsers.has(viewerUsername)) {
        onlineWebUsers.delete(viewerUsername);
      } else {
        onlineWebUsers.set(viewerUsername, Date.now());
      }
    }

    const rawConfigs = await MarketplaceConfig.find().select('-content -combination -authorKey').sort({ createdAt: -1 }).lean();
    const authorNames = [...new Set(rawConfigs.map(c => c.author).filter(Boolean))];
    const authorUsers = authorNames.length
      ? await User.find({ username: { $in: authorNames } }).select('username discordUsername hideOnline').lean().catch(() => [])
      : [];
    const userMap = new Map();
    authorUsers.forEach(u => {
      if (u && u.username) {
        userMap.set(u.username, u);
        if (u.hideOnline) {
          hiddenOnlineUsers.add(u.username);
          onlineWebUsers.delete(u.username);
        }
      }
    });
    const now = Date.now();
    const configs = rawConfigs.map(c => {
      const authorDoc = userMap.get(c.author);
      const isHidden = hiddenOnlineUsers.has(c.author) || Boolean(authorDoc && authorDoc.hideOnline);
      const lastSeen = onlineWebUsers.get(c.author) || 0;
      const isAuthorOnline = !isHidden && (now - lastSeen) < 90000;
      const unlockedArr = Array.isArray(c.unlockedBy) ? c.unlockedBy : [];
      const isUnlockedByViewer = !c.isLocked || (viewerUsername && unlockedArr.includes(viewerUsername));
      const { unlockedBy, ...safeCfg } = c;
      const authorDiscord = (authorDoc && authorDoc.discordUsername) ? String(authorDoc.discordUsername).replace(/^@+/, '').trim() : '';
      return {
        ...safeCfg,
        authorDiscord,
        isAuthorOnline,
        isUnlockedByViewer: Boolean(isUnlockedByViewer)
      };
    });
    res.json({ success: true, configs });
  } catch (e) {
    res.status(500).json({ success: false, error: 'Failed to fetch forum drops' });
  }
});

app.post('/api/marketplace/upload', writeLimiter, authMiddleware, async (req, res) => {
  try {
    const { title, description, game, version, content, customKey, isLocked, combination } = req.body;
    if (!title || !content || typeof content !== 'string' || content.length > 400000) return res.status(400).json({ error: 'Title and valid script content are required' });
    const user = await User.findOne({ username: req.user.username });
    if (!user) return res.status(401).json({ error: 'User not found' });

    let configKey = (customKey && customKey.trim()) ? customKey.trim().toUpperCase() : '';
    if (!configKey || configKey.length < 4) {
      const p1 = crypto.randomBytes(2).toString('hex').toUpperCase();
      const p2 = crypto.randomBytes(2).toString('hex').toUpperCase();
      configKey = 'CFG-' + p1 + '-' + p2;
    }

    const hash = crypto.createHmac('sha256', 'clover_keylock_secret')
      .update(String(content) + user.username + Date.now())
      .digest('hex').substring(0, 16).toUpperCase();
    const fingerprint = 'FPR-' + hash;

    const lockedBool = Boolean(isLocked);
    let sanitizedComb = '';
    if (lockedBool) {
      sanitizedComb = String(combination || '').replace(/\D/g, '').slice(0, 5);
      if (sanitizedComb.length !== 5) {
        return res.status(400).json({ error: 'A locked drop requires an exact 5-digit number combination.' });
      }
    }

    const newConfig = await MarketplaceConfig.create({
      title: String(title).slice(0, 60),
      description: String(description || '').slice(0, 200),
      game: String(game || 'Universal').slice(0, 30),
      version: String(version || '1.0').slice(0, 10),
      author: user.username,
      authorKey: user.licenseKey || '',
      configKey,
      fingerprint,
      content: String(content),
      isLocked: lockedBool,
      combination: sanitizedComb,
      unlockedBy: [user.username],
      isVerified: user.role === 'admin'
    });

    res.json({ success: true, id: newConfig._id, configKey, fingerprint, isLocked: lockedBool });
  } catch (e) {
    res.status(500).json({ error: 'Upload failed: ' + e.message });
  }
});

app.post('/api/marketplace/get-config-content/:id', authMiddleware, async (req, res) => {
  try {
    const cfg = await MarketplaceConfig.findById(req.params.id);
    if (!cfg) return res.status(404).json({ error: 'Config not found' });

    const viewer = req.user.username;
    const alreadyUnlocked = !cfg.isLocked || cfg.author === viewer || (Array.isArray(cfg.unlockedBy) && cfg.unlockedBy.includes(viewer));

    if (!alreadyUnlocked) {
      if (!checkMarketplacePinRate(viewer, cfg._id)) {
        return res.status(429).json({ success: false, error: 'Too many wrong combination attempts. Please wait 15 minutes.' });
      }
      const userComb = String(req.body?.combination || '').replace(/\D/g, '').slice(0, 5);
      if (!userComb || userComb.length !== 5 || !timingSafeCompare(userComb, String(cfg.combination || ''))) {
        recordMarketplacePinFailure(viewer, cfg._id);
        return res.status(403).json({ success: false, error: 'Incorrect 5-number combination' });
      }
      if (!Array.isArray(cfg.unlockedBy)) cfg.unlockedBy = [];
      if (!cfg.unlockedBy.includes(viewer)) {
        cfg.unlockedBy.push(viewer);
      }
      cfg.downloads = (cfg.downloads || 0) + 1;
      await cfg.save();
    } else if (!cfg.isLocked && (!Array.isArray(cfg.unlockedBy) || !cfg.unlockedBy.includes(viewer))) {
      if (!Array.isArray(cfg.unlockedBy)) cfg.unlockedBy = [];
      cfg.unlockedBy.push(viewer);
      cfg.downloads = (cfg.downloads || 0) + 1;
      await cfg.save();
    }

    res.json({ success: true, title: cfg.title, content: cfg.content, configKey: cfg.configKey || cfg.fingerprint, isUnlockedByViewer: true });
  } catch (e) {
    res.status(500).json({ error: 'Failed to retrieve config content' });
  }
});

