app.post('/api/marketplace/install/:id', authMiddleware, async (req, res) => {
  try {
    const user = await User.findOne({ username: req.user.username });
    if (!user || !user.licenseKey) return res.status(400).json({ error: 'Active license key required to bind config' });

    const mk = await MarketplaceConfig.findById(req.params.id);
    if (!mk) return res.status(404).json({ error: 'Marketplace config not found' });

    const viewer = req.user.username;
    const isUnlocked = !mk.isLocked || mk.author === viewer || (Array.isArray(mk.unlockedBy) && mk.unlockedBy.includes(viewer));
    if (!isUnlocked) {
      if (!checkMarketplacePinRate(viewer, mk._id)) {
        return res.status(429).json({ error: 'Too many wrong combination attempts. Please wait 15 minutes.' });
      }
      const userComb = String(req.body?.combination || '').replace(/\D/g, '').slice(0, 5);
      if (!userComb || userComb.length !== 5 || !timingSafeCompare(userComb, String(mk.combination || ''))) {
        recordMarketplacePinFailure(viewer, mk._id);
        return res.status(403).json({ error: 'Unlock this drop with its 5-digit combination first.' });
      }
      if (!Array.isArray(mk.unlockedBy)) mk.unlockedBy = [];
      mk.unlockedBy.push(viewer);
    }

    mk.downloads = (mk.downloads || 0) + 1;
    await mk.save();

    // Server-side binding directly into database
    const cfgName = ('[Market] ' + mk.title.replace(/[^\w\s\-\.\(\)]/g, '')).slice(0, 32);
    await Config.findOneAndUpdate(
      { name: cfgName, ownerKey: user.licenseKey },
      { name: cfgName, content: mk.content, owner: user.username, ownerKey: user.licenseKey, createdAt: new Date() },
      { upsert: true }
    );

    await Key.findByIdAndUpdate(user.licenseKey, { activeConfig: cfgName });
    if (onlineUsers.has(user.licenseKey)) {
      const u = onlineUsers.get(user.licenseKey);
      u.config = cfgName;
      onlineUsers.set(user.licenseKey, u);
    }

    const updateTime = Date.now();
    keyConfigUpdates.set(user.licenseKey, updateTime);
    broadcastToKey(user.licenseKey, { type: 'settings_updated', timestamp: updateTime, activeConfig: cfgName });

    res.json({ success: true, message: 'Config installed and synced to active session!', configName: cfgName, fingerprint: mk.fingerprint });
  } catch (e) {
    console.error('[Marketplace Install]', e?.message || e);
    res.status(500).json({ error: 'Install failed' });
  }
});

