app.post('/api/validate', loaderLimiter, async (req, res) => {
  const { key, hwid, userId, username, userAgent, placeId, gameName, gameIcon } = req.body || {};
  const ip = getRealIP(req);
  if (!key || !hwid) return res.json({ valid: false, error: 'Missing key or HWID' });

  const geo = await getIPInfo(ip);
  if (geo.isVPN && process.env.BLOCK_VPN === 'true') {
    await addLog('vpn_detected', { ip, country: geo.country, city: geo.city, isp: geo.isp, isVPN: true, key, hwid, username });
    return res.json({ valid: false, error: 'VPN/Proxy detected. Please disable and try again.' });
  }

  let kd = await Key.findById(key);
  if (!kd) {
    await addLog('invalid_key', { ip, country: geo.country, city: geo.city, isp: geo.isp, isVPN: geo.isVPN, hwid, username, userId, key, reason: 'Key not found' });
    await updateAnalytics('failed', geo.country);
    return res.json({ valid: false, error: 'WhiteList Error: Key not found' });
  }
  if (kd.status === 'revoked') {
    await addLog('invalid_key', { ip, country: geo.country, city: geo.city, isp: geo.isp, isVPN: geo.isVPN, hwid, username, userId, key, reason: 'Key revoked' });
    return res.json({ valid: false, error: 'Admin has revoked your key' });
  }
  if (kd.status === 'suspended') {
    await addLog('invalid_key', { ip, country: geo.country, city: geo.city, isp: geo.isp, isVPN: geo.isVPN, hwid, username, userId, key, reason: 'Key suspended' });
    return res.json({ valid: false, error: 'Admin has suspended your key' });
  }
  if (kd.requiresRedemption && !kd.redeemed) {
    await addLog('invalid_key', { ip, country: geo.country, city: geo.city, isp: geo.isp, isVPN: geo.isVPN, hwid, username, userId, key, reason: 'Key not redeemed' });
    return res.json({ valid: false, error: 'This key must be redeemed in Discord first. Use the Redeem Key button in our server.' });
  }
  if (isExpired(kd)) {
    await addLog('invalid_key', { ip, country: geo.country, city: geo.city, isp: geo.isp, isVPN: geo.isVPN, hwid, username, userId, key, reason: 'Key expired' });
    return res.json({ valid: false, error: 'WhiteList Error: Key expired' });
  }

  const knownHwids = kd.activations.map(a => a.hwid);
  if (!knownHwids.includes(hwid)) {
    if (knownHwids.length >= kd.maxUses) {
      await addLog('invalid_key', { ip, country: geo.country, city: geo.city, isp: geo.isp, isVPN: geo.isVPN, hwid, username, userId, key, reason: 'Max activations reached' });
      return res.json({ valid: false, error: `Max activations reached (${kd.maxUses})` });
    }
    kd.activations.push({ hwid, userId, username, ip, country: geo.country, city: geo.city, isp: geo.isp, isVPN: geo.isVPN, firstSeen: new Date(), lastSeen: new Date(), userAgent });
    kd.uses++;
    await kd.save();
  } else {
    const act = kd.activations.find(a => a.hwid === hwid);
    if (act) { act.lastSeen = new Date(); act.ip = ip; act.username = username; act.country = geo.country; act.city = geo.city; act.isp = geo.isp; act.isVPN = geo.isVPN; }
    await kd.save();
  }

  const cleanPlaceId = String(placeId || req.body?.place_id || '').replace(/\D/g, '');
  const cleanGameName = String(gameName || req.body?.game_name || '');
  const cleanGameIcon = String(gameIcon || req.body?.game_icon || '');
  onlineUsers.set(key, { hwid, username, ip, country: geo.country, city: geo.city, isp: geo.isp, isVPN: geo.isVPN, config: kd.activeConfig || 'Default', placeId: cleanPlaceId, gameName: cleanGameName, gameIcon: cleanGameIcon, lastHeartbeat: Date.now() });

  const token = crypto.randomBytes(32).toString('hex');
  const expires = new Date(Date.now() + 60000);
  if (!kd.sessions) kd.sessions = new Map();
  kd.sessions.set(token, { hwid, expires, used: false, ip });
  kd.totalExecutions++;
  kd.lastUsed = new Date();
  await kd.save();

  const siteUser = await User.findOne({ licenseKey: key }).select('discordId discordUsername discordDisplayName username');
  const discordId = siteUser?.discordId || '';
  const discordUsername = siteUser?.discordUsername || '';
  const discordDisplayName = siteUser?.discordDisplayName || '';
  const siteUsername = siteUser?.username || '';
  await addLog('script_executed', {
    ip, country: geo.country, city: geo.city, isp: geo.isp, isVPN: geo.isVPN, hwid, username: siteUsername, userId, key, reason: 'Script executed successfully', success: true, userAgent, discordId, discordUsername, discordDisplayName, robloxUsername: username
  });
  await updateAnalytics('execution', geo.country);

  broadcastToAdmins({ type: 'user_online', data: { key, username, placeId: cleanPlaceId, gameName: cleanGameName, gameIcon: cleanGameIcon, country: geo.country, city: geo.city, timestamp: new Date().toISOString() } });
  broadcastToKey(key, { type: 'user_online', data: { self: true, username, placeId: cleanPlaceId, gameName: cleanGameName, gameIcon: cleanGameIcon, timestamp: new Date().toISOString() } });

  res.json({ valid: true, session: token });
});

app.post('/api/get-script', loaderLimiter, async (req, res) => {
  const { key, session, hwid } = req.body || {};
  let kd = await Key.findById(key);
  if (!kd) return res.json({ error: 'Key not found' });
  const sess = kd.sessions?.get(session);
  if (!sess || sess.used || Date.now() > new Date(sess.expires).getTime()) return res.json({ error: 'Session expired' });
  if (sess.hwid !== hwid) return res.json({ error: 'Session HWID mismatch' });
  sess.used = true;
  kd.sessions.set(session, sess);
  await kd.save();
  try {
    let rawLua = null;
    for (const candidate of ['source.lua', 'source']) {
      const candidatePath = path.join(__dirname, candidate);
      if (fs.existsSync(candidatePath)) {
        rawLua = fs.readFileSync(candidatePath, 'utf8');
        break;
      }
    }
    if (!rawLua) {
      rawLua = 'print("Prey: Core Source Missing")';
    } else {
      if (/\r?\ngetgenv\(\)\.Clover = \{/.test(rawLua)) {
        rawLua = rawLua.replace(
          /\r?\ngetgenv\(\)\.Clover = \{/,
          '\nif type(getgenv().Clover) == "table" then getgenv().__PreyUserClover = getgenv().Clover end\ngetgenv().Clover = {'
        );
        rawLua = rawLua.replace(
          "if not getgenv().Clover['Authority'] then",
          'if type(getgenv().__PreyUserClover) == "table" then\n  local function __mergeUser(d, s) for k, v in pairs(s) do if type(v) == "table" and type(d[k]) == "table" then __mergeUser(d[k], v) else d[k] = v end end end\n  __mergeUser(getgenv().Clover, getgenv().__PreyUserClover)\n  getgenv().__PreyUserClover = nil\nend\nif not getgenv().Clover[\'Authority\'] then'
        );
      }
      const reqProto = String(req.headers['x-forwarded-proto'] || req.protocol || 'https').split(',')[0].trim();
      const reqHost = String(req.get('x-forwarded-host') || req.get('host') || 'hello-drab-sigma.vercel.app').split(',')[0].trim();
      const reqApiBaseUrl = `${reqProto}://${reqHost}`;
      rawLua = rawLua
        .replace('local CLOUD_URL = "https://brightside-keysystem.onrender.com/"', `local CLOUD_URL = "${reqApiBaseUrl}"`)
        .replace('http_post(CLOUD_URL, payload)', 'http_post(CLOUD_URL .. "/cloudconfig/save", payload)')
        .replace('http_get(CLOUD_URL .. "?key="', 'http_get(CLOUD_URL .. "/cloudconfig?key="')
        .replace('local host = "https://brightside-keysystem.onrender.com/"', `local host = "${reqApiBaseUrl}"`)
        .replace('warn("Failed saving cloud config:", res)', 'if res ~= "encode_failed" then warn("Failed saving cloud config:", res) end')
        .replace('print("Clover: Preset Sync Update! [" .. hbData.activeConfig .. "]")', '')
        .replace('while task.wait(3) do', 'while task.wait(0.75) do')
        .replace('"/api/get-config/" .. currentConfig', '"/api/get-config/" .. HttpService:UrlEncode(tostring(currentConfig))')
        .replace('"/api/get-config/" .. hbData.activeConfig', '"/api/get-config/" .. HttpService:UrlEncode(tostring(hbData.activeConfig))')
        .replace('"/api/get-config/" .. activeName', '"/api/get-config/" .. HttpService:UrlEncode(tostring(activeName))');
      rawLua = stripLuaComments(rawLua);
    }
    const nonce = crypto.randomBytes(24).toString('hex');
    const streamKey = Buffer.from(`${nonce}:${session}:${hwid}:${key}`, 'utf8');
    const plainBuf = Buffer.from(rawLua, 'utf8');
    const S = new Uint8Array(256);
    for (let i = 0; i < 256; i++) S[i] = i;
    let j = 0;
    for (let i = 0; i < 256; i++) {
      j = (j + S[i] + streamKey[i % streamKey.length]) & 255;
      const tmp = S[i]; S[i] = S[j]; S[j] = tmp;
    }
    const encBuf = Buffer.allocUnsafe(plainBuf.length);
    let iIdx = 0, jIdx = 0;
    for (let n = 0; n < plainBuf.length; n++) {
      iIdx = (iIdx + 1) & 255;
      jIdx = (jIdx + S[iIdx]) & 255;
      const tmp = S[iIdx]; S[iIdx] = S[jIdx]; S[jIdx] = tmp;
      const kByte = S[(S[iIdx] + S[jIdx]) & 255];
      encBuf[n] = plainBuf[n] ^ kByte;
    }
    res.json({ payload: encBuf.toString('base64'), nonce });
  } catch (err) {
    res.json({ error: 'Source file missing' });
  }
});

app.post('/api/heartbeat', async (req, res) => {
  const { key, hwid } = req.body || {};
  if (!key) return res.json({ kick: true, reason: 'Missing key.' });

  let kd = await Key.findById(key);
  if (!kd) return res.json({ kick: true, reason: 'Key no longer exists.' });

  const hbPlaceId = String(req.body.placeId || req.body.place_id || '').replace(/\D/g, '');
  const hbGameName = String(req.body.gameName || req.body.game_name || '');
  const hbGameIcon = String(req.body.gameIcon || req.body.game_icon || '');
  if (onlineUsers.has(key)) {
    const u = onlineUsers.get(key);
    const prevPlaceId = u.placeId || '';
    u.lastHeartbeat = Date.now();
    if (hbPlaceId) u.placeId = hbPlaceId;
    if (hbGameName) u.gameName = hbGameName;
    if (hbGameIcon) u.gameIcon = hbGameIcon;
    onlineUsers.set(key, u);
    if (hbPlaceId && hbPlaceId !== prevPlaceId) {
      broadcastToAdmins({ type: 'user_online', data: { key, username: u.username || '', placeId: u.placeId, gameName: u.gameName || '', gameIcon: u.gameIcon || '', country: u.country || '', city: u.city || '', timestamp: new Date().toISOString() } });
      broadcastToKey(key, { type: 'user_online', data: { self: true, username: u.username || '', placeId: u.placeId, gameName: u.gameName || '', gameIcon: u.gameIcon || '', timestamp: new Date().toISOString() } });
    }
  } else {
    const u = { hwid: hwid || '', username: '', ip: getRealIP(req), config: kd.activeConfig || 'Default', placeId: hbPlaceId, gameName: hbGameName, gameIcon: hbGameIcon, lastHeartbeat: Date.now() };
    onlineUsers.set(key, u);
    broadcastToAdmins({ type: 'user_online', data: { key, username: '', placeId: u.placeId, gameName: u.gameName, gameIcon: u.gameIcon, timestamp: new Date().toISOString() } });
    broadcastToKey(key, { type: 'user_online', data: { self: true, username: '', placeId: u.placeId, gameName: u.gameName, gameIcon: u.gameIcon, timestamp: new Date().toISOString() } });
  }

  const kickInfo = kickQueue.get(key);
  if (kickInfo) {
    kickQueue.delete(key);
    onlineUsers.delete(key);
    await KickEvent.findOneAndUpdate({ key, status: 'pending' }, { status: 'confirmed', confirmedAt: new Date() }, { sort: { timestamp: -1 } });
    return res.json({ kick: true, reason: kickInfo.reason });
  }

  if (kd.status === 'revoked') { onlineUsers.delete(key); return res.json({ kick: true, reason: 'Admin has revoked your key.' }); }
  if (kd.status === 'suspended') { onlineUsers.delete(key); return res.json({ kick: true, reason: 'Admin has suspended you from script.' }); }
  if (isExpired(kd)) { onlineUsers.delete(key); return res.json({ kick: true, reason: 'Your key has expired.' }); }

  const knownHwids = kd.activations.map(a => a.hwid);
  if (!knownHwids.includes(hwid)) {




    console.log(`[Heartbeat] HWID mismatch for key ${key.substring(0, 8)}... (expected one of ${knownHwids.length} activations, got "${hwid.substring(0, 12)}...")`);
  }




  const activeConfig = kd.activeConfig || 'Default';


  if (onlineUsers.has(key)) {
    const u = onlineUsers.get(key);
    u.config = activeConfig;
    onlineUsers.set(key, u);
  }

  const keyLastUpdate = Math.max(keyConfigUpdates.get(key) || 0, globalDefaultTableUpdate || 0);
  const clientLastUpdate = req.body.lastUpdate || 0;
  res.json({
    kick: false,
    activeConfig: activeConfig,
    lastUpdate: keyLastUpdate,
    shouldUpdate: keyLastUpdate > clientLastUpdate
  });
});

app.get('/api/roblox-avatar/:userId', proxyLimiter, authMiddleware, async (req, res) => {
  const userId = req.params.userId;
  if (!userId || !/^\d+$/.test(userId)) return res.status(400).json({ error: 'Invalid user ID' });
  const apiUrl = 'https://thumbnails.roblox.com/v1/users/avatar-headshot?userIds=' + userId + '&size=150x150&format=Png&isCircular=false';
  https.get(apiUrl, { headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' } }, (apiRes) => {
    let body = '';
    apiRes.on('data', chunk => body += chunk);
    apiRes.on('end', () => {
      try {
        const json = JSON.parse(body);
        const imageUrl = json?.data?.[0]?.imageUrl;
        if (imageUrl) res.json({ imageUrl });
        else res.status(500).json({ error: 'No avatar URL' });
      } catch (e) { res.status(500).json({ error: 'Parse failed' }); }
    });
  }).on('error', () => res.status(500).json({ error: 'Fetch failed' }));
});

const robloxGameCache = new Map();
function httpsGetJson(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' } }, (apiRes) => {
      let body = '';
      apiRes.on('data', chunk => body += chunk);
      apiRes.on('end', () => {
        try { resolve(JSON.parse(body)); } catch (e) { reject(e); }
      });
    }).on('error', reject);
  });
}

app.get('/api/roblox-game/:placeId', proxyLimiter, authMiddleware, async (req, res) => {
  const placeId = String(req.params.placeId || '').replace(/\D/g, '');
  if (!placeId) {
    return res.json({ placeId: '', universeId: 0, name: 'In-Game Session', iconUrl: '' });
  }
  const cached = robloxGameCache.get(placeId);
  if (cached && (Date.now() - cached.ts < 30 * 60 * 1000)) {
    return res.json(cached.data);
  }
  const fallback = placeId === '2788229376'
    ? { placeId, universeId: 1008451066, name: '[🦃] Da Hood', iconUrl: 'https://tr.rbxcdn.com/180DAY-13881b400d90922aa395b03ccb63be7c/150/150/Image/Png/noFilter' }
    : { placeId, universeId: 0, name: 'Roblox Place #' + placeId, iconUrl: '' };
  try {
    const uniJson = await httpsGetJson('https://apis.roblox.com/universes/v1/places/' + placeId + '/universe');
    const universeId = uniJson && uniJson.universeId ? uniJson.universeId : 0;
    if (!universeId) return res.json(fallback);
    const [gameJson, iconJson] = await Promise.all([
      httpsGetJson('https://games.roblox.com/v1/games?universeIds=' + universeId).catch(() => null),
      httpsGetJson('https://thumbnails.roblox.com/v1/games/icons?universeIds=' + universeId + '&returnPolicy=PlaceHolder&size=150x150&format=Png&isCircular=false').catch(() => null)
    ]);
    const name = gameJson?.data?.[0]?.name || fallback.name;
    const iconUrl = iconJson?.data?.[0]?.imageUrl || fallback.iconUrl;
    const result = { placeId, universeId, name, iconUrl };
    robloxGameCache.set(placeId, { ts: Date.now(), data: result });
    return res.json(result);
  } catch (e) {
    return res.json(fallback);
  }
});

app.get('/api/admin/analytics', adminMiddleware, async (req, res) => {
  try {
    if (req.user.role !== 'admin') return res.status(403).json({ error: 'Forbidden' });
    const totalUsers = await User.countDocuments();
    const totalKeys = await Key.countDocuments();
    const onlineNow = onlineUsers.size;
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const logsToday = await Log.find({ timestamp: { $gte: today }, type: 'script_executed' });
    const executionsToday = logsToday.length;
    const countryLogs = await Log.find({ timestamp: { $gte: today } }).select('country');
    const countryMap = {};
    countryLogs.forEach(l => { if (l.country) countryMap[l.country] = (countryMap[l.country] || 0) + 1; });
    const topCountries = Object.entries(countryMap).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([country, count]) => ({ country, count }));
    res.json({ totalUsers, totalKeys, onlineNow, executionsToday, topCountries });
  } catch (e) { res.status(500).json({ error: 'Failed' }); }
});

