app.get('/', async (req, res) => {
  try {
    const token = req.cookies?.clover_session || req.cookies?.prey_session || req.cookies?.token || req.headers?.['x-auth-token'];
    const isRemembered = req.cookies?.clover_remember === '1';

    if (token && typeof token === 'string' && typeof PERMANENT_BLACKLISTED_KEYS !== 'undefined' && PERMANENT_BLACKLISTED_KEYS.has(token.trim())) {
      return res.status(403).send('leave and never come back');
    }

    let session = null;
    if (token) {
      session = activeSessions.get(token);
      if (!session && mongoose.connection.readyState === 1) {
        try {
          const dbSession = await Session.findOne({ token });
          if (dbSession) {
            session = buildActiveSessionRecord(dbSession);
            activeSessions.set(token, session);
          }
        } catch (e) { }
      }
    }

    if (session) {
      const rootBind = verifySessionBinding(req, session);
      if (!rootBind.ok) {
        await reportSessionHijackBlocked(req, session, rootBind.reason);
        session = null;
      }
    }

    if (req.__isBlacklistedVisitor) {
      return res.send(getAuthHTML('landing', '', req, res));
    }

    if (session && session.username && blacklistedUsernameCache.set.has(String(session.username).trim().toLowerCase())) {
      req.__isBlacklistedVisitor = true;
      activeSessions.delete(token);
      res.clearCookie('clover_session', { path: '/' });
      res.clearCookie('prey_session', { path: '/' });
      res.clearCookie('token', { path: '/' });
      res.cookie('clover_bl_lock', '1', { path: '/', maxAge: 365 * 24 * 3600 * 1000, sameSite: 'Lax' });
      return res.send(getAuthHTML('landing', '', req, res));
    }

    if (session && (session.rememberMe || isRemembered)) {
      return res.redirect('/app');
    }

    return res.send(getAuthHTML('landing', '', req, res));
  } catch (e) {
    return res.send(getAuthHTML('landing', '', req, res));
  }
});

