app.get('/api/admin-portal/lockout', canaryLimiter, async (req, res) => {
  try {
    const state = await readCanaryLoginLockout(req, res);
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, private');
    return res.json({ success: true, locked: state.locked, lockedUntil: state.lockedUntil, remainingMs: state.remainingMs, attemptsRemaining: state.attemptsRemaining });
  } catch (e) {
    return res.status(503).json({ success: false, error: 'Sign-in protection is temporarily unavailable.' });
  }
});

app.post('/api/admin-portal/login', canaryLimiter, async (req, res) => {
  let lockState;
  try {
    lockState = await readCanaryLoginLockout(req, res);
  } catch (e) {
    return res.status(503).json({ success: false, error: 'Sign-in protection is temporarily unavailable.' });
  }
  if (lockState.locked) {
    return res.status(429).json({ success: false, locked: true, lockedUntil: lockState.lockedUntil, remainingMs: lockState.remainingMs, error: 'Too many incorrect attempts. Sign-in is temporarily locked.' });
  }

  const attemptedUsername = sanitizeCanaryStr(req.body?.username || '', 64);
  const rawPass = typeof req.body?.password === 'string' ? req.body.password : '';
  const matchedLureUser = attemptedUsername.toLowerCase() === CANARY_LURE_CONFIG.username.toLowerCase();
  const matchedLurePass = timingSafeCompare(rawPass, CANARY_LURE_CONFIG.password);
  const authenticated = matchedLureUser && matchedLurePass;

  if (!authenticated) {
    let nextState;
    try {
      nextState = await recordCanaryLoginFailure(req, res);
    } catch (e) {
      return res.status(503).json({ success: false, error: 'Sign-in protection is temporarily unavailable.' });
    }
    await recordCanaryEvent(req, 'canary_login_attempt', {
      authenticated: false,
      usernameMatched: matchedLureUser,
      lockoutTriggered: Boolean(nextState.locked),
      attemptsRemaining: Number(nextState.attemptsRemaining) || 0
    });
    if (nextState.locked) {
      await recordCanaryEvent(req, 'canary_login_lockout_started', {
        durationSec: Math.ceil((Number(nextState.remainingMs) || 0) / 1000),
        stage: Number(nextState.stage) || 0
      });
      return res.status(429).json({
        success: false,
        locked: true,
        lockedUntil: nextState.lockedUntil,
        remainingMs: nextState.remainingMs,
        error: 'Too many incorrect attempts. Sign-in is temporarily locked.'
      });
    }
    return res.status(401).json({
      success: false,
      error: 'Invalid credentials.',
      attemptsRemaining: nextState.attemptsRemaining
    });
  }

  try {
    await clearCanaryLoginFailure(req, res);
  } catch (e) {
    return res.status(503).json({ success: false, error: 'Sign-in protection is temporarily unavailable.' });
  }
  await recordCanaryEvent(req, 'canary_lure_credentials_used', {
    authenticated: true,
    usernameMatched: true,
    passwordMatched: true
  });

  const token = crypto.randomBytes(32).toString('hex');
  const expiresAt = Date.now() + CANARY_SESSION_TTL_MS;
  canarySessions.set(token, { username: CANARY_LURE_CONFIG.username, role: 'canary-admin', expiresAt });
  res.cookie('clover_admin_session', token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'Strict',
    path: '/api/admin-portal',
    maxAge: CANARY_SESSION_TTL_MS
  });
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, private');
  return res.json({ success: true, username: CANARY_LURE_CONFIG.username, expiresAt });
});

