const canaryGeneratedFakeKeys = [];

app.post('/api/admin-portal/action', canaryLimiter, requireCanarySession, async (req, res) => {
  const allowedActions = new Set(['generate_key', 'export_keys', 'reveal_key', 'revoke_user', 'refresh_sessions', 'toggle_maintenance']);
  const action = sanitizeCanaryStr(req.body?.action || 'unknown', 48);
  if (action === 'logout') return res.status(400).json({ success: false, error: 'Use the sign-out control.' });
  if (!allowedActions.has(action)) return res.status(400).json({ success: false, error: 'Unknown action.' });
  await recordCanaryEvent(req, 'canary_action', { action, targetType: 'synthetic_record' });
  if (action === 'generate_key') {
    const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789';
    let keyPart = '';
    for (let i = 0; i < 4; i++) keyPart += alphabet[crypto.randomInt(0, alphabet.length)];
    const key = 'CLOVER-' + keyPart + '-' + String(1000 + crypto.randomInt(0, 9000));
    const record = { key, owner: 'unassigned', status: 'active', uses: 0, maxUses: 1, generatedAt: new Date().toISOString() };
    canaryGeneratedFakeKeys.unshift(record);
    if (canaryGeneratedFakeKeys.length > 100) canaryGeneratedFakeKeys.length = 100;
    return res.json({ success: true, message: 'Key generated successfully: ' + key, generatedKey: key, fakeOnly: true });
  }
  return res.json({ success: true, message: 'Action completed successfully.', fakeOnly: true });
});

