app.get('/app', async (req, res) => {
  try {
    const token = req.cookies?.clover_session || req.cookies?.prey_session || req.cookies?.token || req.headers?.['x-auth-token'];

    if (token && typeof token === 'string' && typeof PERMANENT_BLACKLISTED_KEYS !== 'undefined' && PERMANENT_BLACKLISTED_KEYS.has(token.trim())) {
      return res.status(403).send('leave and never come back');
    }

    let session = null;
    if (token) {
      session = activeSessions.get(token);
      if (!session && mongoose.connection.readyState === 1) {
        try {
          const dbSess = await Session.findOne({ token });
          if (dbSess) {
            let role = dbSess.role || 'customer';
            let key = dbSess.key || '';
            if (typeof User !== 'undefined') {
              const dbUser = await User.findOne({ username: dbSess.username });
              if (dbUser && (dbUser.blacklisted || blacklistedUsernameCache.set.has(String(dbUser.username || '').trim().toLowerCase()))) {
                blacklistedUsernameCache.set.add(String(dbUser.username || '').trim().toLowerCase());
                await Session.deleteOne({ token }).catch(() => {});
                res.clearCookie('clover_session', { path: '/' });
                res.clearCookie('prey_session', { path: '/' });
                res.clearCookie('token', { path: '/' });
                res.cookie('clover_bl_lock', '1', { path: '/', maxAge: 365 * 24 * 3600 * 1000, sameSite: 'Lax' });
                return res.redirect('/');
              }
              if (dbUser) { role = dbUser.role || role; key = dbUser.licenseKey || key; }
            }
            session = buildActiveSessionRecord(dbSess, { role, key });
            activeSessions.set(token, session);
          }
        } catch (e) { }
      }
    }

    // If user is authenticated, verify browser + device binding before rendering the dashboard
    if (session) {
      const appBind = verifySessionBinding(req, session);
      if (!appBind.ok) {
        await reportSessionHijackBlocked(req, session, appBind.reason);
        return res.redirect('/login?session_error=bound_mismatch');
      }
      res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, private');
      res.setHeader('Pragma', 'no-cache');
      return res.send(await getAppHTML(req, res));
    }

    // If unauthenticated or no valid session, redirect directly to login screen
    return res.redirect('/login');
  } catch (e) {
    return res.redirect('/login');
  }
});

const BUNDLED_DASH_HEAD_JS = `(function() {
  var __clBoot = {};
  try {
    var __bel = document.getElementById('__cl_boot');
    if (__bel) __clBoot = JSON.parse(__bel.textContent || '{}');
  } catch (e) {}
  var __uRaw = (typeof __clBoot.s === 'string') ? __clBoot.s : '';
  var __uScope = (__uRaw && __uRaw !== 'user') ? ('__u_' + __uRaw) : '';
  function _sGet(k) {
    try { return __uScope ? localStorage.getItem(k + __uScope) : null; } catch(e) { return null; }
  }
  try {
    var purge = ['prey_user','prey_token','prey_key','prey_role','clover_user','clover_token','clover_key','clover_role','clover_saved_accounts','clover_editor_tabs','clover_active_tab','clover_scratch_cache','token','auth','session','user','jwt','prey_session'];
    purge.forEach(function(k) { localStorage.removeItem(k); sessionStorage.removeItem(k); });
    for (var i = localStorage.length - 1; i >= 0; i--) {
      var k = localStorage.key(i);
      if (k && /token|auth|session|user|prey/i.test(k) && k.indexOf('__u_') === -1 && k !== 'clover_hwid_reset_time') {
        localStorage.removeItem(k);
      }
    }
  } catch(e) {}
  try {
    var savedCollapsed = localStorage.getItem('clover_sidebar_collapsed');
    if (savedCollapsed === '1' && window.innerWidth > 768) {
      document.documentElement.classList.add('sidebar-collapsed');
    }
  } catch(e) {}
  try {
    var savedBg = _sGet('clover_bg_theme');
    if (savedBg) {
      var bgData = JSON.parse(savedBg);
      var bgUrl = bgData && bgData.url;
      if (bgUrl) {
        var styleEl = document.createElement('style');
        styleEl.id = 'early-bg-style';
        if (bgUrl === 'void') {
          styleEl.textContent = '.sunset-backdrop, .nature-backdrop { background-image: none !important; background-color: #06080a !important; }';
        } else {
          var rawBgStr = String(bgUrl).trim();
          var lowerBg = rawBgStr.toLowerCase();
          var okBgPrefix = (rawBgStr.indexOf('/a/') === 0 || rawBgStr === '/sunset.jpg' || rawBgStr.indexOf('/api/bg-proxy?') === 0 || lowerBg.indexOf('https://') === 0);
          var hasBadBgChar = /["'<>(){};]/.test(rawBgStr) || rawBgStr.indexOf(String.fromCharCode(92)) !== -1;
          for (var bi = 0; !hasBadBgChar && bi < rawBgStr.length; bi++) {
            var bCode = rawBgStr.charCodeAt(bi);
            if (bCode <= 32 || bCode === 127) hasBadBgChar = true;
          }
          var safeBgUrl = (okBgPrefix && !hasBadBgChar) ? rawBgStr : '';
          if (safeBgUrl) {
            styleEl.textContent = '.sunset-backdrop, .nature-backdrop { background-image: url("' + safeBgUrl + '") !important; background-color: transparent !important; }';
          }
        }
        document.head.appendChild(styleEl);
      }
    }
  } catch(e) {}
  try {
    try {
      var savedEarlyTheme = _sGet('clover_theme');
      if (savedEarlyTheme) {
        var cmap = { 'emerald': '#10b981', 'violet': '#8b5cf6', 'sapphire': '#38bdf8', 'ruby': '#f43f5e', 'amber': '#f59e0b', 'obsidian': '#ffffff', 'white': '#ffffff' };
        var eHex = cmap[savedEarlyTheme];
        if (eHex) {
          document.documentElement.style.setProperty('--accent', eHex);
          document.documentElement.style.setProperty('--gs-accent', eHex);
          document.documentElement.style.setProperty('--green-main', eHex);
        }
      }
    } catch(e) {}
    var saved = _sGet('clover_theme_config');
    if (saved) {
      var c = JSON.parse(saved);
      if (c && c.primary) {
        var r = document.documentElement;
        r.style.setProperty('--accent', c.primary);
        r.style.setProperty('--gs-accent', c.primary);
        r.style.setProperty('--green-main', c.primary);
        if (c.secondary) {
          r.style.setProperty('--accent-secondary', c.secondary);
          r.style.setProperty('--theme-gradient', 'linear-gradient(135deg, ' + c.primary + ' 0%, ' + c.secondary + ' 100%)');
        }
        if (c.cardColor) {
          var hex = String(c.cardColor).replace('#', '');
          if (hex.length === 3) hex = hex[0] + hex[0] + hex[1] + hex[1] + hex[2] + hex[2];
          var num = parseInt(hex, 16);
          var red = (num >> 16) & 255;
          var grn = (num >> 8) & 255;
          var blu = num & 255;
          var op = (c.cardOpacity !== undefined ? c.cardOpacity : 58) / 100;
          var rgba = 'rgba(' + red + ',' + grn + ',' + blu + ',' + op + ')';
          r.style.setProperty('--card-bg', rgba);
          r.style.setProperty('--theme-card-bg', rgba);
          r.style.setProperty('--vinyl-bg', rgba);
          r.style.setProperty('--theme-vinyl-bg', rgba);
          r.style.setProperty('--sidebar-bg', rgba);
          r.style.setProperty('--theme-sidebar-bg', rgba);
        }
      }
    } else {
      var dr = document.documentElement;
      dr.style.setProperty('--accent', '#ffffff');
      dr.style.setProperty('--accent-rgb', '255,255,255');
      dr.style.setProperty('--gs-accent', '#ffffff');
      dr.style.setProperty('--green-main', '#ffffff');
      dr.style.setProperty('--card-bg', 'rgba(15,15,18,0.58)');
      dr.style.setProperty('--card-border', 'rgba(255,255,255,0)');
      dr.style.setProperty('--sidebar-bg', 'rgba(15,15,18,0.58)');
    }
  } catch(e) {}
})();`;

