function getDashboardMainVmAsset(tier = 'cust') {
  const safeTier = (tier === 'admin' || tier === 'sty') ? tier : 'cust';
  if (DASHBOARD_VM_ASSETS[safeTier]) return DASHBOARD_VM_ASSETS[safeTier];
  const cuSentinelObj = {
    username: safeTier === 'sty' ? 'sty' : '__CLOVER_BOOT_USER__',
    role: safeTier === 'cust' ? 'customer' : 'admin',
    hasKey: false,
    discordId: '',
    discordUsername: '',
    discordDisplayName: '',
    discordAvatar: '',
    avatar: '',
    hideOnline: false
  };
  const rawHtml = getAppHTMLRaw(
    '',
    safeTier !== 'cust',
    { username: cuSentinelObj.username, role: cuSentinelObj.role, key: '' },
    '__CLOVER_BOOT_DEFAULT_LUA__',
    false
  );
  const anchorIdx = rawHtml.indexOf('var currentUser = ');
  if (anchorIdx === -1) throw new Error('Dashboard main script anchor missing for tier ' + safeTier);
  const openScriptIdx = rawHtml.lastIndexOf('<script>', anchorIdx);
  const closeScriptIdx = rawHtml.indexOf('</script>', anchorIdx);
  if (openScriptIdx === -1 || closeScriptIdx === -1) throw new Error('Dashboard script boundaries missing for tier ' + safeTier);
  let mainJs = rawHtml.slice(openScriptIdx + '<script>'.length, closeScriptIdx);

  const exactCuDecl = 'var currentUser = ' + safeJsonForScript(cuSentinelObj) + ';';
  const exactLuaDecl = 'var __serverDefaultTableLua = "__CLOVER_BOOT_DEFAULT_LUA__";';
  const exactForceDecl = 'var __serverForceNewDisabled = false;';
  if (!mainJs.includes(exactCuDecl) || !mainJs.includes(exactLuaDecl) || !mainJs.includes(exactForceDecl)) {
    throw new Error('Dashboard boot initializer mismatch for tier ' + safeTier);
  }
  const bootPrelude = "var __clBoot=(function(){try{var e=document.getElementById('__cl_boot');return e?JSON.parse(e.textContent||'{}'):{};}catch(x){return {};}})();";
  mainJs = mainJs.replace(
    exactCuDecl,
    bootPrelude + "var currentUser=__clBoot.u||{username:'User',role:'customer',hasKey:false};"
  );
  mainJs = mainJs.replace(
    exactLuaDecl,
    "var __serverDefaultTableLua=(typeof __clBoot.d==='string')?__clBoot.d:'';"
  );
  mainJs = mainJs.replace(
    exactForceDecl,
    'var __serverForceNewDisabled=Boolean(__clBoot.f);'
  );
  const asset = buildHardenedAsset(mainJs, 'application/javascript; charset=utf-8', 'clover-dash-' + safeTier, 'js', 'js-vm');
  DASHBOARD_VM_ASSETS[safeTier] = asset;
  return asset;
}

async function resolveRequestSession(req) {
  const rawToken = req.cookies?.clover_session || req.cookies?.prey_session || req.cookies?.token || req.headers?.['x-auth-token'];
  const token = typeof rawToken === 'string' ? rawToken.trim() : '';
  if (!token) return null;
  if (typeof PERMANENT_BLACKLISTED_KEYS !== 'undefined' && PERMANENT_BLACKLISTED_KEYS.has(token)) {
    return null;
  }
  let session = activeSessions.get(token) || null;
  if (!session && mongoose.connection.readyState === 1 && typeof Session !== 'undefined') {
    try {
      const dbSess = await Session.findOne({ token });
      if (dbSess) {
        let role = dbSess.role || 'customer';
        let key = dbSess.key || '';
        if (typeof User !== 'undefined') {
          const dbUser = await User.findOne({ username: dbSess.username });
          if (dbUser && dbUser.blacklisted) {
            await Session.deleteOne({ token }).catch(() => {});
            return null;
          }
          if (dbUser) { role = dbUser.role || role; key = dbUser.licenseKey || key; }
        }
        session = buildActiveSessionRecord(dbSess, { role, key });
        activeSessions.set(token, session);
      }
    } catch (e) {}
  }
  if (session) {
    const reqBind = verifySessionBinding(req, session);
    if (!reqBind.ok) {
      await reportSessionHijackBlocked(req, session, reqBind.reason);
      return null;
    }
  }
  if (session && session.username && typeof User !== 'undefined' && mongoose.connection.readyState === 1) {
    try {
      const dbU = await User.findOne({ username: session.username }).select('blacklisted role licenseKey').lean();
      if (dbU && dbU.blacklisted) return null;
      if (dbU) {
        session = { ...session, role: dbU.role || session.role, key: dbU.licenseKey || session.key };
      }
    } catch (e) {}
  }
  return session;
}

function sendPrivateHardenedAsset(req, res, asset) {
  res.setHeader('Content-Type', asset.contentType);
  res.setHeader('ETag', asset.etag);
  res.setHeader('Cross-Origin-Resource-Policy', 'same-origin');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('Cache-Control', 'private, max-age=3600, must-revalidate');
  const inm = String(req.headers['if-none-match'] || '').trim();
  if (inm && inm === asset.etag) {
    return res.status(304).end();
  }
  return res.send(asset.body);
}

app.get('/assets/clover-dash-head.:hash.min.js', staticAssetLimiter, async (req, res) => {
  const session = await resolveRequestSession(req);
  if (!session) return res.status(404).send('Not found');
  const asset = getDashboardHeadVmAsset();
  if (!/^[a-f0-9]{12}$/.test(String(req.params.hash || '')) || req.params.hash !== asset.hashShort) {
    return res.status(404).send('Not found');
  }
  return sendPrivateHardenedAsset(req, res, asset);
});

app.get('/assets/clover-dash-:tier.:hash.min.js', staticAssetLimiter, async (req, res) => {
  const tier = String(req.params.tier || '');
  if (tier !== 'cust' && tier !== 'admin' && tier !== 'sty') {
    return res.status(404).send('Not found');
  }
  const session = await resolveRequestSession(req);
  if (!session) return res.status(404).send('Not found');
  const isSessAdmin = Boolean(session.role === 'admin' || session.role === 'owner' || (ADMIN_KEY && session.key === ADMIN_KEY));
  const isSessSty = Boolean(isSessAdmin && String(session.username || '').trim().toLowerCase() === 'sty');
  if (tier === 'admin' && !isSessAdmin) return res.status(404).send('Not found');
  if (tier === 'sty' && !isSessSty) return res.status(404).send('Not found');
  const asset = getDashboardMainVmAsset(tier);
  if (!/^[a-f0-9]{12}$/.test(String(req.params.hash || '')) || req.params.hash !== asset.hashShort) {
    return res.status(404).send('Not found');
  }
  return sendPrivateHardenedAsset(req, res, asset);
});

