    function getCsrf() {
    var meta = document.querySelector('meta[name="csrf-token"]');
    return meta ? meta.getAttribute('content') : '';
  }

  window.getCsrfToken = getCsrf;

  async function api(path, opts = {}) {
    try {
      const headers = {
        'Content-Type': 'application/json',
        'x-csrf-token': getCsrf(),
        ...(opts.headers || {})
      };
      const r = await fetch(path, { ...opts, headers });
      if (!r.ok) {
        const text = await r.text().catch(() => 'Error');
        return { error: text, status: r.status };
      }
      const ct = r.headers.get('content-type') || '';
      if (ct.includes('application/json')) return await r.json();
      return { text: await r.text(), ok: true };
    } catch (e) {
      return { error: (e && e.message) || 'Network error' };
    }
  }

  window.api = api;

  function showToast(title, msg, type) {
    var stack = document.getElementById('toastStack');
    if (!stack) return;
    while (stack.children.length >= 3) {
      stack.removeChild(stack.firstChild);
    }

    var t = document.createElement('div');
    t.className = 'toast-msg-card';

    var isErr = type === 'error';
    var isInf = type === 'info';
    var iconClass = isErr ? 'fa-circle-exclamation' : (isInf ? 'fa-circle-info' : 'fa-circle-check');
    var iconColor = isErr ? '#ef4444' : (isInf ? '#60a5fa' : '#34d399');

    var ic = document.createElement('i');
    ic.className = 'fa-solid ' + iconClass;
    ic.style.cssText = 'color:' + iconColor + '; font-size:13px; margin-top:2px; flex-shrink:0;';
    t.appendChild(ic);

    var textWrap = document.createElement('div');
    textWrap.style.cssText = 'flex:1; min-width:0;';
    var titleDiv = document.createElement('div');
    titleDiv.style.cssText = 'font-family:var(--font-heading, "Inter", sans-serif); font-weight:700; font-size:12px; color:#f4f4f6; letter-spacing:0.01em; line-height:1.3;';
    titleDiv.textContent = String(title || '');
    textWrap.appendChild(titleDiv);
    if (msg) {
      var msgDiv = document.createElement('div');
      msgDiv.style.cssText = 'font-size:11.5px; color:#8c96ad; margin-top:2px; line-height:1.35; word-break:break-word;';
      msgDiv.textContent = String(msg || '');
      textWrap.appendChild(msgDiv);
    }
    t.appendChild(textWrap);

    function dismissToast() {
      if (t.classList.contains('leaving')) return;
      t.classList.remove('show');
      t.classList.add('leaving');
      setTimeout(function() { if (t.parentNode) t.parentNode.removeChild(t); }, 220);
    }

    var closeBtn = document.createElement('button');
    closeBtn.type = 'button';
    closeBtn.innerHTML = '<i class="fa-solid fa-xmark"></i>';
    closeBtn.style.cssText = 'background:transparent; border:none; color:#64748b; cursor:pointer; font-size:11px; padding:2px 4px; line-height:1; border-radius:4px; flex-shrink:0; transition:color 0.15s;';
    closeBtn.onmouseover = function() { closeBtn.style.color = '#e2e8f0'; };
    closeBtn.onmouseout = function() { closeBtn.style.color = '#64748b'; };
    closeBtn.onclick = dismissToast;
    t.appendChild(closeBtn);

    var progTrack = document.createElement('div');
    progTrack.className = 'toast-progress-track';
    var progBar = document.createElement('div');
    progBar.className = 'toast-progress-bar';
    progTrack.appendChild(progBar);
    t.appendChild(progTrack);

    stack.appendChild(t);
    requestAnimationFrame(function() {
      requestAnimationFrame(function() { t.classList.add('show'); });
    });
    setTimeout(dismissToast, 3800);
  }
  window.showToast = showToast;

