  window.submitSwitchAccount = async function() {
    var uInp = document.getElementById('switch-acc-username');
    var pInp = document.getElementById('switch-acc-password');
    var errEl = document.getElementById('switch-acc-error');
    var btn = document.getElementById('btn-confirm-switch-account');
    var username = uInp ? uInp.value.trim() : '';
    var password = pInp ? pInp.value : '';
    if (!username || !password) {
      if (errEl) { errEl.textContent = 'Enter both username and password.'; errEl.style.display = 'block'; }
      return;
    }
    if (errEl) { errEl.style.display = 'none'; errEl.textContent = ''; }
    if (btn) { btn.disabled = true; btn.textContent = 'Switching...'; }
    try {
      await window.ensureCurrentAccountSaved(true);
      isSwitchingAccount = true;
      var res = await fetch('/api/login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-csrf-token': typeof getCsrf === 'function' ? getCsrf() : ''
        },
        credentials: 'include',
        body: JSON.stringify({ username: username, password: password })
      });
      var data = await res.json().catch(function() { return {}; });
      if (!res.ok || !data || !data.success) {
        isSwitchingAccount = false;
        if (res.status === 429 && data && data.locked) {
          window.location.replace('/login');
          return;
        }
        var errMsg = (data && data.error) || 'Invalid credentials.';
        if (data && typeof data.attemptsRemaining === 'number' && data.attemptsRemaining > 0) {
          errMsg += ' (' + data.attemptsRemaining + ' attempt' + (data.attemptsRemaining === 1 ? '' : 's') + ' left)';
        }
        if (errEl) { errEl.textContent = errMsg; errEl.style.display = 'block'; }
        if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fa-solid fa-arrow-right-arrow-left"></i> Add &amp; Switch'; }
        return;
      }
      var canonicalUser = data.username || username;
      try {
        localStorage.removeItem('clover_dashboard_tab');
        sessionStorage.removeItem('clover_dashboard_tab');
        var purge = ['prey_user','prey_token','prey_key','prey_role','clover_user','clover_token','clover_key','clover_role','clover_saved_accounts','clover_editor_tabs','clover_active_tab','clover_scratch_cache','token','auth','session','user','jwt','prey_session'];
        purge.forEach(function(k) { localStorage.removeItem(k); sessionStorage.removeItem(k); });
      } catch (e) {}
      if (typeof showToast === 'function') showToast('Account Switched', 'Signed in as ' + canonicalUser + '.', 'success');
      window.location.replace('/app');
    } catch (e) {
      isSwitchingAccount = false;
      if (errEl) { errEl.textContent = 'Network error while switching accounts.'; errEl.style.display = 'block'; }
      if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fa-solid fa-arrow-right-arrow-left"></i> Add &amp; Switch'; }
    }
  };

  

  


