  var playStartWall = performance.now();
  var playBaseTime = currentTrackTime;

  function syncAudioTime(newTime) {
    currentTrackTime = typeof newTime === 'number' ? newTime : parseFloat(newTime) || 0;
    playBaseTime = currentTrackTime;
    playStartWall = performance.now();
  }

  function getCurrentAudioTime() {
    if (!isPlaying) return currentTrackTime;
    var now = performance.now();
    var elapsedSec = (now - playStartWall) / 1000;
    if (elapsedSec >= 0 && elapsedSec < 5) {
      return playBaseTime + elapsedSec;
    }
    return currentTrackTime;
  }

