  /* Playlist & Vinyl Songs Management Functions */
  function extractYouTubeId(url) {
    if (!url) return null;
    url = String(url).trim();
    if (url.length === 11 && !url.includes('/') && !url.includes('.')) return url;

    var ytBeIdx = url.indexOf('youtu.be/');
    if (ytBeIdx !== -1) {
      var seg = url.substring(ytBeIdx + 9).split('?')[0].split('&')[0].split('/')[0].split('#')[0];
      if (seg && seg.length === 11) return seg;
    }

    var vIdx = url.indexOf('v=');
    if (vIdx !== -1) {
      var seg2 = url.substring(vIdx + 2).split('&')[0].split('#')[0].split('/')[0].split('?')[0].split('#')[0];
      if (seg2 && seg2.length === 11) return seg2;
    }

    var embIdx = url.indexOf('embed/');
    if (embIdx !== -1) {
      var seg3 = url.substring(embIdx + 6).split('?')[0].split('&')[0].split('/')[0].split('#')[0];
      if (seg3 && seg3.length === 11) return seg3;
    }

    return null;
  }

