  window.handleCustomBgFileUpload = function(input) {
    var file = input && input.files && input.files[0];
    if (!file) return;
    if (!file.type || file.type.indexOf('image/') !== 0) {
      if (typeof showToast === 'function') showToast('Invalid File', 'Please select an image file.', 'error');
      return;
    }
    if (file.size > 6 * 1024 * 1024) {
      if (typeof showToast === 'function') showToast('File Too Large', 'Please choose an image under 6 MB.', 'error');
      return;
    }
    var reader = new FileReader();
    reader.onload = function() {
      if (typeof reader.result === 'string' && reader.result.indexOf('data:image/') === 0) {
        window.setBgTheme('custom', reader.result);
        if (typeof showToast === 'function') showToast('Wallpaper Uploaded', 'Custom image applied from device.', 'success');
      }
    };
    reader.readAsDataURL(file);
  };

