  window.switchLaunchInternalTab = function(tabName) {
    var isCleanup = tabName === 'cleanup';
    var pStartup = document.getElementById('launch-panel-startup');
    var pCleanup = document.getElementById('launch-panel-cleanup');
    var bStartup = document.getElementById('launch-tab-btn-startup');
    var bCleanup = document.getElementById('launch-tab-btn-cleanup');
    if (pStartup) pStartup.style.display = isCleanup ? 'none' : 'block';
    if (pCleanup) pCleanup.style.display = isCleanup ? 'block' : 'none';
    if (bStartup) {
      bStartup.style.backgroundColor = !isCleanup ? 'rgba(255, 255, 255, 0.1)' : 'transparent';
      bStartup.style.borderColor = !isCleanup ? 'rgba(255, 255, 255, 0.18)' : 'transparent';
      bStartup.style.color = !isCleanup ? '#f4f4f6' : '#8c96ad';
    }
    if (bCleanup) {
      bCleanup.style.backgroundColor = isCleanup ? 'rgba(255, 255, 255, 0.1)' : 'transparent';
      bCleanup.style.borderColor = isCleanup ? 'rgba(255, 255, 255, 0.18)' : 'transparent';
      bCleanup.style.color = isCleanup ? '#f4f4f6' : '#8c96ad';
    }
  };

