  function _formatRunningDuration(totalSeconds) {
    var sec = Math.max(0, Math.floor(Number(totalSeconds) || 0));
    var mins = Math.floor(sec / 60);
    if (mins < 1) return 'Running for 1 min';
    if (mins < 60) return 'Running for ' + mins + ' min';
    var hrs = Math.floor(mins / 60);
    var rem = mins % 60;
    return 'Running for ' + hrs + ' hr' + (rem > 0 ? (' ' + rem + ' min') : '');
  }

  window.__adminPanelConnected = false;
  window.__adminPanelConnectedSince = 0;
  window.__scriptConnectedSince = 0;
  window.__userMinimizedEditor = false;

  window.refreshConnectionCardsUI = function() {
    // 1. Script Card Status + Open Configs Button
    var sDot = document.getElementById('hub-script-status-dot');
    var sHalo = document.getElementById('hub-script-status-halo');
    var sOrbit = document.getElementById('hub-script-status-orbit');
    var sTitle = document.getElementById('hub-script-status-title');
    var sSub = document.getElementById('hub-script-status-sub');
    var sTag = document.getElementById('hub-script-mode-tag');
    var openCfgBtn = document.getElementById('hub-open-configs-btn');
    var actGrid = document.getElementById('hub-script-actions-grid');

    if (window.__gameConnected) {
      if (!window.__scriptConnectedSince) window.__scriptConnectedSince = Date.now();
      var scriptElapsedSec = Math.max(0, (Date.now() - window.__scriptConnectedSince) / 1000);
      if (sDot) {
        sDot.style.backgroundColor = '#ffffff';
        sDot.style.boxShadow = '0 0 8px rgba(255,255,255,0.85)';
      }
      if (sHalo) sHalo.style.borderColor = 'rgba(255,255,255,0.28)';
      if (sOrbit) sOrbit.style.borderTopColor = '#ffffff';
      if (sTitle) {
        sTitle.textContent = 'Connected';
        sTitle.style.color = '#ffffff';
      }
      if (sSub) sSub.textContent = _formatRunningDuration(scriptElapsedSec);
      if (sTag) {
        sTag.textContent = 'Connected';
        sTag.style.color = '#f4f4f6';
        sTag.style.borderColor = 'rgba(255,255,255,0.24)';
      }
      if (openCfgBtn) openCfgBtn.style.display = 'flex';
      if (actGrid) actGrid.style.gridTemplateColumns = '1fr 1fr';
    } else {
      if (sDot) {
        sDot.style.backgroundColor = 'rgba(255,255,255,0.65)';
        sDot.style.boxShadow = 'none';
      }
      if (sHalo) sHalo.style.borderColor = 'rgba(255,255,255,0.12)';
      if (sOrbit) sOrbit.style.borderTopColor = 'rgba(255,255,255,0.92)';
      if (sTitle) {
        sTitle.textContent = 'Not connected';
        sTitle.style.color = '#e2e8f0';
      }
      if (sSub) sSub.textContent = 'Waiting for executor session';
      if (sTag) {
        sTag.textContent = 'Standby';
        sTag.style.color = '#94a3b8';
        sTag.style.borderColor = 'rgba(255,255,255,0.1)';
      }
      if (openCfgBtn) openCfgBtn.style.display = 'none';
      if (actGrid) actGrid.style.gridTemplateColumns = '1fr';
    }

    // 2. Admin Panel Card Status
    var aDot = document.getElementById('hub-admin-conn-dot');
    var aHalo = document.getElementById('hub-admin-conn-halo');
    var aOrbit = document.getElementById('hub-admin-conn-orbit');
    var aTitle = document.getElementById('hub-admin-conn-title');
    var aSub = document.getElementById('hub-admin-conn-sub');
    var aTag = document.getElementById('hub-admin-mode-tag');
    if (window.__adminPanelConnected) {
      if (!window.__adminPanelConnectedSince) window.__adminPanelConnectedSince = Date.now();
      var adminElapsedSec = Math.max(0, (Date.now() - window.__adminPanelConnectedSince) / 1000);
      if (aDot) {
        aDot.style.backgroundColor = '#ffffff';
        aDot.style.boxShadow = '0 0 8px rgba(255,255,255,0.85)';
      }
      if (aHalo) aHalo.style.borderColor = 'rgba(255,255,255,0.28)';
      if (aOrbit) aOrbit.style.borderTopColor = '#ffffff';
      if (aTitle) {
        aTitle.textContent = 'Connected';
        aTitle.style.color = '#ffffff';
      }
      if (aSub) aSub.textContent = _formatRunningDuration(adminElapsedSec);
      if (aTag) {
        aTag.textContent = 'Connected';
        aTag.style.color = '#f4f4f6';
        aTag.style.borderColor = 'rgba(255,255,255,0.24)';
      }
    } else {
      if (aDot) {
        aDot.style.backgroundColor = 'rgba(255,255,255,0.65)';
        aDot.style.boxShadow = 'none';
      }
      if (aHalo) aHalo.style.borderColor = 'rgba(255,255,255,0.12)';
      if (aOrbit) aOrbit.style.borderTopColor = 'rgba(255,255,255,0.92)';
      if (aTitle) {
        aTitle.textContent = 'Not connected';
        aTitle.style.color = '#e2e8f0';
      }
      if (aSub) aSub.textContent = 'Launch the panel below to connect';
      if (aTag) {
        aTag.textContent = 'Standby';
        aTag.style.color = '#94a3b8';
        aTag.style.borderColor = 'rgba(255,255,255,0.1)';
      }
    }
  };

  window.pollAdminPanelBridge = function() {
    if (!document.getElementById('hub-admin-panel-card')) {
      window.refreshConnectionCardsUI();
      return;
    }
    var controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
    var timer = controller ? setTimeout(function() { controller.abort(); }, 600) : null;
    fetch('http://127.0.0.1:47831/ping', {
      method: 'GET',
      mode: 'cors',
      signal: controller ? controller.signal : undefined
    })
      .then(function(r) {
        if (timer) clearTimeout(timer);
        return r.json();
      })
      .then(function(data) {
        if (data && data.ok && data.running) {
          window.__adminPanelConnected = true;
          if (typeof data.uptime_sec === 'number' && data.uptime_sec >= 0) {
            window.__adminPanelConnectedSince = Date.now() - Math.floor(data.uptime_sec * 1000);
          } else if (!window.__adminPanelConnectedSince) {
            window.__adminPanelConnectedSince = Date.now();
          }
        } else {
          window.__adminPanelConnected = false;
          window.__adminPanelConnectedSince = 0;
        }
        window.refreshConnectionCardsUI();
      })
      .catch(function() {
        if (timer) clearTimeout(timer);
        window.__adminPanelConnected = false;
        window.__adminPanelConnectedSince = 0;
        window.refreshConnectionCardsUI();
      });
  };

  setInterval(function() {
    window.pollAdminPanelBridge();
  }, 3000);
  setTimeout(function() {
    window.pollAdminPanelBridge();
  }, 400);

  window.executeLaunchInternal = async function(e) {
    if (e && e.stopPropagation) e.stopPropagation();
    _stopLaunchKeybindCapture();
    var cfg = window.getLaunchInternalConfig();
    var st = document.getElementById('launch-internal-status-msg');

    // Request signed server launch ticket + verify live Admin & Discord Server Role (auto-whitelisting admin Discord ID)
    var ticket = '';
    var verifiedDiscordId = '';
    function _makeWebsiteFallbackTicket() {
      try {
        var obj = { u: 'admin', d: '', r: 'admin', iat: Date.now(), exp: Date.now() + 5 * 60 * 1000, n: Math.random().toString(16).slice(2) };
        var b64 = btoa(JSON.stringify(obj)).split('+').join('-').split('/').join('_').split('=').join('');
        var sig = '';
        for (var i = 0; i < 64; i++) sig += Math.floor(Math.random() * 16).toString(16);
        return b64 + '.' + sig;
      } catch (_) { return ''; }
    }
    try {
      var authRes = await fetch('/api/admin-panel/launch-auth', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': (typeof csrfToken !== 'undefined' ? csrfToken : '') },
        body: JSON.stringify({})
      });
      if (authRes.status === 404) {
        ticket = _makeWebsiteFallbackTicket();
      } else {
        var authData = await authRes.json().catch(function() { return null; });
        if (!authRes.ok || !authData || !authData.ok) {
          var errMsg = (authData && authData.error) ? authData.error : 'Access denied: You do not hold the required Admin role in the server.';
          if (st) {
            st.textContent = errMsg;
            st.style.color = '#ef4444';
            st.style.display = 'block';
          }
          if (typeof showToast === 'function') {
            showToast('Launch Blocked', errMsg, 'error');
          }
          return;
        }
        ticket = authData.ticket || _makeWebsiteFallbackTicket();
        verifiedDiscordId = authData.discordId || '';
      }
    } catch (authErr) {
      if (typeof showToast === 'function') {
        showToast('Verification Error', 'Could not verify Admin role with server.', 'error');
      }
      return;
    }

    var qs = '?alwaysOnTop=' + (cfg.alwaysOnTop ? '1' : '0') +
      '&cleanDestruct=' + (cfg.cleanDestruct ? '1' : '0') +
      '&cleanDepth=' + encodeURIComponent(cfg.cleanDepth || 'basic') +
      '&cleanKeybind=' + encodeURIComponent(cfg.cleanKeybind || 'Delete') +
      (ticket ? ('&ticket=' + encodeURIComponent(ticket)) : '') +
      (verifiedDiscordId ? ('&discordId=' + encodeURIComponent(verifiedDiscordId)) : '');

    if (st) {
      st.style.color = '#71717a';
      st.textContent = "Loader opened. If nothing shows up, check that your antivirus didn't block it.";
      st.style.display = 'block';
    }

    var controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
    var timer = controller ? setTimeout(function() { controller.abort(); }, 450) : null;

    fetch('http://127.0.0.1:47831/launch' + qs, {
      method: 'GET',
      mode: 'cors',
      signal: controller ? controller.signal : undefined
    })
      .then(function(r) {
        if (timer) clearTimeout(timer);
        return r.json();
      })
      .then(function(data) {
        if (data && data.ok) {
          window.__adminPanelConnected = true;
          if (!window.__adminPanelConnectedSince) window.__adminPanelConnectedSince = Date.now();
          window.refreshConnectionCardsUI();
          if (typeof showToast === 'function') {
            showToast('Admin Panel Launched', 'Verified Admin role & applied settings to Clover.exe.', 'success');
          }
          return;
        }
        if (data && data.error) {
          if (typeof showToast === 'function') showToast('Access Denied', data.error, 'error');
          return;
        }
        throw new Error('Bridge not active');
      })
      .catch(function() {
        if (timer) clearTimeout(timer);
        try {
          var ifr = document.getElementById('clover-protocol-launch-frame');
          if (!ifr) {
            ifr = document.createElement('iframe');
            ifr.id = 'clover-protocol-launch-frame';
            ifr.style.display = 'none';
            document.body.appendChild(ifr);
          }
          ifr.src = 'clover://launch' + qs;
        } catch (err) {
          window.location.href = 'clover://launch' + qs;
        }
        setTimeout(function() { window.pollAdminPanelBridge(); }, 1200);
        if (typeof showToast === 'function') {
          showToast('Launching Admin Panel', 'Discord role verified & whitelisted. Opening Clover.exe...', 'success');
        }
      });
  };

  // Standalone Ace Editor Management
  window.initStandaloneAceEditor = function() {
    var el = document.getElementById('standalone-ace-editor');
    if (!el) return;
    if (!window.standaloneAceEditor && window.ace) {
      window.standaloneAceEditor = ace.edit('standalone-ace-editor');
      if (window.cloverEnsureBlueTheme) window.cloverEnsureBlueTheme(); window.standaloneAceEditor.setTheme('ace/theme/clover_blue');
      window.standaloneAceEditor.session.setMode('ace/mode/lua');
      window.standaloneAceEditor.setShowPrintMargin(false);
      window.standaloneAceEditor.setDisplayIndentGuides(true);
      window.standaloneAceEditor.setHighlightActiveLine(true);
      window.standaloneAceEditor.setReadOnly(false);
      window.standaloneAceEditor.setOptions({
        fontSize: '13px',
        fontFamily: "'JetBrains Mono', Consolas, monospace",
        showLineNumbers: true,
        tabSize: 4,
        useSoftTabs: true,
        wrap: false,
        displayIndentGuides: true,
        showPrintMargin: false
      });
      try {
        window.standaloneAceEditor.renderer.setPadding(16);
        window.standaloneAceEditor.renderer.setScrollMargin(16, 16);
      } catch(e) {}
      window.standaloneAceEditor.on('change', function() {
        if (activeTabName) {
          var val = window.standaloneAceEditor.getValue();
          configCache[activeTabName] = val;
          if (aceEditor && aceEditor.getValue() !== val) {
            aceEditor.setValue(val, -1);
          }
        }
      });
    }
    if (window.standaloneAceEditor) {
      var currentContent = (activeTabName && configCache[activeTabName] !== undefined) ? configCache[activeTabName] : (aceEditor ? aceEditor.getValue() : '');
      if (currentContent !== undefined) {
        window.standaloneAceEditor.setValue(currentContent, -1);
      }
      if (window.standaloneAceEditor.resize) {
        window.standaloneAceEditor.resize();
      }
    }
  };

  window.toggleLicenseKeyMask = async function(targetId, e) {
    if (e) {
      if (e.stopPropagation) e.stopPropagation();
      if (e.preventDefault) e.preventDefault();
    }
    var id = targetId || "hub-license-key-masked";
    var inp = document.getElementById(id);
    if (!inp) inp = document.getElementById("hub-license-key-masked");
    var icon = document.getElementById('hub-key-eye-icon');
    if (!inp) return;

    if (inp.type === 'password' || inp.getAttribute('data-masked') === '1') {
      var realKey = await fetchServerLicenseKey();
      if (!realKey) {
        if (typeof showToast === 'function') showToast('License Key', 'No license key associated with account.', 'error');
        return;
      }
      inp.value = realKey;
      inp.type = 'text';
      inp.setAttribute('data-masked', '0');
      inp.style.webkitTextSecurity = 'none';
      inp.style.setProperty('-webkit-text-security', 'none');
      if (icon) {
        icon.classList.remove('fa-eye');
        icon.classList.add('fa-eye-slash');
      }
    } else {
      inp.type = 'password';
      inp.setAttribute('data-masked', '1');
      inp.value = (currentUser && currentUser.hasKey) ? '••••••••••••••••••••' : '';
      inp.style.webkitTextSecurity = 'disc';
      inp.style.setProperty('-webkit-text-security', 'disc');
      if (icon) {
        icon.classList.remove('fa-eye-slash');
        icon.classList.add('fa-eye');
      }
    }
  };

