  // Merged Overview Game Detection & Live Cloud Config State
  window.__gameConnected = false;
  window.updateExecutedGameInfo = function(opts) {
    opts = opts || {};
    var placeId = String(opts.placeId || '').replace(/\D/g, '');
    function applyGameMeta(name, iconUrl, pid) {
      var t1 = document.getElementById('hub-loaded-game-title');
      var t2 = document.getElementById('configs-loaded-game-title');
      var i1 = document.getElementById('hub-loaded-game-icon');
      var i2 = document.getElementById('configs-loaded-game-icon');
      var s1 = document.getElementById('hub-loaded-game-sub');
      var s2 = document.getElementById('configs-loaded-game-sub');
      if (name) {
        if (t1) t1.textContent = name;
        if (t2) t2.textContent = name;
      }
      if (iconUrl) {
        if (i1) i1.src = iconUrl;
        if (i2) i2.src = iconUrl;
      }
      var subTxt = pid ? ('Place ID ' + pid) : '';
      if (s1) { s1.textContent = subTxt; s1.style.display = subTxt ? 'inline-flex' : 'none'; }
      if (s2) { s2.textContent = subTxt; s2.style.display = subTxt ? 'inline-flex' : 'none'; }
    }
    if (opts.gameName || opts.gameIcon) {
      applyGameMeta(opts.gameName || 'In-Game Session', opts.gameIcon || '', placeId);
    } else if (!placeId) {
      applyGameMeta('In-Game Session', '', '');
    }
    if (!placeId) return;
    fetch('/api/roblox-game/' + encodeURIComponent(placeId))
      .then(function(r) { return r.json(); })
      .then(function(data) {
        if (data && (data.name || data.iconUrl)) {
          applyGameMeta(opts.gameName || data.name, opts.gameIcon || data.iconUrl, data.placeId || placeId);
        }
      })
      .catch(function() {});
  };

