  window.toggleGameConnectionState = function(forceState, gameOpts) {
    var wasConnected = Boolean(window.__gameConnected);
    if (typeof forceState === 'boolean') {
      window.__gameConnected = forceState;
    } else {
      window.__gameConnected = !window.__gameConnected;
    }

    var opts = gameOpts || {};
    var waitingView = document.getElementById('hub-overview-waiting-view');
    var unlockedView = document.getElementById('hub-overview-unlocked-view');

    if (window.__gameConnected) {
      if (!wasConnected || !window.__scriptConnectedSince) {
        window.__scriptConnectedSince = opts.connectedSince || Date.now();
      }
      if (typeof window.updateExecutedGameInfo === 'function') {
        window.updateExecutedGameInfo(opts);
      }
      window.refreshConnectionCardsUI();

      // If the user clicked the back arrow out of the Luau canvas table, keep them on Overview and show Open Configs button
      if (window.__userMinimizedEditor && !opts.userExplicitOpen) {
        return;
      }

      document.body.classList.add('editor-expanded');
      if (waitingView) waitingView.style.display = 'none';
      if (unlockedView) unlockedView.style.display = 'flex';

      setTimeout(function() {
        if (!aceEditor) initAceEditor();
        if (aceEditor && aceEditor.resize) aceEditor.resize();
        if (typeof renderTabs === 'function') renderTabs();
        if (typeof fetchConfigsList === 'function') fetchConfigsList();
        var curName = (typeof activeTabName !== 'undefined' && activeTabName) ? activeTabName : 'Default';
        var loadedLabel = document.getElementById('hub-loaded-config-name');
        if (loadedLabel) loadedLabel.textContent = curName + '.lua';
      }, 50);

      if (!wasConnected && typeof showToast === 'function') {
        showToast('Game Connected', 'Roblox executor detected. Config Editor unlocked.', 'success');
      }
    } else {
      window.__userMinimizedEditor = false;
      window.__scriptConnectedSince = 0;
      document.body.classList.remove('editor-expanded');
      if (waitingView) waitingView.style.display = 'flex';
      if (unlockedView) unlockedView.style.display = 'none';
      window.refreshConnectionCardsUI();

      if (wasConnected && typeof showToast === 'function') {
        showToast('Game Disconnected', 'Session disconnected. Waiting for next executor ping.', 'info');
      }
    }
  };

