  window.__confirmTuffResetConfigNow = function() {
    var defCfg = (defaultPresets && defaultPresets['default']) ? defaultPresets['default'] : '';
    if (defCfg && typeof activeTabName !== 'undefined' && activeTabName) {
      configCache[activeTabName] = defCfg;
      if (typeof setEditorValue === 'function') setEditorValue(defCfg);
      if (typeof isScratchTabName === 'function' && isScratchTabName(activeTabName)) {
        try {
          var scratchMap = JSON.parse(uGet('clover_scratch_cache') || '{}');
          scratchMap[activeTabName] = defCfg;
          uSet('clover_scratch_cache', JSON.stringify(scratchMap));
        } catch (e) {}
      }
    } else if (typeof loadTabContent === 'function') {
      loadTabContent(activeTabName);
    }
    var lbl = document.getElementById('hub-active-config-label');
    if (lbl) lbl.textContent = 'DEFAULT';
    var s1 = document.getElementById('hub-tuff-session-status');
    if (s1) { s1.textContent = 'reset to default'; s1.style.color = '#f87171'; }
    var s2 = document.getElementById('configs-tuff-session-status');
    if (s2) { s2.textContent = 'reset to default'; s2.style.color = '#f87171'; }
    window.closeTuffResetModal();
    if (typeof showToast === 'function') {
      showToast('Reset', 'Config reset to default table.', 'info');
    }
  };

