      amber:     { primary: '#f59e0b', secondary: '#fbbf24', hue: 38,  sat: 92, lightness: 50 },
      obsidian:  { primary: '#f8fafc', secondary: '#cbd5e1', hue: 210, sat: 20, lightness: 96 },
